    assert bfs([(0, 1), (1, 2), (2, 3)], 0)[3] == 3 and max_flow({(0, 1): 3, (0, 2): 2, (1, 3): 2, (2, 3): 3, (1, 2): 1}, 0, 3) == 5
    assert topo_sort([(0, 1), (1, 2), (0, 2)]) == [0, 1, 2] and scc([(0, 1), (1, 2), (2, 0), (2, 3)]) == [[0, 1, 2], [3]]
    assert bipartite_matching([0, 1, 2], [(0, 'a'), (0, 'b'), (1, 'a'), (2, 'b')])[0] == 2 and is_bipartite([(0, 1), (1, 2), (2, 3), (3, 0)]) and not is_bipartite([(0, 1), (1, 2), (2, 0)])
    K4 = list(itertools.combinations(range(4), 2)); assert chromatic_number(4, K4) == 4 and spanning_trees(4, K4) == 16 and chromatic_number(5, [(i, (i + 1) % 5) for i in range(5)]) == 3
    assert euler_circuit([(0, 1), (1, 2), (2, 0)]) is not None and euler_circuit([(0, 1), (1, 2)]) is None
