@teste('cat')
def _t():
    P = poset_cat([1, 2, 3, 6], lambda a, b: b % a == 0); assert P.check() == [] and P.initial() == [1] and P.terminal() == [6]
    assert [p for p, *_ in P.products(2, 3)] == [1] and [p for p, *_ in P.coproducts(2, 3)] == [6]
    Z3 = monoid_cat([0, 1, 2], lambda g, f: (g + f) % 3, 0); assert Z3.check() == [] and all(Z3.is_iso(m) for m in Z3.mor)
    Fc = free_category(['a', 'b', 'c', 'd'], {'f': ('a', 'b'), 'g': ('b', 'd'), 'h': ('a', 'c'), 'k': ('c', 'd')}); assert Fc.check() == [] and len(Fc.mor) == 10
    C = poset_cat([0, 1, 2, 3, 4], lambda a, b: a <= b); D = poset_cat([0, 1, 2], lambda a, b: a <= b)
    F = poset_functor(C, D, lambda c: c // 2); G = poset_functor(D, C, lambda d: min(2 * d + 1, 4)); assert F.check() == [] and G.check() == [] and thin_adjoint(F, G) and not thin_adjoint(G, F)
    eta = {c: (c, min(2 * (c // 2) + 1, 4)) for c in C.ob}; eps = {d: (min(2 * d + 1, 4) // 2, d) for d in D.ob}; assert adjunction_triangles(F, G, eta, eps)
    Cc = poset_cat([0, 1, 2], lambda a, b: a <= b); I = lambda S: {x: x for x in S}
    SF = SetFunctor(Cc, {0: ('a',), 1: ('a', 'b'), 2: ('a', 'b')}, {(0, 0): I('a'), (1, 1): I('ab'), (2, 2): I('ab'), (0, 1): {'a': 'a'}, (1, 2): I('ab'), (0, 2): {'a': 'a'}})
    assert SF.check() and all(yoneda_check(Cc, SF, A_) for A_ in Cc.ob)
    lst_unit = lambda x: [x]; lst_bind = lambda m, f: [y for x in m for y in f(x)]; fs = [lambda x: [x, x + 1], lambda x: [], lambda x: [x * 2]]
    assert monad_laws(lst_unit, lst_bind, [1, 2], [[1, 2], [], [3]], fs) and not monad_laws(lst_unit, lambda m, f: [y for x in m[:1] for y in f(x)], [1], [[1, 2]], fs)
    X, Y = frozenset({1, 2, 3}), frozenset({'a', 'b'}); Pr, p1, p2 = fs_product(X, Y); f = {1: 'a', 2: 'b', 3: 'a'}; g = {1: 1, 2: 2, 3: 3}; h = fs_pairing(g, f)
    assert len(Pr) == 6 and fs_compose(p1, h) == g and fs_compose(p2, h) == f and len(fs_exponential(Y, X)) == 9 and len(fs_coproduct(X, Y)[0]) == 5
    assert len(fs_equalizer(f, {1: 'a', 2: 'a', 3: 'b'})[0]) == 1 and len(fs_pullback(f, {'a': 'a', 'b': 'a'})[0]) == 4 and fs_characteristic({1}, X)[1]

