def selftest(verbose=True):
    res = {}; t00 = time.time()
    for area in sorted(TESTES):
        t0 = time.time()
        try: r = TESTES[area](); res[area] = ("pulado" if r == "pulado" else "ok", time.time() - t0, None)
        except Exception as e:
            import traceback; res[area] = ("FALHA", time.time() - t0, traceback.format_exc(limit=3))
        if verbose:
            st, dt, tb = res[area]; cor = LM if st == "ok" else AM if st == "pulado" else RD
            print(f"{CY}{area:5}{RS} {cor}{st:6}{RS} {dt:6.2f}s  {MG}{len(REG[area])} ops{RS}")
            if tb: print(tb)
    nops = sum(len(v) for v in REG.values())
    if verbose: print(f"{AM}{len(REG)} áreas · {nops} operações · {time.time() - t00:.1f}s{RS}")
    return res

# ═════════════════════════════ LACUNAS ASSUMIDAS (honestidade) ═════════════════════════════
# Não cobertos: álgebra comutativa além de Gröbner lex; geometria algébrica/esquemas; K-teoria; homotopia superior
# e ∞-categorias; teoria de representações geral; EDP em 3D/malhas adaptativas; integração simbólica geral (Risch);
# provadores de teoremas e verificação formal; teoria analítica dos números profunda; teoria de modelos.
# Categorias: apenas finitas (força bruta) + FinSet; sem categorias grandes nem limites gerais.

# ═════════════════════════════ NATIVO: compilador x86-64 (fusão de calculo_nativo.py) ═════════════════════════════
import ctypes.util as _cu, mmap as _mm, platform as _pf, struct as _st

def _nn_c(v): return ('c', float(v))
_NZ, _NU, _NX = _nn_c(0), _nn_c(1), ('x',)

def _nn_add(a, b):
    if a == _NZ: return b
    if b == _NZ: return a
    if a[0] == b[0] == 'c': return _nn_c(a[1] + b[1])
    return ('+', a, b)
def _nn_neg(a):
    if a[0] == 'c': return _nn_c(-a[1])
    if a[0] == 'n': return a[1]
    return ('n', a)
def _nn_sub(a, b):
    if b == _NZ: return a
    if a == _NZ: return _nn_neg(b)
    if a[0] == b[0] == 'c': return _nn_c(a[1] - b[1])
    return ('-', a, b)
def _nn_mul(a, b):
    if a == _NZ or b == _NZ: return _NZ
    if a == _NU: return b
    if b == _NU: return a
    if a[0] == b[0] == 'c': return _nn_c(a[1] * b[1])
    return ('*', a, b)
def _nn_div(a, b):
    if a == _NZ: return _NZ
    if b == _NU: return a
    if a[0] == b[0] == 'c' and b[1] != 0: return _nn_c(a[1] / b[1])
    return ('/', a, b)
def _nn_pw(a, n):
    if n == 0: return _NU
    if n == 1: return a
    if a[0] == 'c': return _nn_c(a[1] ** n)
    return ('p', a, int(n))

_NAT_FUNCS = ('sin', 'cos', 'tan', 'exp', 'log', 'sqrt')
_NAT_CONST = {'pi': math.pi, 'e': math.e}

def nat_parse(src):
    """Texto -> AST interna. Aceita ^ como potência, funções de _NAT_FUNCS, pi e e."""
    def go(n):
        if isinstance(n, ast.Expression): return go(n.body)
        if isinstance(n, ast.Constant): return _nn_c(n.value)
        if isinstance(n, ast.Name):
            if n.id == 'x': return _NX
            if n.id in _NAT_CONST: return _nn_c(_NAT_CONST[n.id])
            raise ValueError(f"símbolo desconhecido: {n.id}")
        if isinstance(n, ast.UnaryOp):
            if isinstance(n.op, ast.USub): return _nn_neg(go(n.operand))
            if isinstance(n.op, ast.UAdd): return go(n.operand)
        if isinstance(n, ast.BinOp):
            a, b, o = go(n.left), go(n.right), type(n.op)
            if o is ast.Add: return _nn_add(a, b)
            if o is ast.Sub: return _nn_sub(a, b)
            if o is ast.Mult: return _nn_mul(a, b)
            if o is ast.Div: return _nn_div(a, b)
            if o is ast.Pow:
                if b[0] == 'c' and float(b[1]).is_integer() and abs(b[1]) <= 64: return _nn_pw(a, int(b[1]))
                return ('f', 'exp', _nn_mul(b, ('f', 'log', a)))
        if isinstance(n, ast.Call) and isinstance(n.func, ast.Name) and n.func.id in _NAT_FUNCS and len(n.args) == 1:
            return ('f', n.func.id, go(n.args[0]))
        raise ValueError("construção não suportada")
    return go(ast.parse(src.replace('^', '**'), mode='eval'))

def nat_show(n):
    t = n[0]
    if t == 'c': return f"{n[1]:g}"
    if t == 'x': return 'x'
    if t in ('+', '-', '*', '/'): return f"({nat_show(n[1])} {t} {nat_show(n[2])})"
    if t == 'n': return f"-{nat_show(n[1])}"
    if t == 'p': return f"{nat_show(n[1])}^{n[2]}"
    return f"{n[1]}({nat_show(n[2])})"

def nat_d(n):
    """Derivada simbólica em x."""
    t = n[0]
    if t == 'c': return _NZ
    if t == 'x': return _NU
    if t == '+': return _nn_add(nat_d(n[1]), nat_d(n[2]))
    if t == '-': return _nn_sub(nat_d(n[1]), nat_d(n[2]))
    if t == 'n': return _nn_neg(nat_d(n[1]))
    if t == '*': return _nn_add(_nn_mul(nat_d(n[1]), n[2]), _nn_mul(n[1], nat_d(n[2])))
    if t == '/': return _nn_div(_nn_sub(_nn_mul(nat_d(n[1]), n[2]), _nn_mul(n[1], nat_d(n[2]))), _nn_pw(n[2], 2))
    if t == 'p': return _nn_mul(_nn_mul(_nn_c(n[2]), _nn_pw(n[1], n[2] - 1)), nat_d(n[1]))
    nome, a = n[1], n[2]; da = nat_d(a)
    if nome == 'sin': return _nn_mul(('f', 'cos', a), da)
    if nome == 'cos': return _nn_neg(_nn_mul(('f', 'sin', a), da))
    if nome == 'tan': return _nn_div(da, _nn_pw(('f', 'cos', a), 2))
    if nome == 'exp': return _nn_mul(('f', 'exp', a), da)
    if nome == 'log': return _nn_div(da, a)
    if nome == 'sqrt': return _nn_div(da, _nn_mul(_nn_c(2), ('f', 'sqrt', a)))
    raise ValueError(nome)

def _nat_libm():
    for nome in (_cu.find_library('m'), 'libm.so.6', 'libm.dylib', None):
        try: return ctypes.CDLL(nome)
        except Exception: pass
    raise OSError("libm indisponível")

def _nat_emit(root):
    """Gera bytes x86-64 (SysV, SSE2). Entrada em xmm0 salva em [rbp-8]; saída em xmm0."""
    lib, code = _nat_libm(), bytearray()
    E = lambda *b: code.extend(b)
    def push(): E(0x48, 0x83, 0xEC, 0x08, 0xF2, 0x0F, 0x11, 0x04, 0x24)
    def pop():  E(0xF2, 0x0F, 0x10, 0x04, 0x24, 0x48, 0x83, 0xC4, 0x08)
    def expande(a, n):
        if n == 0: return ('c', 1.0)
        if n < 0: return ('/', ('c', 1.0), expande(a, -n))
        if n == 1: return a
        if n % 2 == 0:
            h = expande(a, n // 2); return ('*', h, h)
        return ('*', a, expande(a, n - 1))
    def gen(n):
        t = n[0]
        if t == 'c':
            E(0x48, 0xB8); E(*_st.pack('<d', n[1])); E(0x66, 0x48, 0x0F, 0x6E, 0xC0)
        elif t == 'x':
            E(0xF2, 0x0F, 0x10, 0x45, 0xF8)
        elif t in ('+', '-', '*', '/'):
            gen(n[1]); push(); gen(n[2]); E(0xF2, 0x0F, 0x10, 0xC8); pop()
            E(0xF2, 0x0F, {'+': 0x58, '-': 0x5C, '*': 0x59, '/': 0x5E}[t], 0xC1)
        elif t == 'n':
            gen(n[1]); E(0x48, 0xB8); E(*_st.pack('<Q', 1 << 63)); E(0x66, 0x48, 0x0F, 0x6E, 0xC8, 0x66, 0x0F, 0x57, 0xC1)
        elif t == 'p':
            gen(expande(n[1], n[2]))
        else:
            gen(n[2]); addr = ctypes.cast(getattr(lib, n[1]), ctypes.c_void_p).value
            E(0x48, 0xB8); E(*_st.pack('<Q', addr))
            E(0x53, 0x48, 0x89, 0xE3, 0x48, 0x83, 0xE4, 0xF0)
            E(0xFF, 0xD0)
            E(0x48, 0x89, 0xDC, 0x5B)
    E(0x55, 0x48, 0x89, 0xE5, 0x48, 0x83, 0xEC, 0x10, 0xF2, 0x0F, 0x11, 0x45, 0xF8)
    gen(root)
    E(0x48, 0x89, 0xEC, 0x5D, 0xC3)
    return bytes(code)

def nat_ev(n, x):
    """Avaliador interpretado (referência e fallback)."""
    t = n[0]
    try:
        if t == 'c': return n[1]
        if t == 'x': return x
        if t == '+': return nat_ev(n[1], x) + nat_ev(n[2], x)
        if t == '-': return nat_ev(n[1], x) - nat_ev(n[2], x)
        if t == '*': return nat_ev(n[1], x) * nat_ev(n[2], x)
        if t == '/': return nat_ev(n[1], x) / nat_ev(n[2], x)
        if t == 'n': return -nat_ev(n[1], x)
        if t == 'p': return nat_ev(n[1], x) ** n[2]
        return getattr(math, n[1])(nat_ev(n[2], x))
    except (ZeroDivisionError, ValueError, OverflowError):
        return math.nan

class NatFn:
    """f(x) compilada. .nativo=True => código de máquina gerado em runtime; senão, interpretador."""
    def __init__(s, node):
        s.node, s.nativo, s.codigo = node, False, b''
        try:
            if _pf.machine().lower() not in ('x86_64', 'amd64') or sys.platform == 'win32':
                raise OSError("sem backend nativo")
            s.codigo = _nat_emit(node)
            m = _mm.mmap(-1, len(s.codigo), prot=_mm.PROT_READ | _mm.PROT_WRITE | _mm.PROT_EXEC)
            m.write(s.codigo)
            buf = ctypes.c_char.from_buffer(m)
            s._f = ctypes.CFUNCTYPE(ctypes.c_double, ctypes.c_double)(ctypes.addressof(buf))
            s._keep, s.nativo = (m, buf), True
        except Exception:
            s._f = lambda x: nat_ev(node, x)
    def __call__(s, x): return s._f(float(x))

@op('nat')
def compilar(expr):
    """Texto -> (AST, NatFn). Equivalente ao antigo def calculo."""
    n = nat_parse(expr) if isinstance(expr, str) else expr
    return n, NatFn(n)

@op('nat')
def derivada(expr, ordem=1):
    n = nat_parse(expr) if isinstance(expr, str) else expr
    for _ in range(ordem): n = nat_d(n)
    return {'simbolica': nat_show(n), 'f': NatFn(n)}

@op('nat')
def avaliar(expr, x): return NatFn(nat_parse(expr))(x)

@op('nat')
def codigo_maquina(expr):
    """Bytes x86-64 gerados para a expressão (vazio se a arquitetura não for suportada)."""
    try: return _nat_emit(nat_parse(expr))
    except Exception: return b''

# ═════════════════════════════ MATRIZES (extensão) ═════════════════════════════
@op('mat')
def kron_sum(A, B):
    A, B = np.asarray(A, float), np.asarray(B, float)
    return np.kron(A, np.eye(B.shape[0])) + np.kron(np.eye(A.shape[0]), B)

@op('mat')
def sylvester(A, B, Q):
    """Resolve AX + XB = Q (vetorização por linhas)."""
    A, B, Q = (np.asarray(M, float) for M in (A, B, Q))
    M = np.kron(A, np.eye(B.shape[0])) + np.kron(np.eye(A.shape[0]), B.T)
    return np.linalg.solve(M, Q.reshape(-1)).reshape(Q.shape)

@op('mat')
def lyapunov(A, Q):
    """Resolve AX + XAᵀ = Q."""
    return sylvester(A, np.asarray(A, float).T, Q)

@op('mat')
def sqrtm(A):
    w, V = np.linalg.eig(np.asarray(A, complex)); return V @ np.diag(np.sqrt(w)) @ np.linalg.inv(V)

@op('mat')
def logm(A):
    w, V = np.linalg.eig(np.asarray(A, complex)); return V @ np.diag(np.log(w)) @ np.linalg.inv(V)

@op('mat')
def matrix_power(A, k):
    A = np.asarray(A, float)
    if k < 0: A, k = np.linalg.inv(A), -k
    R = np.eye(A.shape[0])
    while k:
        if k & 1: R = R @ A
        A = A @ A; k >>= 1
    return R

@op('mat')
def hessenberg(A):
    """Forma de Hessenberg superior por reflexões de Householder. Retorna (H, Q) com A = Q H Qᵀ."""
    H = np.array(A, float); n = len(H); Q = np.eye(n)
    for k in range(n - 2):
        x = H[k + 1:, k].copy(); alpha = -math.copysign(np.linalg.norm(x), x[0] if x[0] != 0 else 1.0)
        v = x; v[0] -= alpha; nv = np.linalg.norm(v)
        if nv == 0: continue
        v = v / nv; P = np.eye(n); P[k + 1:, k + 1:] -= 2 * np.outer(v, v)
        H = P @ H @ P; Q = Q @ P
    return H, Q

@op('mat')
def schur_qr(A, it=500):
    """Forma de Schur complexa por QR com deslocamento de Rayleigh (aproximada). Retorna (T, Q)."""
    T = np.array(A, complex); n = len(T); Q = np.eye(n, dtype=complex)
    for _ in range(it):
        mu = T[-1, -1]; q, r = np.linalg.qr(T - mu * np.eye(n)); T = r @ q + mu * np.eye(n); Q = Q @ q
    return T, Q

@op('mat')
def jacobi_eig(S, tol=1e-12, maxit=20000):
    """Autovalores/autovetores de matriz simétrica por rotações de Jacobi clássicas."""
    A = np.array(S, float); n = len(A); V = np.eye(n)
    for _ in range(maxit):
        off = A - np.diag(np.diag(A)); i, j = np.unravel_index(np.argmax(np.abs(off)), off.shape)
        if abs(A[i, j]) < tol: break
        th = (A[j, j] - A[i, i]) / (2 * A[i, j])
        t = (1.0 if th == 0 else math.copysign(1.0, th)) / (abs(th) + math.sqrt(th * th + 1))
        c = 1 / math.sqrt(t * t + 1); s = t * c
        R = np.eye(n); R[i, i] = R[j, j] = c; R[i, j] = s; R[j, i] = -s
        A = R.T @ A @ R; V = V @ R
    return np.diag(A).copy(), V

@op('mat')
def givens(a, b):
    r = math.hypot(a, b)
    if r == 0: return np.eye(2)
    return np.array([[a / r, b / r], [-b / r, a / r]])

@op('mat')
def householder_vector(x):
    x = np.asarray(x, float); v = x.copy(); s = math.copysign(np.linalg.norm(x), x[0] or 1.0); v[0] += s
    return v / np.linalg.norm(v)

@op('mat')
def toeplitz(c, r): return np.array([[c[i - j] if i >= j else r[j - i] for j in range(len(r))] for i in range(len(c))], float)

@op('mat')
def hankel(c, r=None):
    c = list(c); r = list(r) if r is not None else [0] * len(c)
    return np.array([[(c[i + j] if i + j < len(c) else r[i + j - len(c) + 1]) for j in range(len(c))] for i in range(len(c))], float)

@op('mat')
def circulant(c): c = np.asarray(c, float); return np.array([np.roll(c, k) for k in range(len(c))])

@op('mat')
def vandermonde(x, n=None):
    x = np.asarray(x, float); n = n or len(x); return np.vander(x, n, increasing=True)

@op('mat')
def companion(coeffs):
    """Matriz companheira de p(x)=c0 + c1 x + ... + x^n (coeficientes baixo→alto, mônico)."""
    c = np.asarray(coeffs, float); n = len(c) - 1; C = np.zeros((n, n))
    C[1:, :-1] = np.eye(n - 1); C[:, -1] = -c[:-1] / c[-1]; return C

@op('mat')
def jacobi_iteration(A, b, it=1000, x0=None):
    A, b = np.asarray(A, float), np.asarray(b, float); D = np.diag(A); R = A - np.diag(D)
    x = np.zeros_like(b) if x0 is None else np.asarray(x0, float)
    for _ in range(it): x = (b - R @ x) / D
    return x

@op('mat')
def gauss_seidel(A, b, it=1000, x0=None):
    A, b = np.asarray(A, float), np.asarray(b, float); n = len(b)
    x = np.zeros_like(b) if x0 is None else np.asarray(x0, float)
    for _ in range(it):
        for i in range(n): x[i] = (b[i] - A[i, :i] @ x[:i] - A[i, i + 1:] @ x[i + 1:]) / A[i, i]
    return x

@op('mat')
def sor(A, b, w=1.2, it=1000, x0=None):
    A, b = np.asarray(A, float), np.asarray(b, float); n = len(b)
    x = np.zeros_like(b) if x0 is None else np.asarray(x0, float)
    for _ in range(it):
        for i in range(n):
            gs = (b[i] - A[i, :i] @ x[:i] - A[i, i + 1:] @ x[i + 1:]) / A[i, i]; x[i] = (1 - w) * x[i] + w * gs
    return x

@op('mat')
def arnoldi(A, b, k):
    """Base ortonormal de Krylov K_k(A,b) e a matriz de Hessenberg Hk."""
    A, b = np.asarray(A, float), np.asarray(b, float); n = len(b)
    Q = np.zeros((n, k + 1)); H = np.zeros((k + 1, k)); Q[:, 0] = b / np.linalg.norm(b)
    for j in range(k):
        w = A @ Q[:, j]
        for i in range(j + 1): H[i, j] = Q[:, i] @ w; w = w - H[i, j] * Q[:, i]
        H[j + 1, j] = np.linalg.norm(w)
        if H[j + 1, j] < 1e-14: return Q[:, :j + 1], H[:j + 1, :j]
        Q[:, j + 1] = w / H[j + 1, j]
    return Q[:, :k], H[:k, :k]

@op('mat')
def lanczos(A, b, k):
    """Tridiagonalização de Lanczos (A simétrica): retorna (alphas, betas, Q)."""
    A = np.asarray(A, float); b = np.asarray(b, float); n = len(b)
    Q = np.zeros((n, k)); al = np.zeros(k); be = np.zeros(max(k - 1, 0)); Q[:, 0] = b / np.linalg.norm(b); beta = 0.0; qprev = np.zeros(n)
    for j in range(k):
        w = A @ Q[:, j] - beta * qprev; al[j] = Q[:, j] @ w; w = w - al[j] * Q[:, j]
        beta = np.linalg.norm(w)
        if j < k - 1:
            be[j] = beta
            if beta < 1e-14: return al[:j + 1], be[:j], Q[:, :j + 1]
            qprev = Q[:, j]; Q[:, j + 1] = w / beta
    return al, be, Q

@op('mat')
def polar(A):
    """Decomposição polar A = U P, U ortogonal, P simétrica semidefinida positiva."""
    U_, s, Vt = np.linalg.svd(np.asarray(A, float)); U = U_ @ Vt; P = Vt.T @ np.diag(s) @ Vt; return U, P

@op('mat')
def cayley(A):
    A = np.asarray(A, float); I = np.eye(len(A)); return np.linalg.solve(I + A, I - A)

@op('mat')
def generalized_eig(A, B):
    return np.linalg.eig(np.linalg.solve(np.asarray(B, float), np.asarray(A, float)))

@op('mat')
def norms(A):
    A = np.asarray(A, float); s = np.linalg.svd(A, compute_uv=False)
    return {"frobenius": float(np.linalg.norm(A, 'fro')), "espectral": float(s[0]), "nuclear": float(s.sum()),
            "1": float(np.linalg.norm(A, 1)), "inf": float(np.linalg.norm(A, np.inf))}

@op('mat')
def strassen(A, B, leaf=32):
    A, B = np.asarray(A, float), np.asarray(B, float); n = A.shape[0]
    if n <= leaf or n % 2: return A @ B
    h = n // 2; A11, A12, A21, A22 = A[:h, :h], A[:h, h:], A[h:, :h], A[h:, h:]
    B11, B12, B21, B22 = B[:h, :h], B[:h, h:], B[h:, :h], B[h:, h:]
    M1 = strassen(A11 + A22, B11 + B22, leaf); M2 = strassen(A21 + A22, B11, leaf); M3 = strassen(A11, B12 - B22, leaf)
    M4 = strassen(A22, B21 - B11, leaf); M5 = strassen(A11 + A12, B22, leaf); M6 = strassen(A21 - A11, B11 + B12, leaf)
    M7 = strassen(A12 - A22, B21 + B22, leaf)
    C = np.empty((n, n)); C[:h, :h] = M1 + M4 - M5 + M7; C[:h, h:] = M3 + M5; C[h:, :h] = M2 + M4; C[h:, h:] = M1 - M2 + M3 + M6
    return C

@op('mat')
def so3_exp(w):
    """Exponencial de vetor de rotação (fórmula de Rodrigues)."""
    w = np.asarray(w, float); th = np.linalg.norm(w)
    K = np.array([[0, -w[2], w[1]], [w[2], 0, -w[0]], [-w[1], w[0], 0]])
    if th < 1e-12: return np.eye(3) + K
    K = K / th; return np.eye(3) + math.sin(th) * K + (1 - math.cos(th)) * K @ K

@op('mat')
def so3_log(R):
    c = np.clip((np.trace(R) - 1) / 2, -1, 1); th = math.acos(c)
    if th < 1e-12: return np.zeros(3)
    v = np.array([R[2, 1] - R[1, 2], R[0, 2] - R[2, 0], R[1, 0] - R[0, 1]])
    return th / (2 * math.sin(th)) * v

@op('mat')
def mode_unfold(T, k): return np.moveaxis(np.asarray(T), k, 0).reshape(np.asarray(T).shape[k], -1)

@op('mat')
def mode_product(T, M, k): return np.moveaxis(np.tensordot(np.asarray(M), np.asarray(T), axes=(1, k)), 0, k)

@op('mat')
def hosvd(T, ranks):
    """Decomposição de Tucker truncada por HOSVD. Retorna (núcleo, [fatores])."""
    T = np.asarray(T, float); U = []
    for k, r in enumerate(ranks):
        u, _, _ = np.linalg.svd(mode_unfold(T, k), full_matrices=False); U.append(u[:, :r])
    core = T
    for k, u in enumerate(U): core = mode_product(core, u.T, k)
    return core, U

@op('mat')
def low_rank(A, r):
    U, s, Vt = np.linalg.svd(np.asarray(A, float), full_matrices=False); return (U[:, :r] * s[:r]) @ Vt[:r]

@op('mat')
def block_diag(*Ms):
    Ms = [np.atleast_2d(np.asarray(M, float)) for M in Ms]; n = sum(M.shape[0] for M in Ms); m = sum(M.shape[1] for M in Ms)
    out = np.zeros((n, m)); i = j = 0
    for M in Ms: out[i:i + M.shape[0], j:j + M.shape[1]] = M; i += M.shape[0]; j += M.shape[1]
    return out

@op('mat')
def frobenius_inner(A, B): return float(np.sum(np.asarray(A) * np.asarray(B)))

@op('mat')
def commutator(A, B): A, B = np.asarray(A), np.asarray(B); return A @ B - B @ A

# ═════════════════════════════ MECÂNICA QUÂNTICA / QUBITS ═════════════════════════════
_QH = np.array([[1, 1], [1, -1]], complex) / math.sqrt(2)
_QX = np.array([[0, 1], [1, 0]], complex)
_QY = np.array([[0, -1j], [1j, 0]], complex)
_QZ = np.diag([1, -1]).astype(complex)
_QS = np.diag([1, 1j]).astype(complex)
_QT = np.diag([1, np.exp(1j * math.pi / 4)]).astype(complex)
_QGATES = {'H': _QH, 'X': _QX, 'Y': _QY, 'Z': _QZ, 'S': _QS, 'T': _QT}

@op('qm')
def qstate(bits):
    psi = np.zeros(2 ** len(bits), complex); psi[int(''.join(map(str, bits)), 2)] = 1; return psi

def _qapply(psi, U, k, n):
    t = np.asarray(psi, complex).reshape([2] * n); t = np.moveaxis(np.tensordot(U, t, axes=([1], [k])), 0, k)
    return t.reshape(-1)

@op('qm')
def gate(psi, nome, k, n): return _qapply(psi, _QGATES[nome], k, n)

@op('qm')
def cnot(psi, c, t_, n):
    T = np.asarray(psi, complex).reshape([2] * n).copy(); sl = [slice(None)] * n; sl[c] = 1
    ax = t_ if t_ < c else t_ - 1; sub = T[tuple(sl)].copy(); T[tuple(sl)] = np.flip(sub, axis=ax).copy()
    return T.reshape(-1)

@op('qm')
def probs(psi): p = np.abs(np.asarray(psi)) ** 2; return p / p.sum()

@op('qm')
def sample(psi, shots=1000, seed=0):
    r = np.random.default_rng(seed); p = probs(psi); idx = r.choice(len(p), size=shots, p=p)
    return Counter(format(i, f'0{int(math.log2(len(p)))}b') for i in idx)

@op('qm')
def bell_pair():
    psi = gate(qstate([0, 0]), 'H', 0, 2); return cnot(psi, 0, 1, 2)

@op('qm')
def expectation(psi, O): psi = np.asarray(psi, complex); return complex(np.conj(psi) @ np.asarray(O, complex) @ psi)

# ═════════════════════════════ ANÁLISE (extensão) ═════════════════════════════
@op('an2')
def gauss_hermite(f, n=20):
    x, w = np.polynomial.hermite.hermgauss(n); return float(sum(wi * f(xi) for xi, wi in zip(x, w)))

@op('an2')
def gauss_laguerre(f, n=20):
    x, w = np.polynomial.laguerre.laggauss(n); return float(sum(wi * f(xi) for xi, wi in zip(x, w)))

@op('an2')
def richardson(F, h, p=2): return (2 ** p * F(h / 2) - F(h)) / (2 ** p - 1)

@op('an2')
def bessel_series(nu, x, K=80):
    return sum((-1) ** k * (x / 2) ** (2 * k + nu) / (math.factorial(k) * math.gamma(k + nu + 1)) for k in range(K))

@op('an2')
def inverse_laplace(F, t, T=None, M=4000, c=0.0):
    """Inversa de Laplace por série de Fourier (fórmula de Dubner–Abate) sobre a reta c+iω."""
    T = T or 4 * t + 10; tot = 0.5 * complex(F(complex(c, 0))).real
    for k in range(1, M + 1):
        w = k * math.pi / T; tot += (complex(F(complex(c, w))) * cmath.exp(1j * w * t)).real
    return math.exp(c * t) / T * tot

@op('an2')
def pade(c, L, M):
    """Aproximante de Padé [L/M] de série com coeficientes c. Retorna (p, q), q[0]=1."""
    c = list(c); q = [1.0]
    if M > 0:
        Amat = np.array([[c[L + i - j] if 0 <= L + i - j < len(c) else 0.0 for j in range(1, M + 1)] for i in range(1, M + 1)], float)
        rhs = -np.array([c[L + i] for i in range(1, M + 1)], float)
        q = [1.0] + list(np.linalg.solve(Amat, rhs))
    p = [sum(q[j] * c[i - j] for j in range(0, min(i, M) + 1)) for i in range(L + 1)]
    return p, q

@op('an2')
def laurent_coeff(f, n, c=0.0, r=1.0, N=2048):
    t = np.linspace(0, 2 * math.pi, N, endpoint=False); z = c + r * np.exp(1j * t)
    return complex(np.mean(np.array([f(w) for w in z]) * (z - c) ** (-n)))

@op('an2')
def cauchy_eval(f, z0, r=1.0, N=2048):
    t = np.linspace(0, 2 * math.pi, N, endpoint=False); z = z0 + r * np.exp(1j * t)
    return complex(np.mean(np.array([f(w) for w in z]) * (z - z0) / (z - z0)))

@op('an2')
def euler_maruyama(a, b, x0, T, n, seed=0):
    """dX = a(t,X) dt + b(t,X) dW."""
    r = np.random.default_rng(seed); dt = T / n; x = np.empty(n + 1); x[0] = x0; t = 0.0
    for i in range(n):
        dW = math.sqrt(dt) * r.standard_normal(); x[i + 1] = x[i] + a(t, x[i]) * dt + b(t, x[i]) * dW; t += dt
    return x

@op('an2')
def milstein(a, b, db, x0, T, n, seed=0):
    r = np.random.default_rng(seed); dt = T / n; x = np.empty(n + 1); x[0] = x0; t = 0.0
    for i in range(n):
        dW = math.sqrt(dt) * r.standard_normal(); xi = x[i]
        x[i + 1] = xi + a(t, xi) * dt + b(t, xi) * dW + 0.5 * b(t, xi) * db(t, xi) * (dW * dW - dt); t += dt
    return x

@op('an2')
def fem_poisson_1d(f, n=50):
    """-u'' = f em (0,1), u(0)=u(1)=0, elementos finitos lineares com quadratura simples."""
    h = 1 / (n + 1); x = np.linspace(0, 1, n + 2)
    K = (np.diag(2 * np.ones(n)) - np.diag(np.ones(n - 1), 1) - np.diag(np.ones(n - 1), -1)) / h
    F = np.array([h * f(xi) for xi in x[1:-1]]); u = np.linalg.solve(K, F)
    return x, np.concatenate([[0.0], u, [0.0]])

@op('an2')
def shooting_bvp(f, a, b, ya, yb, s0, s1, steps=2000):
    """y'' = f(x, y, y'), y(a)=ya, y(b)=yb, por método do tiro com secante e RK4."""
    def solve(s):
        y = np.array([ya, s], float); h = (b - a) / steps; x = a; traj = [y.copy()]
        F = lambda xx, yy: np.array([yy[1], f(xx, yy[0], yy[1])])
        for _ in range(steps):
            k1 = F(x, y); k2 = F(x + h / 2, y + h * k1 / 2); k3 = F(x + h / 2, y + h * k2 / 2); k4 = F(x + h, y + h * k3)
            y = y + h * (k1 + 2 * k2 + 2 * k3 + k4) / 6; x += h; traj.append(y.copy())
        return np.array(traj)
    g = lambda s: solve(s)[-1, 0] - yb
    g0, g1 = g(s0), g(s1)
    for _ in range(60):
        if g1 == g0: break
        s0, s1, g0 = s1, s1 - g1 * (s1 - s0) / (g1 - g0), g1
        g1 = g(s1)
        if abs(s1 - s0) < 1e-12: break
    return np.linspace(a, b, steps + 1), solve(s1)[:, 0]

@op('an2')
def chebyshev_coeffs(f, n=16):
    """Coeficientes de Chebyshev de f em [-1,1] via amostragem nos nós de Chebyshev."""
    k = np.arange(n); x = np.cos(np.pi * (k + 0.5) / n); y = np.array([f(v) for v in x])
    c = np.array([2 / n * np.sum(y * np.cos(np.pi * j * (k + 0.5) / n)) for j in range(n)]); c[0] /= 2; return c

# ═════════════════════════════ PROBABILIDADE (extensão) ═════════════════════════════
@op('pr')
def absorption_probs(P, transient, absorbing):
    P = np.asarray(P, float); T = list(transient); Ab = list(absorbing)
    Q = P[np.ix_(T, T)]; R = P[np.ix_(T, Ab)]; return np.linalg.solve(np.eye(len(T)) - Q, R)

@op('pr')
def expected_absorption_time(P, transient):
    P = np.asarray(P, float); T = list(transient); Q = P[np.ix_(T, T)]
    return np.linalg.solve(np.eye(len(T)) - Q, np.ones(len(T)))

@op('pr')
def gambler_ruin(p, i, N):
    """Probabilidade de atingir N antes de 0, partindo de i, com ganho p por aposta."""
    if p == 0.5: return i / N
    r = (1 - p) / p; return (1 - r ** i) / (1 - r ** N)

@op('pr')
def coupon_expect(n): return n * float(harmonic(n))

@op('pr')
def birthday_prob(n, d=365): return 1 - math.prod((d - i) / d for i in range(n))

@op('pr')
def poisson_process(rate, T, seed=0):
    r = np.random.default_rng(seed); t = 0.0; out = []
    while True:
        t += r.exponential(1 / rate)
        if t > T: return out
        out.append(t)

@op('pr')
def mc_pi(n=10 ** 6, seed=0):
    r = np.random.default_rng(seed); x, y = r.random(n), r.random(n); return 4 * float(np.mean(x * x + y * y <= 1))

@op('pr')
def gmm_em_1d(x, k=2, it=300, seed=0):
    x = np.asarray(x, float); r = np.random.default_rng(seed)
    mu = r.choice(x, k, replace=False); sd = np.full(k, x.std()); w = np.full(k, 1 / k)
    for _ in range(it):
        L = np.array([w[j] * np.exp(-0.5 * ((x - mu[j]) / sd[j]) ** 2) / (sd[j] * math.sqrt(2 * math.pi)) for j in range(k)])
        R = L / (L.sum(0) + 1e-300)
        nk = R.sum(1); w = nk / len(x); mu = (R @ x) / nk; sd = np.sqrt((R * (x[None] - mu[:, None]) ** 2).sum(1) / nk) + 1e-9
    return w, mu, sd

# ═════════════════════════════ OTIMIZAÇÃO (extensão) ═════════════════════════════
@op('opt2')
def newton_minimize(grad, hess, x0, it=100, tol=1e-12):
    x = np.array(x0, float)
    for _ in range(it):
        g = grad(x)
        if np.linalg.norm(g) < tol: break
        x = x - np.linalg.solve(hess(x), g)
    return x

@op('opt2')
def gd_armijo(f, grad, x0, it=10000, tol=1e-10):
    x = np.array(x0, float)
    for _ in range(it):
        g = grad(x)
        if np.linalg.norm(g) < tol: break
        t, fx = 1.0, f(x)
        while f(x - t * g) > fx - 0.5 * t * (g @ g) and t > 1e-16: t *= 0.5
        x = x - t * g
    return x

@op('opt2')
def projected_gradient(grad, x0, lo, hi, step=0.1, it=5000):
    x = np.clip(np.array(x0, float), lo, hi)
    for _ in range(it): x = np.clip(x - step * grad(x), lo, hi)
    return x

@op('opt2')
def subgradient_min(f, subg, x0, it=20000):
    x = np.array(x0, float); best = x.copy(); fb = f(x)
    for k in range(1, it + 1):
        g = subg(x); n2 = g @ g
        if n2 == 0: break
        x = x - (1 / k) * g / math.sqrt(n2) * max(1.0, np.linalg.norm(x))
        if f(x) < fb: fb, best = f(x), x.copy()
    return best, fb

@op('opt2')
def fletcher_reeves(f, grad, x0, it=500, tol=1e-10):
    x = np.array(x0, float); g = grad(x); d = -g
    for _ in range(it):
        if np.linalg.norm(g) < tol: break
        t, fx, gd = 1.0, f(x), g @ d
        while f(x + t * d) > fx + 1e-4 * t * gd and t > 1e-16: t *= 0.5
        x = x + t * d; gn = grad(x); beta = (gn @ gn) / (g @ g); d = -gn + beta * d; g = gn
    return x

# ═════════════════════════════ GRAFOS (extensão) ═════════════════════════════
@op('gr2')
def prim(n, edges):
    G = defaultdict(list)
    for u, v, w in edges: G[u].append((w, u, v)); G[v].append((w, v, u))
    seen = {0}; h = list(G[0]); heapq.heapify(h); T = []
    while h and len(seen) < n:
        w, u, v = heapq.heappop(h)
        if v in seen: continue
        seen.add(v); T.append((u, v, w))
        for e in G[v]:
            if e[2] not in seen: heapq.heappush(h, e)
    return T

@op('gr2')
def maximal_cliques(adj):
    """Bron–Kerbosch com pivô. adj: dict v -> set de vizinhos."""
    out = []
    def bk(R, P, X):
        if not P and not X: out.append(sorted(R)); return
        pivot = max(P | X, key=lambda u: len(P & adj[u])) if (P | X) else None
        for v in list(P - (adj[pivot] if pivot is not None else set())):
            bk(R | {v}, P & adj[v], X & adj[v]); P = P - {v}; X = X | {v}
    bk(set(), set(adj), set()); return out

@op('gr2')
def astar(edges, s, t, h):
    G = defaultdict(dict)
    for u, v, w in edges: G[u][v] = w
    g = {s: 0}; pq = [(h(s), s)]; prev = {}
    while pq:
        _, u = heapq.heappop(pq)
        if u == t:
            path = [u]
            while path[-1] in prev: path.append(prev[path[-1]])
            return g[t], path[::-1]
        for v, w in G[u].items():
            if g[u] + w < g.get(v, math.inf): g[v] = g[u] + w; prev[v] = u; heapq.heappush(pq, (g[v] + h(v), v))
    return math.inf, []

@op('gr2')
def spectral_bisection(n, edges):
    L = np.zeros((n, n))
    for u, v in edges: L[u, u] += 1; L[v, v] += 1; L[u, v] -= 1; L[v, u] -= 1
    w, V = np.linalg.eigh(L); f = V[:, 1]; return [i for i in range(n) if f[i] >= 0], [i for i in range(n) if f[i] < 0]

@op('gr2')
def max_independent_set(n, edges):
    adj = defaultdict(set)
    for u, v in edges: adj[u].add(v); adj[v].add(u)
    best = []
    for r in range(n, 0, -1):
        for S in itertools.combinations(range(n), r):
            if all(v not in adj[u] for u, v in itertools.combinations(S, 2)): return list(S)
    return best

# ═════════════════════════════ GEOMETRIA (extensão) ═════════════════════════════
def _gcross(o, a, b): return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

@op('geo2')
def ear_clip(poly):
    """Triangulação de polígono simples (antihorário) por corte de orelhas. Retorna índices."""
    idx = list(range(len(poly))); tris = []; guard = 0
    def in_tri(p, a, b, c):
        return _gcross(a, b, p) >= 0 and _gcross(b, c, p) >= 0 and _gcross(c, a, p) >= 0
    while len(idx) > 3 and guard < 10 ** 5:
        guard += 1; n = len(idx); found = False
        for i in range(n):
            ia, ib, ic = idx[i - 1], idx[i], idx[(i + 1) % n]
            a, b, c = poly[ia], poly[ib], poly[ic]
            if _gcross(a, b, c) <= 0: continue
            if any(in_tri(poly[p], a, b, c) for p in idx if p not in (ia, ib, ic)): continue
            tris.append((ia, ib, ic)); idx.pop(i); found = True; break
        if not found: break
    if len(idx) == 3: tris.append(tuple(idx))
    return tris

@op('geo2')
def de_casteljau(P, t):
    P = [np.array(p, float) for p in P]
    while len(P) > 1: P = [(1 - t) * P[i] + t * P[i + 1] for i in range(len(P) - 1)]
    return P[0]

@op('geo2')
def bspline_basis(i, k, t, knots):
    """Função de base B-spline N_{i,k}(t) (fórmula de Cox–de Boor)."""
    if k == 0: return 1.0 if knots[i] <= t < knots[i + 1] else 0.0
    a = b = 0.0
    d1 = knots[i + k] - knots[i]; d2 = knots[i + k + 1] - knots[i + 1]
    if d1 != 0: a = (t - knots[i]) / d1 * bspline_basis(i, k - 1, t, knots)
    if d2 != 0: b = (knots[i + k + 1] - t) / d2 * bspline_basis(i + 1, k - 1, t, knots)
    return a + b

@op('geo2')
def closest_pair(P):
    return min(((math.dist(p, q), p, q) for i, p in enumerate(P) for q in P[i + 1:]), default=None)

@op('geo2')
def segments_intersect(p1, p2, p3, p4):
    d1, d2 = _gcross(p3, p4, p1), _gcross(p3, p4, p2); d3, d4 = _gcross(p1, p2, p3), _gcross(p1, p2, p4)
    return (d1 * d2 < 0) and (d3 * d4 < 0)

@op('geo2')
def minkowski_convex(P, Q): return convex_hull([(a[0] + b[0], a[1] + b[1]) for a in P for b in Q])

@op('geo2')
def reflection_matrix(n):
    n = np.asarray(n, float); n = n / np.linalg.norm(n); return np.eye(len(n)) - 2 * np.outer(n, n)

@op('geo2')
def affine_fit(P):
    """Hiperplano de melhor ajuste: retorna (centróide, normal) via SVD."""
    P = np.asarray(P, float); c = P.mean(0); _, _, Vt = np.linalg.svd(P - c); return c, Vt[-1]

# ═════════════════════════════ TEORIA DOS NÚMEROS (extensão) ═════════════════════════════
@op('nt2')
def legendre(a, p):
    r = pow(a % p, (p - 1) // 2, p); return 0 if r == 0 else (1 if r == 1 else -1)

@op('nt2')
def prime_pi(n): return len(sieve(n))

@op('nt2')
def mertens(n): return sum(mobius(k) for k in range(1, n + 1))

@op('nt2')
def divisors(n): return sorted(d for d in range(1, math.isqrt(n) + 1) if n % d == 0 for d in {d, n // d})

@op('nt2')
def sum_totient(n): return sum(phi(k) for k in range(1, n + 1))

@op('nt2')
def dirichlet_conv(f, g, n): return sum(f(d) * g(n // d) for d in divisors(n))

@op('nt2')
def is_carmichael(n):
    if is_prime(n) or n < 2: return False
    if any(f_ > 1 for f_ in factor(n).values()): return False
    return all(pow(a, n - 1, n) == 1 for a in range(2, n) if math.gcd(a, n) == 1)

@op('nt2')
def sqrt_cf_period(n):
    a0 = math.isqrt(n)
    if a0 * a0 == n: return 0
    m, d, a, per = 0, 1, a0, 0
    while True:
        m = d * a - m; d = (n - m * m) // d; a = (a0 + m) // d; per += 1
        if a == 2 * a0: return per

@op('nt2')
def multiplicative_sum(f, n): return math.prod(sum(f(p ** i) for i in range(e + 1)) for p, e in factor(n).items())

# ═════════════════════════════ LÓGICA (extensão) ═════════════════════════════
@op('lg2')
def resolution_refute(clauses, max_iter=5000):
    """Refutação por resolução. Cláusulas: listas de literais inteiros (-v = negação). True se insatisfatível."""
    S = {frozenset(c) for c in clauses}
    for _ in range(max_iter):
        L_ = list(S); new = set()
        for i in range(len(L_)):
            for j in range(i + 1, len(L_)):
                for lit in L_[i]:
                    if -lit in L_[j]:
                        r = (L_[i] - {lit}) | (L_[j] - {-lit})
                        if not r: return True
                        if not any(-x in r for x in r): new.add(frozenset(r))
        if new <= S: return False
        S |= new
    return None

# ═════════════════════════════ EQUAÇÕES DIFERENCIAIS (extensão) ═════════════════════════════
@op('de2')
def adams_bashforth4(f, y0, t0, t1, n=1000):
    """Adams–Bashforth de 4ª ordem com partida por RK4 (y' = f(t,y), escalar ou vetor)."""
    h = (t1 - t0) / n; ts = [t0 + i * h for i in range(n + 1)]; ys = [np.atleast_1d(np.array(y0, float))]
    for i in range(3):
        y = ys[-1]; t = ts[i]
        k1 = f(t, y); k2 = f(t + h / 2, y + h * k1 / 2); k3 = f(t + h / 2, y + h * k2 / 2); k4 = f(t + h, y + h * k3)
        ys.append(y + h * (k1 + 2 * k2 + 2 * k3 + k4) / 6)
    F = [f(ts[i], ys[i]) for i in range(4)]
    for i in range(3, n):
        ys.append(ys[i] + h / 24 * (55 * F[i] - 59 * F[i - 1] + 37 * F[i - 2] - 9 * F[i - 3])); F.append(f(ts[i + 1], ys[i + 1]))
    return ts, ys

@op('de2')
def lotka_volterra(a, b, c, d, x0, y0, T, n=10000):
    f = lambda t, v: np.array([a * v[0] - b * v[0] * v[1], -c * v[1] + d * v[0] * v[1]])
    _, ys = adams_bashforth4(f, [x0, y0], 0.0, T, n); return np.array(ys)

# ═════════════════════════════ ÁLGEBRA ABSTRATA E ANEL (extensão) ═════════════════════════════
@op('ring')
def zn_units(n): return [a for a in range(1, n + 1) if math.gcd(a, n) == 1]

@op('ring')
def zn_zero_divisors(n): return [a for a in range(1, n) if math.gcd(a, n) > 1]

@op('ring')
def zn_nilpotents(n):
    ps = list(factor(n).keys()) if n > 1 else []
    return [a for a in range(1, n) if all(a % p == 0 for p in ps)]

@op('ring')
def ideal_zn(gens, n):
    d = math.gcd(n, *gens) if gens else n; return sorted({(d * k) % n for k in range(n // d)})

@op('ring')
def zn_is_field(n): return is_prime(n)

@op('ring')
def gauss_gcd(a, b):
    """Máximo divisor comum em Z[i] (algoritmo de Euclides com arredondamento)."""
    a = complex(*a) if isinstance(a, tuple) else complex(a); b = complex(*b) if isinstance(b, tuple) else complex(b)
    while abs(b) > 1e-9:
        q = a / b; qq = complex(round(q.real), round(q.imag)); a, b = b, a - qq * b
    return (int(round(a.real)), int(round(a.imag)))

@op('ring')
def closure_of_gens(gens, mul, e):
    H = {e}; frontier = [e]; gens = list(gens)
    while frontier:
        x = frontier.pop()
        for g in gens:
            y = mul(x, g)
            if y not in H: H.add(y); frontier.append(y)
    return frozenset(H)

@op('ring')
def subgroups_small(G, mul, e):
    subs = {closure_of_gens([g], mul, e) for g in G}
    subs |= {closure_of_gens([a, b], mul, e) for a in G for b in G}
    return subs

@op('ring')
def normal_subgroups_small(G, mul, e, inv):
    return [H for H in subgroups_small(G, mul, e) if all(mul(mul(g, h), inv(g)) in H for g in G for h in H)]

@op('ring')
def is_hom(f, G, mulG, mulH): return all(f[mulG(a, b)] == mulH(f[a], f[b]) for a in G for b in G)

@op('ring')
def sylow_count(G, mul, e, p):
    n, pk = len(G), 1
    while n % (pk * p) == 0: pk *= p
    return sum(1 for H in subgroups_small(G, mul, e) if len(H) == pk)

@op('ring')
def ddf_gfp(f, p):
    """Fatoração por graus distintos sobre GF(p). Retorna [(grau, número de fatores)]."""
    f = _mt(f, p); res = []; d = 0; h = [0, 1]
    while len(f) - 1 >= 2 * (d + 1):
        d += 1
        h = pm_powmod(h, p, f, p)
        g = pm_gcd(f, _mt(padd(h, [0, -1]), p), p)
        if len(g) > 1:
            res.append((d, (len(g) - 1) // d)); f = pm_divmod(f, g, p)[0]; h = pm_divmod(h, f, p)[1]
    if len(f) > 1: res.append((len(f) - 1, 1))
    return res

@op('ring')
def roots_gfp(f, p): return [x for x in range(p) if peval(f, x) % p == 0]

# ═════════════════════════════ CATEGORIAS (extensão) ═════════════════════════════
@op('cat2')
def slice_objects(C, A): return [m for m in C.mor if C.cod[m] == A]

@op('cat2')
def coslice_objects(C, A): return [m for m in C.mor if C.dom[m] == A]

@op('cat2')
def fs_limit(objs, arrows):
    """Limite em FinSet. objs: {i: conjunto}; arrows: {(i,j): {x: y}}."""
    keys = list(objs); out = []
    for tup in itertools.product(*[sorted(objs[k], key=repr) for k in keys]):
        d = dict(zip(keys, tup))
        if all(f[d[i]] == d[j] for (i, j), f in arrows.items()): out.append(d)
    return out

@op('cat2')
def fs_colimit(objs, arrows):
    """Colimite em FinSet por união-busca sobre pares (índice, elemento)."""
    parent = {}
    def find(a):
        parent.setdefault(a, a)
        while parent[a] != a: parent[a] = parent[parent[a]]; a = parent[a]
        return a
    for i in objs:
        for x in objs[i]: find((i, x))
    for (i, j), f in arrows.items():
        for x in objs[i]: parent[find((i, x))] = find((j, f[x]))
    classes = defaultdict(set)
    for node in list(parent): classes[find(node)].add(node)
    return [frozenset(v) for v in classes.values()]

@op('cat2')
def lan_poset(Cset, Dset, leqD, F, G, join):
    """Extensão de Kan à esquerda: Lan_F G(d) = ⋁{G(c) : F(c) ≤ d}."""
    out = {}
    for d in Dset:
        acc = None
        for c in Cset:
            if leqD(F[c], d): acc = G[c] if acc is None else join(acc, G[c])
        out[d] = acc
    return out

@op('cat2')
def ran_poset(Cset, Dset, leqD, F, G, meet):
    """Extensão de Kan à direita: Ran_F G(d) = ⋀{G(c) : d ≤ F(c)}."""
    out = {}
    for d in Dset:
        acc = None
        for c in Cset:
            if leqD(d, F[c]): acc = G[c] if acc is None else meet(acc, G[c])
        out[d] = acc
    return out

@op('cat2')
def grothendieck_poset(P, leq, F, res):
    """Construção de Grothendieck de F: P → Set. res[(p,q)] é a função F(p≤q)."""
    els = [(p, x) for p in P for x in F[p]]
    def ok(a, b):
        if a[0] == b[0]: return a[1] == b[1]
        return leq(a[0], b[0]) and res[(a[0], b[0])][a[1]] == b[1]
    return els, {(a, b) for a in els for b in els if ok(a, b)}

@op('cat2')
def fs_curry_bijection(X, Y, Z):
    """Verifica por força bruta a bijeção de curry Hom(X×Y,Z) ≅ Hom(X, Z^Y)."""
    X, Y, Z = list(X), list(Y), list(Z); XY = [(x, y) for x in X for y in Y]
    for v in itertools.product(Z, repeat=len(XY)):
        f = dict(zip(XY, v)); g = {x: {y: f[(x, y)] for y in Y} for x in X}
        if {(x, y): g[x][y] for x in X for y in Y} != f: return False
    return True

@op('cat2')
def subobject_classifier_check(X):
    X = list(X); subs = [frozenset(s) for r in range(len(X) + 1) for s in itertools.combinations(X, r)]
    chars = {tuple(int(x in A) for x in X) for A in subs}; return len(chars) == len(subs)

@op('cat2')
def kleisli(g, f, bind):
    """Composição de Kleisli para mônada dada por bind: (g ∘_K f)(x) = bind(f(x), g)."""
    return lambda x: bind(f(x), g)

# ═════════════════════════════ PROCESSOS / DINÂMICA (extensão) ═════════════════════════════
@op('ds2')
def bifurcation_diagram(r_vals, x0=0.5, burn=500, keep=200):
    out = []
    for r in r_vals:
        x = x0
        for _ in range(burn): x = r * x * (1 - x)
        for _ in range(keep): x = r * x * (1 - x); out.append((r, x))
    return out

@op('ds2')
def lyapunov_exponent_map(f, df, x0, n=20000):
    x, s = x0, 0.0
    for _ in range(n): s += math.log(abs(df(x)) + 1e-300); x = f(x)
    return s / n

