def compact_tokens(text):
    return [t if len(t)<=128 else '<unk>' for t in re.findall(r"[^\W_]+(?:[-'][^\W_]+)*|[^\w\s]",text.casefold(),re.UNICODE)[:20000]]


def compact_words(text):
    normalized=''.join(c for c in unicodedata.normalize('NFKD',text.casefold()) if not unicodedata.combining(c))
    stop={'a','o','as','os','um','uma','de','do','da','dos','das','e','em','no','na','nos','nas','que','qual','quais','como','por','para','com','se','eu','voce','me','sobre','explique','diga','pode','ser','sao','foi','isso','esta','este'}
    out=[]
    for word in re.findall(r'[^\W_]+',normalized,re.UNICODE):
        if any('\u3400'<=c<='\u9fff' for c in word):out.extend(list(word)+[word[i:i+2] for i in range(len(word)-1)])
        elif word not in stop and len(word)>1:out.append(word)
    return out


def compact_vector(text,dim=256):
    result=np.zeros(dim)
    for word,count in Counter(compact_words(text)).items():
        for feature,weight in [(word,2.)]+[(word[i:i+3],.3) for i in range(max(0,len(word)-2))]:
            bits=np.unpackbits(np.frombuffer(hashlib.shake_256(feature.encode()).digest(dim//8),dtype=np.uint8)).astype(float)*2-1
            result+=weight*(1+math.log(count))*bits
    return result/max(EPS,float(np.linalg.norm(result)))


class CompressedLanguageModel:
    """PPM/Witten–Bell de ordem variável + passagens originais comprimidas.

    Contagens são parâmetros aprendidos. Não é cálculo de Kolmogorov, uma rede
    fractal, pesos zero, GPT em miniatura ou garantia de fluência irrestrita.
    """
    FORMAT='neuron-compact-language-v1'
    def __init__(self,order=4,max_edges=16000,max_passages=128):
        if type(order) is not int or not 1<=order<=6 or not 256<=max_edges<=32000 or not 1<=max_passages<=256:raise ValueError('Limites de linguagem inválidos')
        self.order,self.max_edges,self.max_passages=order,max_edges,max_passages
        self.counts=OrderedDict({():Counter()});self.passages=[];self.pairs=[];self.seen=0;self.revision=0
