def read_language_sources(lab,identity,*,files=(),urls=(),seconds=300,max_bytes=1048576):
    from urllib.parse import urlsplit
    if not .1<=seconds<=300 or not 1024<=max_bytes<=4*1048576 or len(files)+len(urls)>32:raise ValueError('Orçamento de leitura inválido')
    lab._require_model()
    if not isinstance(lab.backend,CompactEncoderDecoder):raise ValueError('Use uma sessão --model compact:pt')
    agent=lab._agent(identity);agent.ensure_bridge(lab.backend);language=CompressedLanguageModel.load(agent.bridge.language().dump())
    migration=language.enable_bpe()
    lab.history.append('language.bpe.migration',identity,migration)
    deadline=time.monotonic()+seconds;consumed=0;reports=[];errors=[]
    def ingest(text,source):
        nonlocal consumed
        encoded=text.encode();budget=max_bytes-consumed
        if not budget:return
        text=encoded[:min(budget,262144)].decode('utf-8','ignore');consumed+=len(text.encode())
        if not text.strip():return
        # Avaliação em sufixo ainda não lido; depois guarda o documento completo.
        split=max(1,int(len(text)*.8));boundary=text.rfind(' ',0,split);split=boundary if boundary>len(text)*.5 else split;holdout=text[split:][:2000];before=language.coding_metrics(holdout) if holdout else None
        training=language.learn(text[:split],source,archive=False) if text[:split].strip() else None
        after=language.coding_metrics(holdout) if holdout else None
        if text[split:].strip():language.learn(text[split:],source,archive=False)
        language.remember(text,source)
        report=dict(source=source,bytes=len(text.encode()),holdout_bits_before=None if before is None else before['bits_per_token'],holdout_bits_after=None if after is None else after['bits_per_token'],holdout_coding_before=before,holdout_coding_after=after,
            split='prefixo 80% / sufixo 20%, sem reordenar; documentos repetidos podem contaminar a avaliação',training=training)
        reports.append(report);lab.history.append('language.document',identity,dict(report=report,text=text))
    for file in files:
        if time.monotonic()>=deadline or consumed>=max_bytes:break
        path=Path(file)
        with path.open('rb') as stream:
            while consumed<max_bytes and time.monotonic()<deadline:
                data=stream.read(min(262144,max_bytes-consumed))
                if not data:break
                ingest(data.decode('utf-8','replace'),str(path))
    for url in urls:
        if time.monotonic()>=deadline or consumed>=max_bytes:break
        try:
            host=(urlsplit(url).hostname or '').lower();remaining=max(.1,deadline-time.monotonic())
            policy=ToolPolicy(lab.directory/'reading',http_hosts=(host,),max_bytes=min(262144,max(1024,max_bytes-consumed)),timeout=min(10,remaining))
            result=ToolHarness(policy,lab.history).run('http.get',dict(url=url))['result'];ingest(result['text'],url)
        except (OSError,ValueError,RuntimeError) as error:
            errors.append(dict(source=url,error=str(error)));lab.history.append('language.read.failed',identity,errors[-1])
    agent.bridge.store(language)
    if language.tokenizer is not None:language.tokenizer.persist(lab.history,identity)
    lab.checkpoint();lab._refresh()
    result=dict(documents=reports,errors=errors,bytes=consumed,elapsed_budget=seconds,stats=language.stats(),offline_ready=True)
    lab.history.append('language.read.completed',identity,result)
    return result


