class DesktopMotorPolicy:
    """Imitação supervisionada finita: 32 sinais -> deslocamento relativo 2D.

    Não reconhece aplicativos nem transforma qualquer objetivo em uma macro.
    Sugestões nunca são executadas implicitamente.
    """
    def __init__(self,capacity=256):self.capacity=capacity;self.samples=deque(maxlen=capacity)
    def teach(self,features,displacement):
        x=_vector(features,32,'features');y=_vector(displacement,2,'displacement',1000)
        self.samples.append((x.copy(),y.copy()))
    def suggest(self,features):
        if len(self.samples)<2:raise ValueError('Ensine pelo menos duas demonstrações motoras')
        x=_vector(features,32,'features');X=np.array([a for a,b in self.samples]);Y=np.array([b for a,b in self.samples])
        weights=np.linalg.solve(X.T@X+.1*np.eye(32),X.T@Y);result=np.clip(x@weights,-200,200)
        return dict(op='move_relative',dx=float(result[0]),dy=float(result[1]),source='ridge_imitation',samples=len(self.samples),executed=False)
    def dump(self):return dict(capacity=self.capacity,samples=[dict(features=a.tolist(),displacement=b.tolist()) for a,b in self.samples])
    @classmethod
    def load(cls,data):
        if type(data.get('capacity')) is not int or not 2<=data['capacity']<=256 or len(data.get('samples',[]))>data['capacity']:raise ValueError('Estado motor inválido')
        result=cls(data['capacity'])
        for row in data['samples']:result.teach(row['features'],row['displacement'])
        return result


