def _read_learning_pairs(path,maximum=64):
    path=Path(path)
    if path.stat().st_size>262144:raise ValueError('Dataset excede 256 KiB')
    result=[]
    with path.open(encoding='utf-8') as file:
        for line in file:
            if line.strip():
                row=json.loads(line);q,a=row.get('input'),row.get('target')
                if any(not isinstance(t,str) or not 1<=len(t)<=1000 for t in (q,a)):raise ValueError('Par JSONL inválido')
                result.append((q,a))
                if len(result)>maximum:raise ValueError('Dataset excede '+str(maximum)+' pares')
    return result


def run_advanced_cli(args):
    if args.command in ('read','bootstrap','generate-compact'):
        if args.command=='bootstrap' and args.wikipedia:
            from urllib.parse import quote
            topics=args.topic or ['Língua portuguesa','Gramática da língua portuguesa','Aprendizagem']
            if len(topics)>8 or any(not isinstance(t,str) or not 1<=len(t)<=120 for t in topics):raise ValueError('Forneça até 8 tópicos curtos')
            args.url=list(args.url)+['https://pt.wikipedia.org/wiki/'+quote(t.replace(' ','_'),safe='') for t in topics]
        with NeuronLaboratory(args.directory,LabConfig(agents=1,model='compact:pt')) as lab:
            lab.load_model()
            if args.command=='generate-compact':
                agent=lab._agent('NEURON-1');agent.ensure_bridge(lab.backend)
                text=agent.bridge.language().generate(args.prefix,args.tokens,args.seed)
                lab.history.append('language.generated','NEURON-1',dict(prefix=args.prefix,text=text,verified=False))
                print(json.dumps(dict(text=text,verified=False,mode='ppm_generation'),ensure_ascii=False,indent=2))
            else:
                if not args.file and not args.url:raise ValueError('Forneça --file ou --url; nenhuma fonte é buscada implicitamente')
                print(json.dumps(read_language_sources(lab,args.agent,files=args.file,urls=args.url,seconds=args.seconds,max_bytes=args.max_bytes),ensure_ascii=False,indent=2))
        return 0
    if args.command=='architecture':
        with RunLease(args.directory/'writer.lock'),EventHistory(args.directory/'history.sqlite') as history:
            editor=ArchitectureEditor(Path(__file__),args.directory,history)
            if args.mode=='inspect':result=editor.inspect()
            elif args.mode in ('apply','rollback'):
                if not args.value:raise ValueError('Informe o hash do candidato')
                result=getattr(editor,args.mode)(args.value)
            else:
                if not args.value:raise ValueError('Informe um arquivo de funções para a VM')
                source=Path(args.value)
                if source.stat().st_size>32768:raise ValueError('Módulo da VM excede 32 KiB')
                code=source.read_text()
                if args.mode=='run':
                    vm=RestrictedBytecodeVM(code);values=json.loads(args.args)
                    if not isinstance(values,list) or len(values)>8:raise ValueError('--args deve ser uma lista de até 8 argumentos')
                    result=dict(result=jsonable(vm.run(args.function,*[np.array(v,dtype=float) if isinstance(v,list) else v for v in values])),bytecode_sha256=vm.bytecode_digest)
                else:result=getattr(editor,args.mode)(code)
            print(json.dumps(result,ensure_ascii=False,indent=2))
        return 0
    if args.command=='desktop':
        text=args.actions
        if text.startswith('@'):
            path=Path(text[1:])
            if path.stat().st_size>16384:raise ValueError('Plano excede 16 KiB')
            text=path.read_text()
        with RunLease(args.directory/'writer.lock'),EventHistory(args.directory/'history.sqlite') as history:
            controller=DesktopController(live=args.live,stop_file=args.stop_file or args.directory/'STOP',history=history)
            try:result=controller.execute(json.loads(text))
            finally:controller.close()
            print(json.dumps(result,ensure_ascii=False,indent=2))
        return 0
    if args.command=='federate':
        cfg=LabConfig(model='numpy:'+str(args.base),input_tokens=128,output_tokens=64)
        if args.output.resolve()==args.base.resolve():raise ValueError('Saída deve ser diferente da âncora --base')
        core=NativeSeq2Seq.load(cfg,args.base);validation=_read_learning_pairs(args.validation)
        with RunLease(args.directory/'writer.lock'),EventHistory(args.directory/'history.sqlite') as history:
            federation=FederatedLearning(core,validation,quorum=args.quorum,max_norm=args.max_norm,max_regression=args.max_regression,history=history,output=args.output)
            if args.mode=='train':
                if args.corpus is None or not 1<=args.steps<=16:raise ValueError('Forneça --corpus e --steps entre 1 e 16')
                pairs=_read_learning_pairs(args.corpus,256);bridge=core.new_bridge(0)
                for q,a in pairs:core.teach(core.encode(q),bridge,np.zeros(48),a,steps=args.steps,rate=.2)
                core.save(args.output,bridge);report=dict(output=str(args.output),samples=len(pairs),base=core.signature,validation_before=federation.anchor_loss,validation_after=federation.loss(bridge))
                history.append('federation.local_training','federation',report);print(json.dumps(report,indent=2));return 0
            if args.key_file is None or args.key_file.stat().st_size>1024:raise ValueError('Forneça --key-file (chave criada por swarm keygen)')
            key=args.key_file.read_text().strip()
            if args.mode=='serve':
                server=make_federated_server(args.host,args.port,key,federation,history)
                print(f'Federação explícita: {args.host}:{server.server_address[1]} · âncora {core.signature[:16]} · HMAC sem cifragem',flush=True)
                try:server.serve_forever(poll_interval=.25)
                except KeyboardInterrupt:pass
                finally:server.server_close()
                return 0
            client=FederatedPeerClient(args.peer,key,history);status=client.request(dict(federation='status'))
            if status['anchor']!=federation.anchor or status['round']!=federation.round_id:raise ValueError('Âncora/política/rodada remota diferente; confira quorum/norma/tolerância')
            if args.mode=='status':result=status
            elif args.mode=='submit':
                if args.local is None:raise ValueError('Informe --local com pesos treinados a partir de --base')
                local=NativeSeq2Seq.load(cfg,args.local);bridge=local.new_bridge(0)
                packet=federation.export(bridge,client=args.client,samples=args.samples);result=client.request(dict(federation='submit',update=packet))
            else:
                remote=client.request(dict(federation='pull'));delta=federation.decode(remote['update']);bridge=core.new_bridge(0)
                for k in federation.PARAMS:bridge.arrays[k]=core.base[k]+delta[k]
                loss=federation.loss(bridge)
                accepted=loss<=federation.anchor_loss+federation.max_regression
                if accepted:core.save(args.output,bridge)
                result=dict(accepted_locally=accepted,baseline_loss=federation.anchor_loss,candidate_loss=loss,remote_report=remote['report'],output=str(args.output) if accepted else None)
                history.append('federation.pull.checked','federation',result)
            print(json.dumps(result,indent=2,ensure_ascii=False))
        return 0
    raise ValueError('Comando avançado desconhecido')


from fractions import Fraction


def _proof_expression(value):
    if isinstance(value,str):
        if len(value)>8192:raise ValueError('Fonte simbólica excede 8 KiB')
        try:tree=ast.parse(value,mode='eval')
        except SyntaxError:tree=ast.parse(value)
    elif isinstance(value,ast.AST):tree=copy.deepcopy(value)
    else:raise ValueError('Expressão/AST esperada')
    if len(list(ast.walk(tree)))>512:raise ValueError('AST excede orçamento simbólico')
    if isinstance(tree,ast.Expression):return tree.body
    if isinstance(tree,ast.Module):
        if len(tree.body)!=1:raise ValueError('Uma função ou expressão por prova')
        tree=tree.body[0]
    if isinstance(tree,ast.Expr):return tree.value
    if not isinstance(tree,ast.FunctionDef) or tree.decorator_list or tree.args.defaults or tree.args.kw_defaults or tree.args.kwonlyargs or tree.args.vararg or tree.args.kwarg or tree.args.posonlyargs:raise ValueError('Somente funções retas e puras no domínio polinomial')
    names={a.arg for a in tree.args.args};env={}
    class Substitute(ast.NodeTransformer):
        def visit_Name(self,node):return copy.deepcopy(env.get(node.id,node))
    result=None
    for node in tree.body:
        if isinstance(node,ast.Expr) and isinstance(node.value,ast.Constant) and isinstance(node.value.value,str):continue
        if result is not None:raise ValueError('Código após retorno não suportado')
        if isinstance(node,ast.Assign) and len(node.targets)==1 and isinstance(node.targets[0],ast.Name):
            name=node.targets[0].id;expr=Substitute().visit(copy.deepcopy(node.value))
            if any(isinstance(n,ast.Name) and n.id not in names for n in ast.walk(expr)):raise ValueError('Variável sem definição')
            if len(list(ast.walk(expr)))>512:raise ValueError('Substituição simbólica excede orçamento')
            env[name]=expr
        elif isinstance(node,ast.Return):
            result=Substitute().visit(copy.deepcopy(node.value))
            if len(list(ast.walk(result)))>512:raise ValueError('Retorno simbólico excede orçamento')
        else:raise ValueError('Controle de fluxo/efeitos não pertencem ao domínio da prova')
    if result is None:raise ValueError('Retorno ausente')
    return result


def _exact_polynomial(node,variables):
    n=len(variables);zero=(0,)*n;operations=[0]
    def trim(d):
        operations[0]+=1
        if operations[0]>4096 or len(d)>1024 or any(sum(m)>16 or abs(v.numerator).bit_length()>4096 or v.denominator.bit_length()>4096 for m,v in d.items()):raise ValueError('Expansão polinomial excede limite')
        return {m:v for m,v in d.items() if v}
    def add(a,b,sign=1):
        d=dict(a)
        for m,v in b.items():d[m]=d.get(m,Fraction(0))+sign*v
        return trim(d)
    def mul(a,b):
        if len(a)*len(b)>65536:raise ValueError('Produto polinomial muito grande')
        d={}
        for m,v in a.items():
            for q,w in b.items():
                r=tuple(x+y for x,y in zip(m,q));d[r]=d.get(r,Fraction(0))+v*w
        return trim(d)
    def go(node):
        if isinstance(node,ast.Constant) and type(node.value) in (int,float):
            if not math.isfinite(node.value) or abs(node.value)>1e100:raise ValueError('Constante fora do domínio')
            return {zero:Fraction(str(node.value))}
        if isinstance(node,ast.Name) and node.id in variables:
            exponent=[0]*n;exponent[variables.index(node.id)]=1;return {tuple(exponent):Fraction(1)}
        if isinstance(node,ast.UnaryOp) and isinstance(node.op,(ast.USub,ast.UAdd)):
            value=go(node.operand);return {m:(-v if isinstance(node.op,ast.USub) else v) for m,v in value.items()}
        if isinstance(node,ast.BinOp):
            if isinstance(node.op,ast.Pow):
                if not isinstance(node.right,ast.Constant) or type(node.right.value) is not int or not 0<=node.right.value<=8:raise ValueError('Potência deve ser inteiro de 0 a 8')
                base=go(node.left);out={zero:Fraction(1)}
                for _ in range(node.right.value):out=mul(out,base)
                return out
            a,b=go(node.left),go(node.right)
            if isinstance(node.op,ast.Add):return add(a,b)
            if isinstance(node.op,ast.Sub):return add(a,b,-1)
            if isinstance(node.op,ast.Mult):return mul(a,b)
            if isinstance(node.op,ast.Div) and set(b)<={zero} and b.get(zero,0):return trim({m:v/b[zero] for m,v in a.items()})
        raise ValueError('Operação fora de Q[x]: sem chamadas, divisão por variável ou transcendentes')
    return trim(go(node))


def _proof_poly_pack(poly):return [[list(m),str(c.numerator),str(c.denominator)] for m,c in sorted(poly.items())]


def symbolic_equivalence_check(ast_old,ast_new,*,variables=None,assumptions=()):
    """Prova exata no anel Q[x] ou inclusão em ideal declarado.

    Não prova equivalência IEEE-754, desempenho, memória, efeitos ou segurança
    geral do programa. Domínio não suportado retorna inconclusivo, nunca True.
    """
    try:
        old,new=_proof_expression(ast_old),_proof_expression(ast_new)
        inferred=sorted({n.id for tree in (old,new) for n in ast.walk(tree) if isinstance(n,ast.Name)})
        variables=''.join(inferred) if variables is None else variables
        if not variables:variables='x'
        if not isinstance(variables,str) or not 1<=len(variables)<=4 or len(set(variables))!=len(variables) or any(c not in 'abcdefghijklmnopqrstuvwxyz' for c in variables):raise ValueError('Use até quatro variáveis de uma letra')
        if not isinstance(assumptions,(list,tuple)) or len(assumptions)>4:raise ValueError('Até quatro geradores de ideal')
        a,b=_exact_polynomial(old,variables),_exact_polynomial(new,variables);difference=dict(a)
        for monomial,value in b.items():difference[monomial]=difference.get(monomial,Fraction(0))-value
        difference={m:v for m,v in difference.items() if v};module=omnimat();certificate=None
        if assumptions:
            for text in assumptions:_exact_polynomial(_proof_expression(text),variables)
            certificate=module.groebner_certificate(list(assumptions),variables)
            if not module.verify_groebner_certificate(certificate):raise ArithmeticError('Certificado Gröbner inválido')
            remainder=module._reduce(difference,certificate['basis'])
        else:remainder=difference
        proof=dict(version=1,domain='Q['+','.join(variables)+']',old=ast.unparse(old),new=ast.unparse(new),variables=variables,
            assumptions=list(assumptions),difference=_proof_poly_pack(difference),remainder=_proof_poly_pack(remainder),
            ideal_certificate=None if certificate is None else _math_pack(certificate),proved=not remainder,
            status='proved' if not remainder else 'not_equivalent',ieee754_proved=False,clock_speed_proved=False)
        proof['digest']=hashlib.sha256(json.dumps(proof,sort_keys=True,separators=(',',':')).encode()).hexdigest()
        return proof
    except (ValueError,TypeError,OverflowError,ArithmeticError,SyntaxError) as error:
        return dict(status='inconclusive',proved=False,reason=str(error),domain='unsupported',ieee754_proved=False,clock_speed_proved=False)


def verify_symbolic_equivalence(proof):
    try:
        if proof.get('version')!=1 or not proof.get('proved'):return False
        saved=dict(proof);digest=saved.pop('digest')
        if hashlib.sha256(json.dumps(saved,sort_keys=True,separators=(',',':')).encode()).hexdigest()!=digest:return False
        recomputed=symbolic_equivalence_check(proof['old'],proof['new'],variables=proof['variables'],assumptions=proof['assumptions'])
        return recomputed==proof and recomputed['proved']
    except (ValueError,KeyError,TypeError):return False


def boolean_equivalence_check(old,new):
    """DPLL sobre XOR via Tseitin + verificação independente finita <=12 entradas."""
    import itertools
    try:
        trees=[_proof_expression(old),_proof_expression(new)];names=sorted({n.id for t in trees for n in ast.walk(t) if isinstance(n,ast.Name)})
        if len(names)>12:raise ValueError('Prova booleana limitada a 12 entradas')
        ids={n:i+1 for i,n in enumerate(names)};next_id=[len(names)+1];clauses=[]
        def build(node):
            if isinstance(node,ast.Name):return ids[node.id]
            if isinstance(node,ast.UnaryOp) and isinstance(node.op,ast.Not):return -build(node.operand)
            if isinstance(node,ast.Constant) and type(node.value) is bool:
                z=next_id[0];next_id[0]+=1;clauses.append([z if node.value else -z]);return z
            if isinstance(node,ast.BoolOp) and isinstance(node.op,(ast.And,ast.Or)):
                values=[build(v) for v in node.values];z=next_id[0];next_id[0]+=1
                if isinstance(node.op,ast.And):clauses.extend([[-z,v] for v in values]);clauses.append([z]+[-v for v in values])
                else:clauses.extend([[z,-v] for v in values]);clauses.append([-z]+values)
                return z
            raise ValueError('Use apenas and/or/not e booleanos')
        a,b=[build(t) for t in trees];clauses.extend([[a,b],[-a,-b]])
        result=calcular('lg.dpll',clauses)
        def evaluate(node,env):
            if isinstance(node,ast.Name):return env[node.id]
            if isinstance(node,ast.Constant):return node.value
            if isinstance(node,ast.UnaryOp):return not evaluate(node.operand,env)
            values=[evaluate(v,env) for v in node.values];return all(values) if isinstance(node.op,ast.And) else any(values)
        counterexample=None;checked=0
        for values in itertools.product((False,True),repeat=len(names)):
            env=dict(zip(names,values));checked+=1
            if evaluate(trees[0],env)!=evaluate(trees[1],env):counterexample=env;break
        proved=result is None and counterexample is None
        return dict(status='proved' if proved else 'not_equivalent',proved=proved,domain='finite_boolean_circuit',assignments_checked=checked,
            dpll_unsat=result is None,counterexample=counterexample,clauses=clauses,variables=names)
    except (ValueError,TypeError,SyntaxError) as error:return dict(status='inconclusive',proved=False,reason=str(error))


def _curriculum_integer(value):
    if type(value) is not int or abs(value)>100:raise ValueError('Inteiro sintético fora do domínio')
    return value


def synthetic_oracle(problem):
    """Problemas finitos exatos. Não usa saídas inventadas como fatos físicos."""
    if not isinstance(problem,dict):raise ValueError('Problema deve ser objeto')
    family=problem.get('family');data=problem.get('data');certificate={}
    if family=='arithmetic':
        if not isinstance(data,list) or len(data)!=3:raise ValueError('Aritmética: [a,operador,b]')
        a,op,b=data;a,b=_curriculum_integer(a),_curriculum_integer(b)
        if op not in ('+','-','*'):raise ValueError('Operador não permitido')
        request=route_math_message('quanto é '+str(a)+' '+op+' '+str(b));result=_run_math_direct(request)
        answer=str(_math_decode(result['result']));certificate=dict(method='OMNIMAT: aritmética racional exata',verification=result['verification'])
    elif family=='gcd':
        if not isinstance(data,list) or len(data)!=2:raise ValueError('MDC exige dois inteiros')
        a,b=[abs(_curriculum_integer(v)) for v in data];g,u,v=calcular('nt.egcd',a,b)
        if g!=math.gcd(a,b) or a*u+b*v!=g:raise ArithmeticError('Certificado Bézout inválido')
        answer=str(g);certificate=dict(method='OMNIMAT egcd + math.gcd + identidade de Bézout',u=u,v=v,g=g)
    elif family=='ode_linear':
        if not isinstance(data,list) or len(data)!=3:raise ValueError('EDO: [y0,k,T]')
        y0,k,T=[_curriculum_integer(v) for v in data];answer=str(y0+k*T)
        expression=f'({y0})+({k})*t';poly=_exact_polynomial(_proof_expression(expression),'t');derivative={}
        for (power,),coefficient in poly.items():
            if power:derivative[(power-1,)]=coefficient*power
        valid=derivative.get((0,),Fraction(0))==k and set(derivative)<={(0,)} and poly.get((0,),Fraction(0))==y0
        if not valid:raise ArithmeticError('Solução linear da EDO inválida')
        certificate=dict(method='Diferenciação polinomial racional + condição inicial, y\'=k constante',solution=expression,verified=True,
            domain='EDO escalar linear constante, não simulador físico geral')
    elif family=='tsp':
        import itertools
        matrix=np.asarray(data)
        if matrix.ndim!=2 or matrix.shape[0]!=matrix.shape[1] or not 3<=len(matrix)<=5 or matrix.dtype.kind not in 'iu' or np.any(matrix<0) or np.max(matrix)>20 or np.any(np.diag(matrix)!=0):raise ValueError('TSP: matriz inteira 3–5, custos 0–20, diagonal zero')
        n=len(matrix);dp={(1,0):0}
        for mask in range(1,1<<n):
            if not mask&1:continue
            for j in range(n):
                if (mask,j) not in dp:continue
                for k in range(1,n):
                    if not mask>>k&1:
                        key=(mask|1<<k,k);dp[key]=min(dp.get(key,math.inf),dp[mask,j]+int(matrix[j,k]))
        optimum=min(dp[(1<<n)-1,j]+int(matrix[j,0]) for j in range(1,n));best=math.inf;best_route=None
        for route in itertools.permutations(range(1,n)):
            full=(0,)+route+(0,);cost=sum(int(matrix[a,b]) for a,b in zip(full,full[1:]))
            if cost<best:best,best_route=cost,list(full)
        if optimum!=best:raise ArithmeticError('Divergência entre programação dinâmica e enumeração TSP')
        answer=str(optimum);certificate=dict(method='Held–Karp + enumeração independente de todos os tours, n<=5',route=best_route,cost=best,verified=True)
    else:raise ValueError('Famílias: arithmetic, gcd, ode_linear, tsp')
    return dict(answer=answer,certificate=certificate,verified=True,family=family,source='exact_synthetic_task_not_real_observation')


def generate_synthetic_problem(rng,family=None):
    family=family or ('arithmetic','gcd','ode_linear','tsp')[int(rng.integers(4))]
    if family=='arithmetic':
        a,b=map(int,rng.integers(-12,13,2));op=('+','-','*')[int(rng.integers(3))];data=[a,op,b];prompt=f'Calcule {a} {op} {b}. Responda só o número inteiro.'
    elif family=='gcd':
        a,b=map(int,rng.integers(1,51,2));data=[a,b];prompt=f'MDC de {a} e {b}. Responda só o número inteiro.'
    elif family=='ode_linear':
        y0,k,T=map(int,rng.integers(0,8,3));data=[y0,k,T];prompt=f'EDO y\'={k}, y(0)={y0}. Quanto é y({T})? Responda só o número inteiro.'
    elif family=='tsp':
        n=int(rng.integers(3,6));matrix=rng.integers(1,10,(n,n));np.fill_diagonal(matrix,0);data=matrix.tolist();prompt='Custo mínimo do ciclo TSP começando em 0: '+json.dumps(data,separators=(',',':'))+'. Só o inteiro.'
    else:raise ValueError('Família sintética desconhecida')
    return dict(family=family,data=data,prompt=prompt)


def synthetic_state(seed=8008):
    return dict(version=1,attempts=0,solved=0,training_accepted=0,training_rejected=0,teacher_labels=0,rng=np.random.default_rng(seed).bit_generator.state,recent=[])


class SyntheticCurriculum:
    """Daemon opt-in. Trabalha somente em pausas, com dados exatos e retenção.

    Self-play treina apenas respostas corretas. Teacher mode é explicitamente
    supervisão do solver, útil para partida a frio; não é descoberta de teoremas.
    """
    def __init__(self,lab):
        self.lab=lab;self.stop_event=threading.Event();self.thread=None;self.mode='selfplay';self.interval=2.;self.idle_seconds=2.;self.identity='NEURON-1';self.steps=1
    def start(self,identity='NEURON-1',*,teacher=False,interval=2.,idle_seconds=2.,steps=1):
        if type(teacher) is not bool or not .2<=interval<=60 or not .2<=idle_seconds<=60 or type(steps) is not int or not 1<=steps<=4:raise ValueError('Limites do currículo inválidos')
        self.lab._require_model();self.lab._agent(identity)
        if not isinstance(self.lab.backend,(NativeSeq2Seq,CompactEncoderDecoder)):raise ValueError('Currículo local usa NumPy nativo ou compacto, sem alterar T5 congelado')
        if isinstance(self.lab.backend,NativeSeq2Seq) and self.lab.backend.dimension>64:raise ValueError('Currículo limita o núcleo nativo a dimensão 64')
        if self.thread and self.thread.is_alive():raise ValueError('Currículo já está ativo')
        self.identity,self.mode,self.interval,self.idle_seconds,self.steps=identity,'verified_teacher' if teacher else 'selfplay',float(interval),float(idle_seconds),steps
        self.stop_event.clear();self.thread=threading.Thread(target=self._loop,name='SyntheticCurriculum',daemon=True);self.thread.start()
        self.lab.history.append('curriculum.started','curriculum',self.status());return self.status()
    def status(self):return dict(running=bool(self.thread and self.thread.is_alive() and not self.stop_event.is_set()),mode=self.mode,interval=self.interval,idle_seconds=self.idle_seconds,agent=self.identity,steps=self.steps)
    def _loop(self):
        while not self.stop_event.wait(self.interval):
            if time.monotonic()-self.lab.last_activity<self.idle_seconds:continue
            pending=getattr(self.lab,'foreground_queue',None)
            if pending is not None and not pending.empty():continue
            if not self.lab._lock.acquire(False):continue
            try:
                if self.stop_event.is_set() or time.monotonic()-self.lab.last_activity<self.idle_seconds:continue
                self.lab.curriculum_step(self.identity,teacher=self.mode=='verified_teacher',steps=self.steps)
            except Exception as error:
                self.lab.history.append('curriculum.failed','curriculum',dict(error=type(error).__name__,message=str(error)));self.stop_event.set()
            finally:self.lab._lock.release()
    def stop(self):
        self.stop_event.set()
        if self.thread is not None and self.thread is not threading.current_thread():
            deadline=time.monotonic()+30
            while self.thread.is_alive() and time.monotonic()<deadline:self.thread.join(.25)
            if self.thread.is_alive():raise RuntimeError('Currículo ainda finaliza uma operação; histórico permanece aberto')
        return self.status()


def curriculum_step_impl(lab,identity,teacher=False,steps=1,family=None):
    if type(teacher) is not bool or type(steps) is not int or not 1<=steps<=4:raise ValueError('Parâmetros de currículo inválidos')
    lab._require_model();core=lab.backend
    if not isinstance(core,(NativeSeq2Seq,CompactEncoderDecoder)) or isinstance(core,NativeSeq2Seq) and core.dimension>64:raise ValueError('Currículo usa modelos NumPy pequenos')
    agent=lab._agent(identity);agent.ensure_bridge(core);state=lab.synthetic_state;rng=np.random.default_rng();rng.bit_generator.state=state['rng']
    problem=generate_synthetic_problem(rng,family);observations=agent.unit.steps;context=agent.last_context.copy()
    # O aprendiz é consultado ANTES do solver; não passa pelo roteador que forneceria a resposta.
    proposed,inspection=core.generate(core.encode(problem['prompt']),agent.bridge,context)
    receipt=FormalCortex(lab.history,'curriculum',timeout=5).run(dict(op='system.curriculum',args=[dict(family=problem['family'],data=problem['data'])]))
    verified=receipt['result'];target=verified['answer'];candidate=proposed.strip();solved=bool(re.fullmatch(r'[+-]?\d{1,20}',candidate)) and int(candidate)==int(target)
    state['attempts']+=1;state['solved']+=int(solved);state['rng']=rng.bit_generator.state;report=None;accepted=False;train_source=None
    if solved or teacher:
        train_source='verified_selfplay' if solved else 'verified_synthetic_teacher';state['teacher_labels']+=int(not solved)
        before={k:v.copy() for k,v in agent.bridge.arrays.items()}
        probes=[('Calcule 2 + 3. Só o número.','5'),('MDC de 6 e 9. Só o número.','3'),('Calcule 2 * 4. Só o número.','8')]
        def retention():
            if isinstance(core,NativeSeq2Seq):return float(np.mean([core.loss_grad(core.encode(q),agent.bridge,np.zeros(48),a)[0] for q,a in probes]))
            return float(np.mean([agent.bridge.language().coding_metrics(a)['bits_per_byte'] for q,a in probes]))
        old_loss=retention();report=core.teach(core.encode(problem['prompt']),agent.bridge,context,target,steps=steps,rate=.1);new_loss=retention();accepted=math.isfinite(new_loss) and new_loss<=old_loss+.02
        if not accepted:agent.bridge.arrays=before;state['training_rejected']+=1
        else:state['training_accepted']+=1
        report.update(retention_before=old_loss,retention_after=new_loss,retention_tolerance=.02,accepted=accepted,source=train_source)
    if agent.unit.steps!=observations:raise AssertionError('Currículo não pode criar observações reais')
    summary=dict(attempt=state['attempts'],problem=problem,learner_answer=proposed,learner_correct=solved,oracle_answer=target,oracle_receipt=receipt['id'],
        learner_inspection=inspection,trained=accepted,training=report,mode='verified_teacher' if teacher else 'selfplay',bptt=isinstance(core,NativeSeq2Seq),observations_before=observations,observations_after=agent.unit.steps)
    state['recent'].append(summary);state['recent']=state['recent'][-32:]
    lab.history.append('curriculum.attempt',identity,summary)
    if isinstance(agent.bridge,CompactBridge) and agent.bridge.language().tokenizer is not None:agent.bridge.language().tokenizer.persist(lab.history,identity)
    return summary


EIGHT_ACTIONS={'thought_config','bpe_status','bpe_enable','curriculum_step','curriculum_start','curriculum_stop','symbolic_prove'}


def add_eight_commands(commands):
    prove=commands.add_parser('prove',help='Equivalência exata em Q[x] ou circuito booleano finito')
    prove.add_argument('old');prove.add_argument('new');prove.add_argument('--variables');prove.add_argument('--assume',action='append',default=[]);prove.add_argument('--boolean',action='store_true');prove.add_argument('--directory',type=Path,default=Path('neuron_data/provas'))
    bpe=commands.add_parser('bpe',help='Treina BPE byte a byte e persiste vocabulário/trie em SQLite')
    bpe.add_argument('mode',choices=('inspect','train','encode'));bpe.add_argument('text',nargs='?',default='');bpe.add_argument('--file',type=Path);bpe.add_argument('--directory',type=Path,default=Path('neuron_data/compacto'))
    curriculum=commands.add_parser('curriculum',help='Dados sintéticos exatos; self-play ou professor verificado explícito')
    curriculum.add_argument('--directory',type=Path,default=Path('neuron_data/curriculo'));curriculum.add_argument('--model',default='numpy:tiny');curriculum.add_argument('--rounds',type=int,default=10);curriculum.add_argument('--teacher',action='store_true');curriculum.add_argument('--steps',type=int,default=1);curriculum.add_argument('--thought-budget',type=int,default=0);curriculum.add_argument('--constitution',action='store_true')
    think=commands.add_parser('think',help='Inferência NumPy com recorrências latentes observáveis e orçamento')
    think.add_argument('text');think.add_argument('--model',default='numpy:tiny');think.add_argument('--directory',type=Path,default=Path('neuron_data/pensamento'));think.add_argument('--thought-budget',type=int,default=4);think.add_argument('--seconds',type=float,default=5.)
    return {'prove','bpe','curriculum','think'}


def run_eight_cli(args):
    if args.command=='prove':
        request=dict(op='system.boolean_equivalence' if args.boolean else 'system.symbolic_equivalence',args=[args.old,args.new],kwargs={} if args.boolean else dict(variables=args.variables,assumptions=args.assume))
        with RunLease(args.directory/'writer.lock'),EventHistory(args.directory/'history.sqlite') as history:
            receipt=FormalCortex(history,'proof',timeout=10).run(request);print(json.dumps(receipt,ensure_ascii=False,indent=2))
        return 0 if receipt['result'].get('proved') else 3
    if args.command=='bpe':
        with NeuronLaboratory(args.directory,LabConfig(agents=1,model='compact:pt')) as lab:
            lab.load_model();agent=lab.agents[0];agent.ensure_bridge(lab.backend);language=CompressedLanguageModel.load(agent.bridge.language().dump())
            if args.mode=='train':
                if args.file is not None:result=read_language_sources(lab,agent.identity,files=[args.file])
                else:
                    language.enable_bpe();result=language.learn(args.text,'local:bpe-cli');agent.bridge.store(language);lab.checkpoint()
                language=agent.bridge.language()
            elif args.mode=='encode':
                language.enable_bpe();ids=language.tokenizer.encode(args.text);result=dict(ids=ids,roundtrip=language.tokenizer.decode(ids),bytes=len(args.text.encode()),tokens=len(ids))
            else:result=language.stats()
            if language.tokenizer is not None:language.tokenizer.persist(lab.history,agent.identity)
            print(json.dumps(result,ensure_ascii=False,indent=2))
        return 0
    if args.command=='curriculum':
        if type(args.rounds) is not int or not 0<=args.rounds<=10000:raise ValueError('Rodadas 0–10000; zero ativa daemon até Ctrl+C')
        cfg=LabConfig(agents=1,model=args.model,thought_budget=args.thought_budget,constitutional_projection=args.constitution)
        with NeuronLaboratory(args.directory,cfg) as lab:
            lab.load_model()
            if args.rounds:
                for _ in range(args.rounds):print(json.dumps(lab.curriculum_step('NEURON-1',teacher=args.teacher,steps=args.steps),ensure_ascii=False),flush=True)
            else:
                lab.curriculum.start(teacher=args.teacher,steps=args.steps)
                print('Currículo opt-in ativo; Ctrl+C encerra com checkpoint.',flush=True)
                try:
                    while not lab.curriculum.stop_event.wait(.5):pass
                except KeyboardInterrupt:pass
        return 0
    if args.command=='think':
        cfg=LabConfig(agents=1,model=args.model,thought_budget=args.thought_budget,inference_seconds=args.seconds)
        with NeuronLaboratory(args.directory,cfg) as lab:
            lab.load_model()
            if not isinstance(lab.backend,NativeSeq2Seq):raise ValueError('Recorrência latente disponível para --model numpy:tiny ou numpy:modelo.npz')
            agent=lab.agents[0];agent.ensure_bridge(lab.backend);answer,inspection=lab.backend.generate(lab.backend.encode(args.text),agent.bridge,agent.last_context)
            lab.history.append('thought.inference',agent.identity,dict(input=args.text,output=answer,inspection=inspection));print(json.dumps(dict(text=answer,thought=inspection['thought']),ensure_ascii=False,indent=2))
        return 0
    raise ValueError('Comando NEURON 8 desconhecido')


class MetaProgrammer:
    """Altera apenas adaptive_kernel e publica candidato + relatório + backup.

    AST restringe sintaxe; regressões e amostras não provam correção universal.
    Apply é explícito, confere hash e executa selftest do arquivo candidato.
    Não há execução de patches recebidos pela rede nem reinício automático.
    """
    def __init__(self,source,directory,history=None):
        self.source=Path(source).resolve();self.directory=Path(directory).resolve();self.history=history
        self.directory.mkdir(parents=True,exist_ok=True)

    def inspect(self):
        source=self.source.read_text(encoding='utf-8');tree=ast.parse(source)
        return dict(path=str(self.source),sha256=hashlib.sha256(source.encode()).hexdigest(),
            classes=[n.name for n in tree.body if isinstance(n,ast.ClassDef)],
            functions=[n.name for n in tree.body if isinstance(n,(ast.FunctionDef,ast.AsyncFunctionDef))],
            editable=['adaptive_kernel'],limitations='AST não constitui prova formal; só kernel escalar restrito.')

    def stage(self,expression):
        expr=_kernel_expression(expression)
        source=self.source.read_text(encoding='utf-8');parent=hashlib.sha256(source.encode()).hexdigest();tree=ast.parse(source)
        target=next(n for n in tree.body if isinstance(n,ast.FunctionDef) and n.name=='adaptive_kernel')
        reference=next(n for n in target.body if isinstance(n,ast.Return)).value
        reference=ast.Expression(body=reference);_kernel_expression(ast.unparse(reference))
        formal=symbolic_equivalence_check(reference,expr)
        if not verify_symbolic_equivalence(formal):raise ValueError('Equivalência racional não provada: '+formal.get('reason',formal['status']))
        samples=np.concatenate(([0,1,-1,1e-9,-1e-9,1e6,-1e6],np.random.default_rng(656).uniform(-1000,1000,256)))
        for x in samples:
            a=float(_kernel_eval(reference,float(x)));b=float(_kernel_eval(expr,float(x)))
            if not math.isfinite(b) or not math.isclose(a,b,rel_tol=1e-9,abs_tol=1e-8):raise ValueError('Candidato falhou na retenção do kernel')
        replacement='def adaptive_kernel(x):\n    """Kernel restrito atualizado por candidato testado."""\n    return '+ast.unparse(expr.body)+'\n'
        lines=source.splitlines(keepends=True);lines[target.lineno-1:target.end_lineno]=[replacement]
        candidate=''.join(lines);compile(candidate,str(self.source),'exec')
        child=hashlib.sha256(candidate.encode()).hexdigest();path=self.directory/(child+'.py')
        path.write_text(candidate,encoding='utf-8')
        points=[float(x) for x in samples[:32]]
        started=time.perf_counter()
        process=subprocess.run([sys.executable,str(path),'_kernel-worker'],input=json.dumps(points),text=True,capture_output=True,timeout=5)
        if process.returncode:raise ValueError('Candidato isolado falhou: '+process.stderr[:500])
        values=json.loads(process.stdout)
        if len(values)!=len(points) or any(not math.isclose(v,_kernel_eval(reference,x),rel_tol=1e-9,abs_tol=1e-8) for v,x in zip(values,points)):raise ValueError('Saída do candidato não preserva referência')
        # Medianas em processos separados: observação de tempo, não prova de ganho.
        timings=[]
        for implementation in (self.source,path):
            observed=subprocess.run([sys.executable,str(implementation),'_kernel-benchmark'],capture_output=True,text=True,timeout=5)
            if observed.returncode:raise ValueError('Benchmark isolado falhou')
            timings.append(json.loads(observed.stdout)['median_ns_per_call'])
        report=dict(parent_sha256=parent,candidate_sha256=child,candidate=str(path),expression=expression,
            samples=len(samples),isolated_seconds=time.perf_counter()-started,tests='retention_samples_passed',
            applied=False,proof=True,symbolic_proof=formal,scope='adaptive_kernel only; equivalence in Q[x], not IEEE754',
            baseline_ns_per_call=timings[0],candidate_ns_per_call=timings[1],observed_speedup=timings[0]/max(1e-9,timings[1]),
            timing_caveat='Microbenchmark observado; ruído e plataforma podem inverter o resultado.')
        (self.directory/(child+'.json')).write_text(json.dumps(report,indent=2),encoding='utf-8')
        if self.history:self.history.append('meta.staged','meta',report)
        return report

    def evolve(self):
        attempts=[]
        for expression in ('(x+1)**2','(x+1)*(x+1)','x*(x+2)+1'):
            try:attempts.append(self.stage(expression))
            except (ValueError,ArithmeticError):continue
        eligible=[r for r in attempts if r['observed_speedup']>1.02]
        selected=min(eligible,key=lambda r:r['candidate_ns_per_call']) if eligible else None
        report=dict(attempts=attempts,selected=None if selected is None else selected['candidate_sha256'],
            applied=False,scope='Três reescritas algébricas predefinidas do kernel; não inventa algoritmos nem modifica o cérebro.')
        if self.history:self.history.append('meta.evolved','meta',report)
        return report

    def apply(self,candidate_hash):
        if not re.fullmatch('[0-9a-f]{64}',candidate_hash):raise ValueError('Hash inválido')
        path=self.directory/(candidate_hash+'.py');report=json.loads((self.directory/(candidate_hash+'.json')).read_text())
        current=self.source.read_bytes();candidate=path.read_bytes()
        if hashlib.sha256(current).hexdigest()!=report['parent_sha256']:raise ValueError('Fonte mudou depois do estágio')
        if hashlib.sha256(candidate).hexdigest()!=candidate_hash:raise ValueError('Candidato adulterado')
        # Revalida que a única diferença é o corpo do kernel.
        before,after=ast.parse(current),ast.parse(candidate)
        targets=[next(n for n in tree.body if isinstance(n,ast.FunctionDef) and n.name=='adaptive_kernel') for tree in (before,after)]
        if ast.dump(targets[0].args)!=ast.dump(targets[1].args) or targets[1].decorator_list or targets[1].returns is not None or targets[1].type_comment is not None:
            raise ValueError('Assinatura ou decoradores do kernel alterados')
        if any(not isinstance(n,ast.Return) and not (isinstance(n,ast.Expr) and isinstance(n.value,ast.Constant) and isinstance(n.value.value,str)) for n in targets[1].body):
            raise ValueError('Só docstring e retorno são permitidos no kernel')
        formal=symbolic_equivalence_check(targets[0],targets[1])
        if not verify_symbolic_equivalence(formal):raise ValueError('Candidato sem prova racional válida')
        for tree in (before,after):
            for i,node in enumerate(tree.body):
                if isinstance(node,ast.FunctionDef) and node.name=='adaptive_kernel':
                    if tree is after:
                        returns=[n for n in node.body if isinstance(n,ast.Return)]
                        if len(returns)!=1:raise ValueError('Kernel inválido')
                        _kernel_expression(ast.unparse(returns[0].value))
                        if len(node.body)>2:raise ValueError('Corpo do kernel inválido')
                    tree.body[i]=ast.FunctionDef(name='adaptive_kernel',args=ast.arguments(posonlyargs=[],args=[],kwonlyargs=[],kw_defaults=[],defaults=[]),body=[ast.Pass()],decorator_list=[])
        if ast.dump(before,include_attributes=False)!=ast.dump(after,include_attributes=False):raise ValueError('Patch altera funções fora do kernel')
        result=subprocess.run([sys.executable,str(path),'selftest'],capture_output=True,text=True,timeout=180)
        log=self.directory/(candidate_hash+'.tests.log');log.write_text(result.stdout+result.stderr)
        if result.returncode:raise ValueError('Regressão no candidato; consulte '+str(log))
        # Reconfere depois dos testes para evitar sobrescrever edição concorrente.
        if self.source.read_bytes()!=current:raise ValueError('Fonte mudou durante os testes')
        backup=self.directory/(report['parent_sha256']+'.backup.py');backup.write_bytes(current)
        handle,tmp=tempfile.mkstemp(dir=self.source.parent,prefix='.neuron-meta-',suffix='.py')
        try:
            with os.fdopen(handle,'wb') as file:file.write(candidate);file.flush();os.fsync(file.fileno())
            os.chmod(tmp,self.source.stat().st_mode & 0o777);os.replace(tmp,self.source)
        finally:
            if os.path.exists(tmp):os.unlink(tmp)
        report.update(applied=True,backup=str(backup),regression='selftest passed',restart_required=True)
        (self.directory/(candidate_hash+'.json')).write_text(json.dumps(report,indent=2))
        if self.history:self.history.append('meta.applied','meta',report)
        return report

    def rollback(self,candidate_hash):
        if not re.fullmatch('[0-9a-f]{64}',candidate_hash):raise ValueError('Hash inválido')
        report=json.loads((self.directory/(candidate_hash+'.json')).read_text())
        if hashlib.sha256(self.source.read_bytes()).hexdigest()!=candidate_hash:raise ValueError('Fonte atual difere do candidato')
        backup=self.directory/(report['parent_sha256']+'.backup.py');data=backup.read_bytes()
        if hashlib.sha256(data).hexdigest()!=report['parent_sha256']:raise ValueError('Backup adulterado')
        handle,tmp=tempfile.mkstemp(dir=self.source.parent,prefix='.neuron-rollback-')
        try:
            with os.fdopen(handle,'wb') as file:file.write(data);file.flush();os.fsync(file.fileno())
            os.chmod(tmp,self.source.stat().st_mode & 0o777);os.replace(tmp,self.source)
        finally:
            if os.path.exists(tmp):os.unlink(tmp)
        if self.history:self.history.append('meta.rolled_back','meta',dict(candidate=candidate_hash,parent=report['parent_sha256']))
        return dict(restored=report['parent_sha256'],restart_required=True)


@dataclass
class ToolPolicy:
    root: Path
    allow_write: bool = False
    http_hosts: tuple = ()
    commands: tuple = ()  # listas argv completas, fornecidas explicitamente pelo operador
    max_bytes: int = 65536
    timeout: float = 5.
    allow_desktop: bool = False

    def __post_init__(self):
        self.root=Path(self.root).resolve();self.root.mkdir(parents=True,exist_ok=True)
        if not 1024<=self.max_bytes<=262144 or not .1<=self.timeout<=30:raise ValueError('Limites de ferramentas inválidos')


class ToolHarness:
    def __init__(self,policy,history=None):self.policy,self.history=policy,history

    def path(self,value):
        p=Path(value)
        if p.is_absolute():raise ValueError('Caminho deve ser relativo à pasta de ferramentas')
        target=(self.policy.root/p).resolve()
        if not target.is_relative_to(self.policy.root):raise ValueError('Caminho sai da pasta autorizada')
        return target

    def run(self,name,args=None):
        args=args or {};identifier=uuid.uuid4().hex
        if not isinstance(args,dict):raise ValueError('Argumentos devem ser objeto JSON')
        if self.history:self.history.append('tool.requested','tools',dict(id=identifier,tool=name,args=args))
        try:
            result=self._run(name,args)
        except Exception as error:
            if self.history:self.history.append('tool.failed','tools',dict(id=identifier,error=type(error).__name__,message=str(error)))
            raise
        if self.history:self.history.append('tool.completed','tools',dict(id=identifier,tool=name,result=result))
        return dict(id=identifier,tool=name,result=result)

    def _run(self,name,args):
        if name=='files.list':
            p=self.path(args.get('path','.'))
            if not p.is_dir():raise ValueError('Pasta inexistente')
            import itertools
            rows=[]
            for c in itertools.islice(p.iterdir(),201):
                if c.is_symlink():continue
                rows.append(dict(name=c.name,directory=c.is_dir()))
            return dict(entries=rows[:200],truncated=len(rows)>200)
        if name=='files.read':
            with self.path(args['path']).open('rb') as file:data=file.read(self.policy.max_bytes+1)
            return dict(text=data[:self.policy.max_bytes].decode('utf-8','replace'),truncated=len(data)>self.policy.max_bytes)
        if name=='files.write':
            if not self.policy.allow_write:raise PermissionError('Escrita desabilitada na política')
            data=args['text'].encode('utf-8');target=self.path(args['path'])
            if len(data)>self.policy.max_bytes:raise ValueError('Arquivo excede limite')
            if target.exists() and args.get('expected_sha256')!=hashlib.sha256(target.read_bytes()).hexdigest():raise ValueError('Para sobrescrever, forneça expected_sha256 atual')
            target.parent.mkdir(parents=True,exist_ok=True)
            handle,tmp=tempfile.mkstemp(dir=target.parent,prefix='.tool-')
            try:
                with os.fdopen(handle,'wb') as file:file.write(data)
                os.replace(tmp,target)
            finally:
                if os.path.exists(tmp):os.unlink(tmp)
            return dict(path=str(target.relative_to(self.policy.root)),bytes=len(data),sha256=hashlib.sha256(data).hexdigest())
        if name in ('desktop.plan','desktop.execute'):
            controller=DesktopController(live=name=='desktop.execute' and self.policy.allow_desktop,stop_file=self.policy.root/'STOP',history=self.history)
            try:return controller.execute(args.get('actions'))
            finally:controller.close()
        if name=='math.calculate':return FormalCortex(self.history,'tools').run(args)
        if name=='source.inspect':return MetaProgrammer(Path(__file__),self.policy.root/'patches',self.history).inspect()
        if name=='http.get':return self.http_get(args['url'])
        if name=='process.run':return self.process(args['argv'])
        raise ValueError('Ferramenta desconhecida')

    def http_get(self,url):
        from urllib.parse import urlsplit
        import urllib.request
        import ipaddress
        parsed=urlsplit(url);host=(parsed.hostname or '').lower()
        if parsed.scheme!='https' or parsed.username or parsed.password or parsed.port not in (None,443):raise ValueError('Somente HTTPS na porta 443 sem credenciais')
        if host not in self.policy.http_hosts:raise PermissionError('Host não autorizado explicitamente')
        addresses=socket.getaddrinfo(host,443,type=socket.SOCK_STREAM)
        if not addresses or any(not ipaddress.ip_address(a[4][0]).is_global for a in addresses):raise ValueError('HTTP só permite endereços públicos')
        class NoRedirect(urllib.request.HTTPRedirectHandler):
            def redirect_request(self,*_):raise ValueError('Redirecionamento desabilitado; autorize o destino explicitamente')
        import http.client
        resolved=addresses[0][4][0]
        class PinnedHTTPS(http.client.HTTPSConnection):
            def connect(self):
                self.sock=socket.create_connection((resolved,443),timeout=self.timeout,source_address=self.source_address)
                self.sock=self._context.wrap_socket(self.sock,server_hostname=self.host)
        class PinnedHandler(urllib.request.HTTPSHandler):
            def https_open(self,request):return self.do_open(PinnedHTTPS,request,context=self._context)
        opener=urllib.request.build_opener(urllib.request.ProxyHandler({}),NoRedirect(),PinnedHandler())
        request=urllib.request.Request(url,headers={'User-Agent':'NEURON/6 local-tool','Accept':'text/html,text/plain,application/json','Accept-Encoding':'identity'})
        with opener.open(request,timeout=self.policy.timeout) as response:
            content=response.read(self.policy.max_bytes+1);kind=response.headers.get_content_type()
            if kind not in ('text/plain','text/html','application/json'):raise ValueError('Resposta não textual')
            text=content[:self.policy.max_bytes].decode(response.headers.get_content_charset() or 'utf-8','replace')
            if kind=='text/html':
                from html.parser import HTMLParser
                class Extract(HTMLParser):
                    def __init__(self):super().__init__();self.parts=[];self.hidden=0
                    def handle_starttag(self,tag,attrs):
                        if tag in ('script','style'):self.hidden+=1
                    def handle_endtag(self,tag):
                        if tag in ('script','style'):self.hidden=max(0,self.hidden-1)
                    def handle_data(self,data):
                        if not self.hidden:self.parts.append(data)
                parser=Extract();parser.feed(text);text=' '.join(parser.parts)
        return dict(url=url,text=text,truncated=len(content)>self.policy.max_bytes,provenance='untrusted_web_data',instructions=False)

    def process(self,argv):
        if not isinstance(argv,list) or not all(isinstance(x,str) for x in argv) or tuple(argv) not in [tuple(x) for x in self.policy.commands]:raise PermissionError('Comando argv completo não autorizado na política')
        proc=subprocess.Popen(argv,cwd=self.policy.root,stdin=subprocess.DEVNULL,stdout=subprocess.PIPE,stderr=subprocess.STDOUT,start_new_session=os.name=='posix')
        data=bytearray();overflow=threading.Event()
        def drain():
            while True:
                chunk=proc.stdout.read1(4096)
                if not chunk:break
                remaining=self.policy.max_bytes-len(data);data.extend(chunk[:max(0,remaining)])
                if len(chunk)>remaining:overflow.set();kill();break
        def kill():
            try:
                if os.name=='posix':os.killpg(proc.pid,signal.SIGKILL)
                else:proc.kill()
            except ProcessLookupError:pass
        thread=threading.Thread(target=drain,daemon=True);thread.start();timed_out=False
        try:proc.wait(timeout=self.policy.timeout)
        except subprocess.TimeoutExpired:timed_out=True;kill();proc.wait()
        thread.join(timeout=1)
        if thread.is_alive():kill();proc.stdout.close()
        return dict(returncode=proc.returncode,output=bytes(data).decode('utf-8','replace'),truncated=overflow.is_set(),timed_out=timed_out,
            isolation='Comando autorizado do operador; não é sandbox de código arbitrário.')

    def plan(self,goal):
        # Um plano revisável, nunca ações extraídas de uma resposta neural.
        if not isinstance(goal,str) or len(goal)>4000:raise ValueError('Objetivo inválido')
        if goal.startswith('/tool '):
            request=json.loads(goal[6:]);return [dict(tool=request['tool'],args=request.get('args',{}))]
        math_request=route_math_message(goal)
        if math_request:return [dict(tool='math.calculate',args=math_request)]
        if re.search(r'\b(listar|liste)\b',goal.lower()):return [dict(tool='files.list',args={})]
        return []

    def execute_goal(self,goal,max_steps=4):
        if type(max_steps) is not int or not 1<=max_steps<=8:raise ValueError('Passos entre 1 e 8')
        plan=self.plan(goal)
        if not plan:return dict(status='needs_explicit_tool_request',plan=[],message='Use /tool {"tool":"files.list","args":{}} ou uma pergunta matemática reconhecida.')
        results=[]
        for step in plan[:max_steps]:results.append(self.run(step['tool'],step['args']))
        return dict(status='completed',plan=plan,results=results)


class SwarmProtocol:
    """Pares configurados + PSK HMAC; sem descoberta ou conexão oculta.

    Mensagens autenticadas, não cifradas: use localhost, LAN confiável ou túnel.
    Apenas tarefas matemáticas limitadas; nunca fonte, comandos ou sensores.
    """
    def __init__(self,key,history=None):
        if not isinstance(key,str) or len(key.encode())<32:raise ValueError('Chave compartilhada deve ter pelo menos 32 bytes')
        self.key=key.encode();self.history=history;self.seen=OrderedDict();self.lock=threading.RLock()
        if history:
            with history._lock:
                history.connection.execute('CREATE TABLE IF NOT EXISTS swarm_nonces (nonce TEXT PRIMARY KEY, utc REAL NOT NULL)');history.connection.commit()

    def sign(self,payload):
        body=dict(version=1,nonce=uuid.uuid4().hex,utc=time.time(),payload=payload)
        raw=json.dumps(body,sort_keys=True,separators=(',',':'),allow_nan=False).encode()
        return dict(body=body,mac=hmac.new(self.key,raw,hashlib.sha256).hexdigest())

    def verify(self,envelope):
        body=envelope['body'];raw=json.dumps(body,sort_keys=True,separators=(',',':'),allow_nan=False).encode()
        if len(raw)>262144 or not hmac.compare_digest(hmac.new(self.key,raw,hashlib.sha256).hexdigest(),envelope.get('mac','')):raise ValueError('Autenticação HMAC inválida')
        nonce=body.get('nonce');utc=body.get('utc')
        if body.get('version')!=1 or not isinstance(nonce,str) or not re.fullmatch('[0-9a-f]{32}',nonce) or type(utc) not in (float,int) or not math.isfinite(utc) or abs(time.time()-utc)>30:raise ValueError('Mensagem expirada ou protocolo inválido')
        with self.lock:
            if self.history:
                with self.history._lock:
                    conn=self.history.connection;conn.execute('DELETE FROM swarm_nonces WHERE utc<?',(time.time()-60,))
                    if conn.execute('SELECT count(*) FROM swarm_nonces').fetchone()[0]>=4096:raise ValueError('Limite de mensagens por janela')
                    try:conn.execute('INSERT INTO swarm_nonces VALUES(?,?)',(nonce,float(utc)));conn.commit()
                    except sqlite3.IntegrityError as error:raise ValueError('Mensagem repetida') from error
            else:
                now=time.time()
                self.seen=OrderedDict((k,t) for k,t in self.seen.items() if now-t<60)
                if nonce in self.seen:raise ValueError('Mensagem repetida')
                if len(self.seen)>=4096:raise ValueError('Limite de mensagens por janela')
                self.seen[nonce]=now
        return body['payload']

    @staticmethod
    def request(request):
        request=_bounded_math_request(request)
        if request.get('native') or request['op'] not in ('nt.factor','nt.is_prime','lg.dpll','gr.bellman_ford','system.solve'):raise ValueError('Operação não permitida no swarm')
        if request['op']=='nt.is_prime' and (not request.get('args') or type(request['args'][0]) is not int or not 0<=request['args'][0]<2**64):raise ValueError('Primalidade distribuída limitada a 64 bits')
        # Valida limites estruturais antes de aceitar a tarefa.
        if request['op'] in ('lg.dpll','gr.bellman_ford') and (not request.get('args') or not isinstance(request['args'][0],list) or len(request['args'][0])>64):raise ValueError('Tarefa excede 64 cláusulas/arestas')
        return request


def make_swarm_server(host,port,key,history=None):
    import socketserver
    protocol=SwarmProtocol(key,history);slots=threading.BoundedSemaphore(4)
    class Handler(socketserver.StreamRequestHandler):
        def handle(self):
            self.connection.settimeout(12)
            try:
                raw=self.rfile.readline(65537)
                if len(raw)>65536 or not raw.endswith(b'\n'):raise ValueError('Mensagem excede 64 KiB')
                payload=protocol.verify(json.loads(raw));request=protocol.request(payload['request'])
                if history:history.append('swarm.task.received','peer',dict(peer=self.client_address[0],request=request))
                receipt=FormalCortex(history,'swarm',timeout=5).run(request)
                response=dict(job=payload.get('job'),request_sha256=hashlib.sha256(json.dumps(request,sort_keys=True).encode()).hexdigest(),receipt=receipt)
                wire=json.dumps(protocol.sign(response),allow_nan=False).encode()+b'\n'
                if len(wire)>262144:raise ValueError('Resultado excede limite de rede')
                self.wfile.write(wire)
            except (OSError,ValueError,KeyError,TypeError,RuntimeError) as error:
                if history:history.append('swarm.rejected','peer',dict(error=type(error).__name__,message=str(error)))
    class Server(socketserver.ThreadingTCPServer):
        allow_reuse_address=True;daemon_threads=True;request_queue_size=8
        def process_request(self,request,address):
            if not slots.acquire(blocking=False):request.close();return
            try:super().process_request(request,address)
            except BaseException:slots.release();raise
        def process_request_thread(self,request,address):
            try:super().process_request_thread(request,address)
            finally:slots.release()
    return Server((host,port),Handler)


class SwarmClient:
    def __init__(self,peers,key,history=None):
        if not isinstance(peers,list) or not 1<=len(peers)<=16:raise ValueError('Configure de 1 a 16 pares')
        self.peers=[]
        for peer in peers:
            host,port=peer.rsplit(':',1);port=int(port)
            if not host or not 1<=port<=65535:raise ValueError('Par inválido')
            self.peers.append((host,port))
        self.protocol=SwarmProtocol(key,history);self.history=history

    def _task(self,request,index):
        request=self.protocol.request(request);job=uuid.uuid4().hex;peer=self.peers[index%len(self.peers)]
        request_hash=hashlib.sha256(json.dumps(request,sort_keys=True).encode()).hexdigest()
        wire=json.dumps(self.protocol.sign(dict(job=job,request=request))).encode()+b'\n'
        if len(wire)>65536:raise ValueError('Requisição de rede excede limite')
        if self.history:self.history.append('swarm.task.sent','swarm',dict(job=job,peer=peer,request=request))
        with socket.create_connection(peer,timeout=8) as connection:
            connection.settimeout(12);connection.sendall(wire)
            with connection.makefile('rb') as file:raw=file.readline(262145)
        if len(raw)>262144 or not raw.endswith(b'\n'):raise ValueError('Resposta de rede inválida')
        response=self.protocol.verify(json.loads(raw))
        if response.get('job')!=job or response.get('request_sha256')!=request_hash:raise ValueError('Resposta não corresponde à tarefa enviada')
        receipt=response['receipt'];result=_math_decode(receipt['result']);args=_math_decode(request.get('args',[]));operation=request['op']
        if receipt.get('operation')!=operation:raise ValueError('Operação do resultado incorreta')
        if operation=='system.solve':
            spec=args[0];family=spec.get('family');data=spec.get('data');arguments=[data] if family=='sat' else [data,spec.get('source',0)]
            valid=result.get('family')==family and _formal_verify(family,arguments,result['solution'])
        elif operation=='nt.is_prime':valid=type(result) is bool and result==bool(omnimat().is_prime(args[0]))
        else:valid=_verification(operation,args,result)['verified']
        if not valid:raise ArithmeticError('Resultado remoto não passou pelo verificador local')
        report=dict(job=job,peer=list(peer),request=request,result=receipt['result'],verified_locally=True,
            verification='Certificado/atribuição/distâncias conferidos localmente; PSK autentica o par, não garante a correção.')
        if self.history:self.history.append('swarm.task.verified','swarm',report)
        return report

    def map(self,requests):
        from concurrent.futures import ThreadPoolExecutor
        if not isinstance(requests,list) or not 1<=len(requests)<=32:raise ValueError('De 1 a 32 tarefas por lote')
        with ThreadPoolExecutor(max_workers=min(4,len(requests))) as pool:
            return list(pool.map(lambda item:self._task(item[1],item[0]),enumerate(requests)))


class NativeSensors:
    """Sensores amostrados; não implica reconhecimento de fala/objetos ou controle do desktop."""
    @staticmethod
    def features(kind,values):
        if kind not in ('camera','screen','microphone','screen-x11'):raise ValueError('Modalidade inválida')
        a=np.asarray(values,dtype=float)
        if a.ndim!=1 or not 32<=len(a)<=4096 or not np.isfinite(a).all():raise ValueError('Forneça 32–4096 amostras finitas')
        if kind=='microphone':
            if np.max(np.abs(a))>1:raise ValueError('Áudio deve estar normalizado entre -1 e 1')
            spectrum=np.abs(np.fft.rfft(a));parts=np.array_split(spectrum,32)
            pooled=np.array([np.mean(p) for p in parts]);pooled=np.log1p(pooled);pooled/=max(1.,float(np.max(pooled)))
        else:
            if a.min()<0 or a.max()>255:raise ValueError('Pixels devem estar entre 0 e 255')
            pooled=np.array([p.mean() for p in np.array_split(a,32)])/127.5-1
        return pooled

    @staticmethod
    def screen_x11():
        if not sys.platform.startswith('linux'):raise RuntimeError('Captura ctypes direta disponível neste backend apenas para Linux/X11; use captura do navegador no Windows/macOS/Wayland')
        if not os.environ.get('DISPLAY'):raise RuntimeError('Sem DISPLAY X11; use o seletor de tela do navegador')
        import ctypes as C
        import ctypes.util
        library=ctypes.util.find_library('X11')
        if not library:raise RuntimeError('libX11 ausente')
        lib=C.CDLL(library)
        lib.XOpenDisplay.argtypes=[C.c_char_p];lib.XOpenDisplay.restype=C.c_void_p
        lib.XDefaultRootWindow.argtypes=[C.c_void_p];lib.XDefaultRootWindow.restype=C.c_ulong
        lib.XDefaultScreen.argtypes=[C.c_void_p];lib.XDefaultScreen.restype=C.c_int
        for name in ('XDisplayWidth','XDisplayHeight'):
            fn=getattr(lib,name);fn.argtypes=[C.c_void_p,C.c_int];fn.restype=C.c_int
        lib.XGetImage.argtypes=[C.c_void_p,C.c_ulong,C.c_int,C.c_int,C.c_uint,C.c_uint,C.c_ulong,C.c_int];lib.XGetImage.restype=C.c_void_p
        lib.XGetPixel.argtypes=[C.c_void_p,C.c_int,C.c_int];lib.XGetPixel.restype=C.c_ulong
        lib.XDestroyImage.argtypes=[C.c_void_p];lib.XDestroyImage.restype=C.c_int
        lib.XCloseDisplay.argtypes=[C.c_void_p];lib.XCloseDisplay.restype=C.c_int
        display=lib.XOpenDisplay(None)
        if not display:raise RuntimeError('Não foi possível abrir o display X11')
        image=None
        try:
            screen=lib.XDefaultScreen(display);width=lib.XDisplayWidth(display,screen);height=lib.XDisplayHeight(display,screen)
            if not 1<=width<=8192 or not 1<=height<=8192:raise ValueError('Resolução X11 fora do limite')
            image=lib.XGetImage(display,lib.XDefaultRootWindow(display),0,0,width,height,C.c_ulong(-1).value,2)
            if not image:raise RuntimeError('XGetImage falhou')
            # XImage expõe máscaras RGB; não se assume layout de bytes do framebuffer.
            class XImageHead(C.Structure):
                _fields_=[('width',C.c_int),('height',C.c_int),('xoffset',C.c_int),('format',C.c_int),('data',C.c_void_p),('byte_order',C.c_int),('bitmap_unit',C.c_int),('bitmap_bit_order',C.c_int),('bitmap_pad',C.c_int),('depth',C.c_int),('bytes_per_line',C.c_int),('bits_per_pixel',C.c_int),('red_mask',C.c_ulong),('green_mask',C.c_ulong),('blue_mask',C.c_ulong)]
            head=C.cast(image,C.POINTER(XImageHead)).contents
            def channel(pixel,mask):
                if not mask:return 0.
                shift=(mask & -mask).bit_length()-1;return ((pixel&mask)>>shift)/float(mask>>shift)*255
            pixels=[]
            for y in np.linspace(0,height-1,24,dtype=int):
                for x in np.linspace(0,width-1,32,dtype=int):
                    v=int(lib.XGetPixel(image,int(x),int(y)))
                    pixels.append(.2126*channel(v,head.red_mask)+.7152*channel(v,head.green_mask)+.0722*channel(v,head.blue_mask))
            return dict(kind='screen-x11',width=32,height=24,values=pixels,source='ctypes/libX11',original_size=[width,height])
        finally:
            if image:lib.XDestroyImage(image)
            lib.XCloseDisplay(display)


def _ws_frame(payload,opcode=2):
    payload=bytes(payload);n=len(payload)
    if n>262144:raise ValueError('Frame muito grande')
    return bytes([0x80|opcode,n]) + payload if n<126 else bytes([0x80|opcode,126])+struct.pack('!H',n)+payload if n<65536 else bytes([0x80|opcode,127])+struct.pack('!Q',n)+payload


def neural_stream_packet(lab,identity,sequence=0):
    """Protocolo: NRN6 + uint32 sequência + uint32 contagem + floats little-endian.

    Amostras de pesos reais; posições no desenho são um layout visual fixo,
    não uma reconstrução biológica ou uma explicação causal do raciocínio.
    """
    with lab._lock:
        agent=lab._agent(identity)
        native=isinstance(agent.bridge,NativeBridge)
        compact=isinstance(agent.bridge,CompactBridge)
        parameters=({'conditioning_B':agent.bridge.arrays['B'],'ppm_counts':np.array(list(agent.bridge.language().counts[()].values()),dtype=float)} if compact else agent.bridge.arrays) if native else agent.task.core.p
        chunks=[];groups=[];total=sum(v.size for k,v in parameters.items() if k!='updates')
        for k in sorted(parameters):
            if k=='updates':continue
            a=parameters[k].ravel();n=min(256,len(a));idx=np.linspace(0,max(0,len(a)-1),n,dtype=int)
            groups.append(dict(name=k,shape=list(parameters[k].shape),offset=sum(len(c) for c in chunks),count=n))
            chunks.append(a[idx].astype('<f4'))
        values=np.concatenate(chunks) if chunks else np.empty(0,dtype='<f4')
        metadata=dict(type='neural-frame',version=1,agent=identity,sequence=sequence,groups=groups,total_parameters=total,
            samples=len(values),source='compact_conditioning_and_learned_counts' if compact else 'native_seq2seq_individual_weights' if native else 'numpy_task_weights',round=lab.rounds,
            turn=agent.turns,training_updates=int(agent.bridge.arrays['updates'][0]) if native else None,
            affect=agent.unit.affect.values.copy(),layout='fixed sphere; colors from actual sampled weights; no causal thought trace')
        packet=b'NRN6'+struct.pack('<II',sequence,len(values))+values.tobytes()
    return metadata,packet


def serve_neural_websocket(handler,lab):
    import select
    from urllib.parse import urlsplit,parse_qs
    if handler.headers.get('Origin') not in (f'http://127.0.0.1:{handler.server.server_port}',f'http://localhost:{handler.server.server_port}'):
        handler._send(403,dict(error='Origem WebSocket não autorizada'));return
    if handler.headers.get('Upgrade','').lower()!='websocket' or 'upgrade' not in handler.headers.get('Connection','').lower() or handler.headers.get('Sec-WebSocket-Version')!='13':
        handler._send(400,dict(error='Handshake WebSocket versão 13 esperado'));return
    try:
        key=handler.headers['Sec-WebSocket-Key']
        if len(base64.b64decode(key,validate=True))!=16:raise ValueError('Chave inválida')
        identity=parse_qs(urlsplit(handler.path).query).get('agent',['NEURON-1'])[0];lab._agent(identity)
    except (KeyError,ValueError,TypeError):handler._send(400,dict(error='Parâmetros WebSocket inválidos'));return
    if not handler.server.ws_slots.acquire(blocking=False):handler._send(503,dict(error='Limite de quatro fluxos simultâneos'));return
    handler.close_connection=True
    try:
        accept=base64.b64encode(hashlib.sha1((key+'258EAFA5-E914-47DA-95CA-C5AB0DC85B11').encode()).digest()).decode()
        handler.send_response(101);handler.send_header('Upgrade','websocket');handler.send_header('Connection','Upgrade');handler.send_header('Sec-WebSocket-Accept',accept);handler.end_headers()
        handler.connection.settimeout(1.);seq=0
        while not handler.server.ws_stop.is_set() and not lab.closed:
            metadata,packet=neural_stream_packet(lab,identity,seq);seq=(seq+1)&0xffffffff
            handler.wfile.write(_ws_frame(json.dumps(metadata).encode(),1)+_ws_frame(packet));handler.wfile.flush()
            ready,_,_=select.select([handler.connection],[],[],.25)
            if ready:
                # Só controle de conexão; todas as ações usam a fila HTTP auditada.
                header=handler.rfile.read(2)
                if not header:break
                if len(header)!=2:raise ValueError('Frame incompleto')
                a,b=header
                if a&0x70 or not a&0x80 or not b&0x80 or (b&127)>125 or a&15 not in (8,9,10):raise ValueError('Só controle WebSocket mascarado sem fragmentação')
                mask=handler.rfile.read(4);data=handler.rfile.read(b&127)
                if len(mask)!=4 or len(data)!=(b&127):raise ValueError('Frame incompleto')
                payload=bytes(v^mask[i%4] for i,v in enumerate(data))
                if a&15==8:handler.wfile.write(_ws_frame(payload,8));break
                if a&15==9:handler.wfile.write(_ws_frame(payload,10))
    except (OSError,ValueError,RuntimeError):pass
    finally:handler.server.ws_slots.release()


SEED_ACTIONS={'memory_search','memory_add','tools_policy','tool_plan','tool_goal','meta_inspect','meta_stage','sensor_observe','sensor_x11'}


def add_seed_commands(commands):
    train=commands.add_parser('native-train',help='Treina Encoder–Decoder NumPy local com pares JSONL; sem download')
    train.add_argument('corpus',type=Path,nargs='?',help='JSONL {"input":"...","target":"..."}; omitir usa seis exemplos de demonstração')
    train.add_argument('--output',type=Path,default=Path('neuron_data/native/modelo.npz'))
    train.add_argument('--epochs',type=int,default=10);train.add_argument('--steps',type=int,default=4)
    train.add_argument('--resume',action='store_true')
    train.add_argument('--thought-budget',type=int,default=0);train.add_argument('--constitution',action='store_true')
    memory=commands.add_parser('memory',help='Busca HDC local e ingestão de texto, capacidade finita')
    memory.add_argument('query',nargs='?',default='memória');memory.add_argument('--add',type=Path)
    memory.add_argument('--agent',default='NEURON-1');memory.add_argument('--directory',type=Path,default=Path('neuron_data/sessao'))
    tools=commands.add_parser('tools',help='Ferramentas auditadas, restritas à pasta selecionada')
    tools.add_argument('goal',nargs='?',default='/tool {"tool":"files.list","args":{}}')
    tools.add_argument('--directory',type=Path,default=Path('neuron_data/tools'))
    tools.add_argument('--allow-write',action='store_true');tools.add_argument('--http-host',action='append',default=[])
    tools.add_argument('--allow-command',action='append',default=[],help='Uma lista JSON argv completa por ocorrência')
    tools.add_argument('--plan',action='store_true')
    meta=commands.add_parser('meta',help='Inspeção e patches restritos do kernel escalar, com testes/backup')
    meta.add_argument('mode',choices=('inspect','stage','evolve','apply','rollback'),nargs='?',default='inspect')
    meta.add_argument('value',nargs='?',default='(x+1)**2');meta.add_argument('--directory',type=Path,default=Path('neuron_data/sessao/patches'))
    swarm=commands.add_parser('swarm',help='Pares explícitos autenticados; nenhum acesso de rede por padrão')
    swarm.add_argument('mode',choices=('keygen','serve','batch'),nargs='?',default='serve');swarm.add_argument('tasks',nargs='?',type=Path)
    swarm.add_argument('--key-file',type=Path,required=True);swarm.add_argument('--host',default='127.0.0.1');swarm.add_argument('--port',type=int,default=8790)
    swarm.add_argument('--global',dest='federated_global',action='store_true',help='Atalho de federação entre pares explícitos, sem descoberta')
    swarm.add_argument('--base',type=Path);swarm.add_argument('--validation',type=Path)
    swarm.add_argument('--peer',action='append',default=[]);swarm.add_argument('--directory',type=Path,default=Path('neuron_data/swarm'))
    sensor=commands.add_parser('sensors',help='Captura ctypes Linux/X11 ou ingestão WAV PCM; sensores do navegador ficam no painel')
    sensor.add_argument('mode',choices=('screen','wav'));sensor.add_argument('--file',type=Path)
    sensor.add_argument('--directory',type=Path,default=Path('neuron_data/sensores'))
    return {'native-train','memory','tools','meta','swarm','sensors'}


def run_seed_cli(args):
    if args.command=='swarm' and getattr(args,'federated_global',False):
        if args.base is None or args.validation is None:raise ValueError('--global exige --base, --validation e --key-file; somente pares configurados')
        if len(args.peer)>1:raise ValueError('Escolha um coordenador de rodada por sincronização; cada participante pode servir outra rodada')
        command=['federate','pull' if args.peer else 'serve','--base',str(args.base),'--validation',str(args.validation),'--key-file',str(args.key_file),'--directory',str(args.directory),'--host',args.host,'--port',str(args.port)]
        if args.peer:command+=['--peer',args.peer[0]]
        return main(command)
    if args.command=='native-train':
        if not 1<=args.epochs<=200 or not 1<=args.steps<=16:raise ValueError('epochs 1–200; steps 1–16')
        cfg=LabConfig(model='numpy:tiny',input_tokens=128,output_tokens=64,thought_budget=args.thought_budget,constitutional_projection=args.constitution)
        core=NativeSeq2Seq.load(cfg,args.output) if args.resume else NativeSeq2Seq(cfg)
        bridge=core.new_bridge(0);demo=[('olá','Olá!'),('oi','Olá!'),('seu nome','NEURON.'),('quem é você?','Sou o NEURON.'),('obrigado','De nada!'),('tchau','Até logo!')]
        total=0;output=args.output;directory=output.parent/'treino'
        with RunLease(directory/'writer.lock'),EventHistory(directory/'history.sqlite') as history:
            for epoch in range(args.epochs):
                loss=[]
                if args.corpus:
                    if args.corpus.stat().st_size>16*1024*1024:raise ValueError('Corpus excede 16 MiB')
                    def pairs():
                        with args.corpus.open(encoding='utf-8') as file:
                            for line in file:
                                if len(line)>16384:raise ValueError('Linha do corpus muito longa')
                                if line.strip():
                                    row=json.loads(line);yield row['input'],row['target']
                    iterator=pairs()
                else:iterator=iter(demo)
                count=0
                for question,answer in iterator:
                    if not all(isinstance(t,str) and 1<=len(t)<=4000 for t in (question,answer)):raise ValueError('Par de treino inválido')
                    total+=args.steps;count+=1
                    if total>20000 or count>1000:raise ValueError('Orçamento: 1000 pares/época, 20.000 atualizações por execução')
                    result=core.teach(core.encode(question),bridge,np.zeros(48),answer,steps=args.steps,rate=.2);loss.append(result['loss_after'])
                    history.append('native.training.example','native',dict(epoch=epoch+1,input=question,target=answer,report=result))
                if not loss:raise ValueError('Corpus vazio')
                core.save(output,bridge)
                history.append('native.training.epoch','native',dict(epoch=epoch+1,mean_loss=float(np.mean(loss)),updates=total,output=str(output)))
                print(json.dumps(dict(epoch=epoch+1,loss=float(np.mean(loss)),updates=total,output=str(output)),ensure_ascii=False),flush=True)
        return 0
    if args.command=='swarm' and args.mode=='keygen':
        import secrets
        args.key_file.parent.mkdir(parents=True,exist_ok=True)
        fd=os.open(args.key_file,os.O_WRONLY|os.O_CREAT|os.O_EXCL,0o600)
        with os.fdopen(fd,'w') as file:file.write(secrets.token_hex(32)+'\n')
        print('Chave criada em '+str(args.key_file)+'; compartilhe somente com pares confiáveis.');return 0
    if args.command=='meta':
        editor=MetaProgrammer(Path(__file__),args.directory)
        if args.mode=='inspect':result=editor.inspect()
        elif args.mode=='stage':result=editor.stage(args.value)
        elif args.mode=='evolve':result=editor.evolve()
        elif args.mode=='apply':result=editor.apply(args.value)
        else:result=editor.rollback(args.value)
        print(json.dumps(result,ensure_ascii=False,indent=2));return 0
    if args.command=='swarm':
        if args.key_file.stat().st_size>1024:raise ValueError('Arquivo de chave inválido')
        key=args.key_file.read_text().strip()
        with RunLease(args.directory/'writer.lock'),EventHistory(args.directory/'history.sqlite') as history:
            if args.mode=='serve':
                server=make_swarm_server(args.host,args.port,key,history)
                print(f'NEURON swarm explícito em {args.host}:{server.server_address[1]}; HMAC sem cifragem; Ctrl+C encerra.',flush=True)
                try:server.serve_forever(poll_interval=.25)
                except KeyboardInterrupt:pass
                finally:server.shutdown();server.server_close()
            else:
                if args.tasks is None or args.tasks.stat().st_size>1048576:raise ValueError('Informe um arquivo de tarefas JSON até 1 MiB')
                tasks=json.loads(args.tasks.read_text());print(json.dumps(SwarmClient(args.peer,key,history).map(tasks),ensure_ascii=False,indent=2))
        return 0
    if args.command=='memory':
        with NeuronLaboratory(args.directory) as lab:
            if args.add:
                if args.add.stat().st_size>1024*1024:raise ValueError('Texto de ingestão excede 1 MiB')
                with args.add.open(encoding='utf-8') as file:
                    chunk=''
                    for line in file:
                        if len(line)>8000:raise ValueError('Linha de texto excede 8000 caracteres')
                        if len(chunk)+len(line)>7000:
                            lab.semantic_memory.add(args.agent,chunk,kind='user_document');chunk=''
                        chunk+=line
                    if chunk:lab.semantic_memory.add(args.agent,chunk,kind='user_document')
            print(json.dumps(lab.seed_action(dict(action='memory_search',agent=args.agent,query=args.query)),ensure_ascii=False,indent=2))
        return 0
    if args.command=='tools':
        with RunLease(args.directory/'writer.lock'),EventHistory(args.directory/'history.sqlite') as history:
            policy=ToolPolicy(args.directory/'files',args.allow_write,tuple(args.http_host),tuple(tuple(json.loads(c)) for c in args.allow_command))
            harness=ToolHarness(policy,history)
            result=harness.plan(args.goal) if args.plan else harness.execute_goal(args.goal)
            print(json.dumps(jsonable(result),ensure_ascii=False,indent=2))
        return 0
    if args.command=='sensors':
        if args.mode=='screen':sample=NativeSensors.screen_x11()
        else:
            import wave
            if args.file is None:raise ValueError('Informe --file áudio.wav')
            with wave.open(str(args.file),'rb') as audio:
                if audio.getsampwidth()!=2 or audio.getnchannels() not in (1,2):raise ValueError('WAV deve ser PCM16 mono/estéreo')
                raw=audio.readframes(4096);channels=audio.getnchannels();rate=audio.getframerate()
            a=np.frombuffer(raw,dtype='<i2').astype(float).reshape(-1,channels).mean(1)/32768.
            sample=dict(kind='microphone',values=a.tolist(),sample_rate=rate,source='user_wav_file')
        with NeuronLaboratory(args.directory,LabConfig(agents=1)) as lab:
            result=lab.seed_action(dict(action='sensor_observe',agent='NEURON-1',kind=sample['kind'],values=sample['values']))
            print(json.dumps(result,ensure_ascii=False,indent=2))
        return 0
    raise ValueError('Comando seed desconhecido')


@dataclass(frozen=True)
class LabConfig:
    agents: int = 3
    seed: int = 42
    model: str = "google/flan-t5-small"
    revision: str = "main"
    input_tokens: int = 128
    output_tokens: int = 48
    memory_capacity: int = 64
    context_turns: int = 4
    inspection_tokens: int = 32
    bridge_rank: int = 8
    device: str = "cpu"
    cache_dir: str = "neuron_data/model-cache"
    thought_budget: int = 0
    reasoning_effort: str = "medio"
    reasoning_visible: bool = True
    reasoning_custom_budget: int = 32
    reasoning_custom_seconds: float = 20.
    inference_seconds: float = 5.
    constitutional_projection: bool = False

    def __post_init__(self):
        if self.reasoning_effort not in ("baixo","medio","alto","muito_alto","maximo","personalizado") or type(self.reasoning_visible) is not bool:raise ValueError("Preferências de raciocínio inválidas")
        if type(self.reasoning_custom_budget) is not int or not 0<=self.reasoning_custom_budget<=256 or type(self.reasoning_custom_seconds) not in (int,float) or not math.isfinite(self.reasoning_custom_seconds) or not .1<=self.reasoning_custom_seconds<=30:raise ValueError("Orçamento personalizado: 0–256 passos, .1–30 s")
        if type(self.thought_budget) is not int or not 0<=self.thought_budget<=256 or type(self.constitutional_projection) is not bool:raise ValueError("Orçamento/constituição inválidos")
        if type(self.inference_seconds) not in (int,float) or not math.isfinite(self.inference_seconds) or not .1<=self.inference_seconds<=30:raise ValueError("Prazo de inferência .1–30 s")
        for name, lower, upper in (("agents", 1, 8), ("input_tokens", 16, 256),
                ("output_tokens", 1, 128), ("memory_capacity", 1, 256),
                ("context_turns", 0, 8), ("inspection_tokens", 4, 64), ("bridge_rank", 2, 64)):
            value = getattr(self, name)
            if type(value) is not int or not lower <= value <= upper:
                raise ValueError(f"{name}: esperado inteiro entre {lower} e {upper}")
        _count(self.seed, "seed")
        if not isinstance(self.model, str) or not self.model.strip() or len(self.model) > 512:
            raise ValueError("Identificador/caminho de modelo inválido")
        if self.device not in ("cpu", "cuda", "mps"):
            raise ValueError("device deve ser cpu, cuda ou mps")
        if not isinstance(self.revision, str) or not self.revision or len(self.revision) > 128:
            raise ValueError("Revisão de modelo inválida")


def numpy_inspection(model: Neuron, x: Any, previous: Params | None = None) -> dict[str, Any]:
    """Ativações reais e deltas de pesos; inspeção não atualiza o modelo."""
    with model._lock:
        a = model.features.validate(x)
        output, cache = model.core.forward(model.features(a))
        groups = {}
        for key, value in model.core.p.items():
            change = None if previous is None else value - previous[key]
            groups[key] = dict(norm=float(np.linalg.norm(value)),
                delta_l2=0.0 if change is None else float(np.linalg.norm(change)),
                max_delta=0.0 if change is None else float(np.max(np.abs(change))))
        return jsonable(dict(steps=model.steps, experts=model.core.active,
            routing=cache["pi"], dendrites=cache["h"], gates=cache["gate"],
            expert_outputs=cache["outputs"], output=output, weights=groups,
            weight_delta_l2=math.sqrt(sum(g["delta_l2"] ** 2 for g in groups.values())),
            memory=model.memory.size, loss=model.loss_ema))


def _bridge_factory(torch, dimension: int, rank: int, seed: int):
    """Cada instância recebe pesos próprios; backbone congelado é compartilhável."""
    class NeuralBridge(torch.nn.Module):
        def __init__(self):
            super().__init__()
            self.down = torch.nn.Linear(dimension, rank, bias=False)
            self.up = torch.nn.Linear(rank, dimension, bias=False)
            self.state = torch.nn.Linear(48, 2 * dimension)
            torch.nn.init.normal_(self.down.weight, std=0.02)
            torch.nn.init.normal_(self.up.weight, std=0.02)
            torch.nn.init.normal_(self.state.weight, std=0.02)
            torch.nn.init.zeros_(self.state.bias)

        def forward(self, hidden, context):
            residual = hidden + 0.1 * self.up(torch.tanh(self.down(hidden)))
            prefix = 0.1 * torch.tanh(self.state(context)).reshape(1, 2, dimension)
            return torch.cat((prefix, residual), dim=1)
    # Não altera o RNG global usado por outros aplicativos.
    with torch.random.fork_rng(devices=[]):
        torch.random.default_generator.manual_seed(seed)
        return NeuralBridge()


class EncoderDecoderCore:
    """Somente Seq2Seq: encoder -> NEURON -> ponte neural -> decoder.

    O backbone não é treinado implicitamente. Ensino atualiza a ponte própria
    de cada agente por gradiente real; transições e feedback treinam os Neurons
    NumPy. Não há outro chatbot nem backend causal nesta implementação.
    """
    def __init__(self, config: LabConfig, *, offline: bool = False):
        try:
            import torch
            from transformers import AutoConfig, AutoTokenizer, AutoModelForSeq2SeqLM
        except ImportError as error:
            raise RuntimeError("Instale o modo Encoder–Decoder no menu de dependências, ou use: "
                "python -m pip install 'torch>=2.6' 'transformers>=4.46,<5' sentencepiece") from error
        location = config.model
        options = dict(revision=config.revision, local_files_only=offline, trust_remote_code=False, cache_dir=config.cache_dir)
        description = AutoConfig.from_pretrained(location, **options)
        if not description.is_encoder_decoder:
            raise ValueError("Este NEURON requer um Encoder–Decoder (T5, FLAN-T5, BART, mBART, mT5). "
                             "Modelos somente decoder não são aceitos.")
        tokenizer = AutoTokenizer.from_pretrained(location, **options)
        model = AutoModelForSeq2SeqLM.from_pretrained(location, **options,
            attn_implementation="eager", use_safetensors=True, torch_dtype=torch.float32)
        self._initialize(config, tokenizer, model, config.model, "pretrained")

    def _initialize(self, config, tokenizer, model, identity, origin):
        import torch
        if not model.config.is_encoder_decoder:
            raise ValueError("Modelo não é Encoder–Decoder")
        self.config, self.torch, self.tokenizer = config, torch, tokenizer
        self.model = model.to(config.device).eval()
        self.model.requires_grad_(False)
        self.identity, self.origin = identity, origin
        self.dimension = int(model.config.d_model)
        if self.dimension > 4096:
            raise ValueError("d_model excede o orçamento de inspeção (4096)")
        self.tokenizer.truncation_side = "left"
        self.generation_options = {}
        languages = getattr(self.tokenizer, "lang_code_to_id", {})
        if "pt_XX" in languages:
            self.tokenizer.src_lang = "pt_XX"
            self.generation_options["forced_bos_token_id"] = languages["pt_XX"]
        if self.tokenizer.pad_token_id is None:
            raise ValueError("Tokenizer precisa definir pad_token")
        torch.set_num_threads(max(1, min(4, os.cpu_count() or 1)))
        seed = int.from_bytes(hashlib.sha256((identity + str(self.dimension)).encode()).digest()[:4], "little")
        self.projection = np.random.default_rng(seed).normal(0, 1, (self.dimension, 32))
        self._lock = threading.RLock()
        self.last_tensors = None
        digest = hashlib.sha256()
        for name, parameter in self.model.named_parameters():
            digest.update((name + str(tuple(parameter.shape))).encode())
            raw = parameter.detach().cpu().contiguous().view(torch.uint8).numpy()
            digest.update(memoryview(raw).cast("B"))
        self.signature = digest.hexdigest()

    @classmethod
    def from_components(cls, config, tokenizer, model, *, identity="local-random-test"):
        obj = cls.__new__(cls)
        obj._initialize(config, tokenizer, model, identity, "random-test")
        return obj

    def new_bridge(self, seed: int):
        return _bridge_factory(self.torch, self.dimension, self.config.bridge_rank, seed).to(self.config.device)

    def encode(self, text: str):
        with self._lock:
            encoded = self.tokenizer(text, return_tensors="pt", truncation=True,
                                    max_length=self.config.input_tokens)
            encoded = {k: v.to(self.config.device) for k, v in encoded.items() if k in ("input_ids", "attention_mask")}
            with self.torch.no_grad():
                result = self.model.get_encoder()(**encoded, output_attentions=True,
                    output_hidden_states=True, return_dict=True)
            mask = encoded["attention_mask"].unsqueeze(-1)
            pooled = ((result.last_hidden_state * mask).sum(1) / mask.sum(1).clamp(min=1))[0]
            vector = pooled.float().cpu().numpy()
            features = np.tanh(vector @ self.projection / math.sqrt(self.dimension))
            return dict(inputs=encoded, result=result, features=features)

    def _condition(self, encoded, bridge, context):
        from transformers.modeling_outputs import BaseModelOutput
        context = self.torch.tensor(context, dtype=self.torch.float32, device=self.config.device).reshape(1, 48)
        hidden = bridge(encoded["result"].last_hidden_state.detach(), context)
        mask = encoded["inputs"]["attention_mask"]
        prefix_mask = self.torch.ones((1, 2), dtype=mask.dtype, device=mask.device)
        return BaseModelOutput(last_hidden_state=hidden), self.torch.cat((prefix_mask, mask), dim=1)

    def _hidden_summary(self, states):
        if states is None:
            return []
        return [dict(layer=index, mean_token_norm=float(s.float().norm(dim=-1).mean()),
                     max_abs=float(s.float().abs().max()), shape=list(s.shape))
                for index, s in enumerate(states)]

    def _attention(self, matrices, queries, keys):
        if matrices is None or not len(matrices) or matrices[-1] is None:
            return dict(available=False, reason="Backend não retornou atenções")
        array = matrices[-1][0].detach().float().cpu().numpy()
        q_indices = np.linspace(0, array.shape[-2] - 1,
            min(self.config.inspection_tokens, array.shape[-2]), dtype=int)
        k_indices = np.linspace(0, array.shape[-1] - 1,
            min(self.config.inspection_tokens, array.shape[-1]), dtype=int)
        if len(keys) >= 2 and keys[0] == "[NEURON:0]" and keys[1] == "[NEURON:1]" and array.shape[-1] > len(k_indices):
            rest = np.linspace(2, array.shape[-1]-1, max(0, len(k_indices)-2), dtype=int)
            k_indices = np.concatenate((np.array([0,1]), rest))
        visible = array[:16][:, q_indices][:, :, k_indices]
        return dict(available=True, layer=len(matrices)-1, layers=len(matrices),
            total_heads=array.shape[0], shown_heads=min(16, array.shape[0]),
            query_tokens=[queries[i] for i in q_indices], key_tokens=[keys[i] for i in k_indices],
            matrix=visible.tolist(), sampled=array.shape[-2] > len(q_indices) or array.shape[-1] > len(k_indices))

    def generate(self, encoded, bridge, context):
        with self._lock, self.torch.no_grad():
            conditioned, mask = self._condition(encoded, bridge, context)
            sequences = self.model.generate(encoder_outputs=conditioned, attention_mask=mask,
                max_new_tokens=self.config.output_tokens, num_beams=1, do_sample=False,
                use_cache=True, pad_token_id=self.tokenizer.pad_token_id, **self.generation_options)
            decoder_ids = sequences[:, :-1]
            if decoder_ids.shape[1] == 0:
                raise RuntimeError("Decoder não produziu uma sequência inspecionável")
            replay = self.model(encoder_outputs=conditioned, attention_mask=mask,
                decoder_input_ids=decoder_ids, output_attentions=True,
                output_hidden_states=True, use_cache=False, return_dict=True)
            input_tokens = self.tokenizer.convert_ids_to_tokens(encoded["inputs"]["input_ids"][0].tolist())
            decoder_tokens = self.tokenizer.convert_ids_to_tokens(decoder_ids[0].tolist())
            prefix_tokens = ["[NEURON:0]", "[NEURON:1]"] + input_tokens
            raw = encoded["result"]
            inspection = dict(model=self.identity, origin=self.origin, architecture=self.model.config.model_type,
                input_tokens=input_tokens, decoder_input_tokens=decoder_tokens,
                predicted_token_ids=sequences[0, 1:].tolist(),
                encoder_states=self._hidden_summary(raw.hidden_states),
                decoder_states=self._hidden_summary(replay.decoder_hidden_states),
                encoder_attention=self._attention(raw.attentions, input_tokens, input_tokens),
                decoder_attention=self._attention(replay.decoder_attentions, decoder_tokens, decoder_tokens),
                cross_attention=self._attention(replay.cross_attentions, decoder_tokens, prefix_tokens),
                bridge_context=list(map(float, context)), bridge_prefix_tokens=2,
                frozen_backbone=True, adapter_parameters=sum(p.numel() for p in bridge.parameters()),
                alignment="Cada entrada do decoder prevê o token seguinte; cross-attention inclui dois tokens neurais.")
            self.last_tensors = (raw, replay, conditioned.last_hidden_state)
            return self.tokenizer.decode(sequences[0], skip_special_tokens=True).strip(), inspection

    def teach(self, encoded, bridge, context, answer: str, *, steps: int = 4, rate: float = 0.1):
        if type(steps) is not int or not 1 <= steps <= 16:
            raise ValueError("Ensino deve ter entre 1 e 16 passos")
        if not math.isfinite(rate) or not 0 < rate <= 0.5:
            raise ValueError("Taxa do ensino deve estar em (0,0.5]")
        with self._lock:
            labels = self.tokenizer(answer, return_tensors="pt", truncation=True,
                max_length=self.config.output_tokens)["input_ids"].to(self.config.device)
            if labels.shape[1] == 0:
                raise ValueError("Resposta alvo vazia após tokenização")
            before = {k: v.detach().clone() for k, v in bridge.named_parameters()}
            losses = []
            try:
                for _ in range(steps):
                    bridge.zero_grad(set_to_none=True)
                    conditioned, mask = self._condition(encoded, bridge, context)
                    loss = self.model(encoder_outputs=conditioned, attention_mask=mask,
                        labels=labels, use_cache=False, return_dict=True).loss
                    if not self.torch.isfinite(loss):
                        raise FloatingPointError("Perda de ensino não finita")
                    loss.backward()
                    norm = self.torch.nn.utils.clip_grad_norm_(bridge.parameters(), 1.0, error_if_nonfinite=True)
                    with self.torch.no_grad():
                        proposed = [(p, p - rate * p.grad) for p in bridge.parameters() if p.grad is not None]
                        if self.config.constitutional_projection:
                            named=list(bridge.named_parameters());base={k:v.detach().cpu().numpy().copy() for k,v in named};steps_np={k:(-rate*v.grad).detach().cpu().numpy() if v.grad is not None else np.zeros_like(base[k]) for k,v in named}
                            candidates,_=constitutional_candidate(base,steps_np);proposed=[(v,self.torch.as_tensor(candidates[k],device=v.device,dtype=v.dtype)) for k,v in named]
                        if not all(bool(self.torch.isfinite(value).all()) for _, value in proposed):
                            raise FloatingPointError("Pesos não finitos no ensino")
                        for parameter, value in proposed:
                            parameter.copy_(value)
                    losses.append(float(loss.detach()))
                with self.torch.no_grad():
                    conditioned, mask = self._condition(encoded, bridge, context)
                    after_loss = float(self.model(encoder_outputs=conditioned, attention_mask=mask,
                        labels=labels, use_cache=False, return_dict=True).loss)
                delta = math.sqrt(sum(float((v.detach()-before[k]).float().square().sum()) for k,v in bridge.named_parameters()))
                return dict(loss_before=losses[0], loss_after=after_loss, losses=losses,
                    steps=steps, delta_l2=delta, trainable="ponte_encoder_decoder_individual",
                    backbone_updated=False, gradient_norm=float(norm))
            except BaseException:
                with self.torch.no_grad():
                    for k,p in bridge.named_parameters():
                        p.copy_(before[k])
                raise
            finally:
                bridge.zero_grad(set_to_none=True)

    def export_tensors(self, filename: Path):
        if self.last_tensors is None:
            raise ValueError("Execute uma resposta antes de exportar tensores")
        raw, replay, bridge_hidden = self.last_tensors
        filename = Path(filename)
        filename.parent.mkdir(parents=True, exist_ok=True)
        handle, temporary = tempfile.mkstemp(dir=filename.parent, prefix=filename.name, suffix=".tmp")
        os.close(handle)
        try:
            with zipfile.ZipFile(temporary, "w", zipfile.ZIP_DEFLATED) as archive:
                groups = dict(encoder_attention=raw.attentions, encoder_hidden=raw.hidden_states,
                    decoder_attention=replay.decoder_attentions, decoder_hidden=replay.decoder_hidden_states,
                    cross_attention=replay.cross_attentions, bridge_hidden=(bridge_hidden,))
                for group, tensors in groups.items():
                    for i, tensor in enumerate(tensors or ()):
                        if tensor is not None:
                            with archive.open(f"{group}.{i}.npy", "w") as output:
                                np.lib.format.write_array(output, tensor.detach().float().cpu().numpy(), allow_pickle=False)
            os.replace(temporary, filename)
        finally:
            if os.path.exists(temporary):
                os.unlink(temporary)


def _bridge_arrays(bridge):
    if isinstance(bridge,NativeBridge):return {k:v.copy() for k,v in bridge.arrays.items()}
    return {key: value.detach().float().cpu().numpy().copy() for key, value in bridge.state_dict().items()}


def _restore_bridge(core, bridge, arrays):
    if isinstance(bridge,NativeBridge):
        if set(arrays)!=set(bridge.arrays):raise ValueError('Pesos nativos incompatíveis')
        for k,v in arrays.items():
            if v.shape!=bridge.arrays[k].shape or not np.isfinite(v).all():raise ValueError('Peso nativo inválido: '+k)
        bridge.arrays={k:v.copy() for k,v in arrays.items()};return
    expected = bridge.state_dict()
    if set(expected) != set(arrays):
        raise ValueError("Pesos de ponte incompatíveis com este Encoder–Decoder")
    values = {}
    for key, tensor in expected.items():
        array = np.asarray(arrays[key], dtype=np.float32)
        if tuple(array.shape) != tuple(tensor.shape) or not np.isfinite(array).all():
            raise ValueError("Forma/valores inválidos nos pesos da ponte")
        values[key] = core.torch.as_tensor(array.copy(), device=core.config.device)
    bridge.load_state_dict(values, strict=True)


class DialogueNeuron:
    """Uma instância possui três núcleos NumPy, memória e ponte Seq2Seq próprios."""
    def __init__(self, identity: str, index: int, cfg: LabConfig):
        self.identity, self.index, self.config = identity, index, cfg
        base = dict(branches=6, fourier_features=4, initial_experts=1, max_experts=3,
            replay_capacity=64, replay_batch=2, calibration_window=64, growth_cooldown=32,
            constitutional_projection=cfg.constitutional_projection,seed=cfg.seed + index * 101, learning_rate=(0.004,0.006,0.009)[index % 3])
        self.task = Neuron(Config(input_dim=8, output_dim=2, **base))
        self.formal_router=Neuron(dataclasses.replace(self.task.config,seed=base['seed']+777))
        self.last_formal=None;self.sensor_source=None;self.hypotheses=deque(maxlen=32)
        self.last_formal_numpy=numpy_inspection(self.formal_router,np.zeros(8))
        self.quality = Neuron(Config(input_dim=32, output_dim=2, **base))
        self.unit = CognitiveUnit(Config(sensory_dim=32, motor_dim=4, ensemble_size=2,
            episodic_capacity=64, planning_horizon=1, planning_candidates=4, planning_iterations=1,
            vsa_dim=64, symbolic_capacity=32, meta_every=16, meta_window=8, **base))
        self.bridge = None
        self.saved_bridge = None
        self.motor_policy=DesktopMotorPolicy();self.sensor_features=None
        self.turns = 0
        self.last_features = np.zeros(32)
        self.last_context = np.zeros(48)
        self.last_numpy = numpy_inspection(self.task, np.zeros(8))
        self.last_transformer = None
        self.last_action = np.zeros(4)
        self.messages = deque(maxlen=max(2, cfg.context_turns * 2))
        self.memories = deque(maxlen=cfg.memory_capacity)
        self.last_text = ""
        self.last_prompt = ""
        self.teachings = 0

    def attach(self, history: EventHistory):
        history.attach(self.task, self.identity + "/task")
        history.attach(self.formal_router,self.identity+'/formal-router')
        history.attach(self.quality, self.identity + "/feedback")
        history.attach(self.unit, self.identity + "/cognition")

    def ensure_bridge(self, core):
        if self.bridge is None:
            self.bridge = core.new_bridge(self.config.seed + 5000 + self.index)
            if self.saved_bridge is not None:
                _restore_bridge(core, self.bridge, self.saved_bridge)
                self.saved_bridge = None

    def context(self, features, action):
        _, cache = self.task.core.forward(self.task.features(np.zeros(8)))
        routing = np.zeros(4)
        routing[:len(cache["pi"])] = cache["pi"]
        affect = [self.unit.affect.values[k] for k in ("fear", "curiosity", "frustration", "satisfaction")]
        quality = float(self.quality.predict_one(features).probabilities[1])
        vector = np.concatenate((features, action, affect, routing,
            [min(10, self.task.loss_ema), quality, min(1, self.turns/1000), 1.0]))
        if vector.shape != (48,):
            raise RuntimeError("Contexto neural interno com dimensão incorreta")
        if self.last_formal is not None:
            vector = vector + .15*math_bridge_signal(self.last_formal)
        return vector

    def retrieve(self, features, exclude: str = "", query: str = ""):
        candidates = []
        for memory in self.memories:
            a = np.asarray(memory["features"])
            score = float(np.dot(a, features) / max(EPS, np.linalg.norm(a) * np.linalg.norm(features)))
            if memory["question"] != exclude:
                candidates.append((score + (0.1 if memory.get("kind")=="teaching" else 0), memory))
        candidates.sort(key=lambda row: row[0], reverse=True)
        result=[m for score,m in candidates[:2] if score > 0.25]
        memory=getattr(self,'semantic_memory',None)
        if memory is not None and query:
            known={m['question'] for m in result}
            for item in memory.search(self.identity,query,3):
                if item['score']>.25 and item['question']!=exclude and item['question'] not in known:
                    result.append(item);known.add(item['question'])
        return result[:4]

    def prompt(self, message, retrieved):
        pieces = ["Responda em português à última mensagem. Use os exemplos lembrados quando pertinentes."]
        for memory in retrieved:
            label = "Exemplo ensinado" if memory.get("kind")=="teaching" else "Resultado calculado preservado no histórico" if memory.get('kind')=='formal_result' else "Registro observado, não verificado"
            pieces.append(label + " — entrada: " + memory["question"][:300] + "\nResposta: " + memory["answer"][:300])
        for item in list(self.messages)[-self.config.context_turns*2:] if self.config.context_turns else []:
            pieces.append(item["speaker"] + ": " + item["text"][:400])
        pieces.append("Usuário: " + message + "\nNEURON:")
        return "\n".join(pieces)

    def view(self):
        return dict(id=self.identity, turns=self.turns, teachings=self.teachings,
            memory=len(self.memories), task_steps=self.task.steps,
            cognitive_transitions=self.unit.transitions, feedback_steps=self.quality.steps,
            affect=self.unit.affect.values.copy(), action=self.last_action.tolist(),
            numpy=self.last_numpy, transformer=self.last_transformer,
            messages=list(self.messages), last_text=self.last_text,
            formal_steps=self.formal_router.steps,formal_numpy=self.last_formal_numpy,
            formal_result=self.last_formal,hypotheses=list(self.hypotheses),sensor_source=self.sensor_source,
            bridge_ready=self.bridge is not None, transformer_stamp=None if self.last_transformer is None else self.last_transformer.get("stamp"))


def lab_operation(method):
    @wraps(method)
    def wrapped(self, *args, **kwargs):
        with self._lock:
            depth = self._operation_depth
            self._operation_depth += 1
            try:
                self.history.append("lab.operation.started", "lab", dict(method=method.__name__, args=args, kwargs=kwargs))
                result = method(self, *args, **kwargs)
                if depth == 0:
                    self.checkpoint()
                self._refresh()
                return result
            except Exception as error:
                self.history.append("lab.error", "lab", dict(operation=method.__name__,
                    error=type(error).__name__, message=str(error)))
                if depth == 0:
                    saved = self.history.restore("lab")
                    if saved is not None:
                        self._load_bytes(saved[0])
                self._refresh(error=str(error))
                raise
            finally:
                self._operation_depth -= 1
                if method.__name__ not in ("curriculum_step",):self.last_activity=time.monotonic()
    return wrapped


class NeuronLaboratory:
    """Sessão recuperável com instâncias independentes e backbone Seq2Seq comum."""
    def __init__(self, directory: Path, config: LabConfig | None = None, *, backend=None, min_free_mb=64):
        self.directory = Path(directory)
        self.directory.mkdir(parents=True, exist_ok=True)
        self._lease = RunLease(self.directory / "writer.lock")
        self._lease.__enter__()
        self._lock, self._view_lock = threading.RLock(), threading.RLock()
        self._operation_depth = 0
        self.backend = backend
        self.last_error = ""
        self._view = {}
        self.closed = False
        self.last_activity=time.monotonic();self.synthetic_state=synthetic_state();self.curriculum=SyntheticCurriculum(self);self.auto_improvement_state=dict(rounds=0,recent=[])
        try:
            self.history = EventHistory(self.directory / "history.sqlite", min_free_mb=min_free_mb)
            self.semantic_memory=HDCSemanticMemory(self.history)
            self.tool_policy=ToolPolicy(self.directory/'tools')
            saved = self.history.restore("lab")
            if saved:
                self._load_bytes(saved[0])
            else:
                if self.history.connection.execute("SELECT count(*) FROM snapshots").fetchone()[0]:
                    raise ValueError("Diretório pertence a outro modo; escolha outro diretório")
                self.config = config or LabConfig()
                self.expected_signature = None
                self.rng = np.random.default_rng(self.config.seed + 991)
                self.agents = [DialogueNeuron(f"NEURON-{i+1}", i, self.config) for i in range(self.config.agents)]
                self.population = self.rng.uniform(-1, 1, (8, 6))
                self.archive = deque(maxlen=16)
                self.rounds = 0
                self.metrics = deque(maxlen=96)
                self.formal_race = None
            if config is not None and config.agents > len(self.agents):
                old_count = len(self.agents)
                self.config = dataclasses.replace(self.config, agents=config.agents)
                for agent in self.agents:
                    agent.config = self.config
                for index in range(old_count, self.config.agents):
                    self.agents.append(DialogueNeuron(f"NEURON-{index+1}", index, self.config))
                self.history.append("lab.instances.added", "lab", dict(previous=old_count, current=len(self.agents)))
            if self.backend is not None:
                if self.expected_signature is not None and self.expected_signature != self.backend.signature:
                    raise ValueError("Backbone diferente do checkpoint; use os mesmos pesos ou uma nova sessão")
                self.expected_signature = self.backend.signature
            for agent in self.agents:
                agent.attach(self.history)
                agent.semantic_memory=self.semantic_memory
                if self.backend is not None:
                    agent.ensure_bridge(self.backend)
            self.history.append("lab.opened", "lab", dict(config=self.config, resumed=bool(saved)))
            self.checkpoint()
            self._refresh()
        except BaseException:
            if hasattr(self, "history"):
                self.history.close()
            self._lease.__exit__()
            raise

    def _refresh(self, error=None):
        if error is not None:
            self.last_error = error
        with self._view_lock:
            self._view = jsonable(dict(version=__version__, config=self.config,
                rounds=self.rounds, model_ready=self.backend is not None,
                model_origin=None if self.backend is None else self.backend.origin,
                model=self.config.model, agents=[a.view() for a in self.agents],
                metrics=list(self.metrics), error=self.last_error,
                formal_race=None if self.formal_race is None else list(self.formal_race.recent),
                auto_improvement_state=self.auto_improvement_state,semantic_memory=self.semantic_memory.stats(),runtime_kernels=RUNTIME_KERNELS.status(),synthetic_state=self.synthetic_state,curriculum=self.curriculum.status(),
                storage=str(self.history.path), legend="Ativações e planos numéricos são observações; mensagens são saídas do decoder."))

    def view(self, *, include_transformers=False):
        with self._view_lock:
            result = copy.deepcopy(self._view)
        if not include_transformers:
            for agent in result.get("agents", []):
                agent.pop("transformer", None)
        return result

    def inspection(self, identity):
        with self._view_lock:
            for agent in self._view.get("agents", []):
                if agent["id"] == identity:
                    if agent["transformer"] is None:
                        raise ValueError("Instância ainda não tem uma inspeção Encoder–Decoder")
                    return copy.deepcopy(agent["transformer"])
        raise ValueError("Instância inexistente")

    def _agent(self, identity):
        for agent in self.agents:
            if agent.identity == identity:
                return agent
        raise ValueError("Instância inexistente")

    def _require_model(self):
        if self.backend is None:
            raise RuntimeError("Encoder–Decoder ainda não carregado. Carregue um modelo no menu; "
                "a arena numérica funciona sem ele. Nenhuma conversa será simulada por frases prontas.")

    @lab_operation
    def load_model(self, *, offline=False):
        if self.backend is not None:
            return dict(model=self.backend.identity, ready=True)
        self.history.append("lab.model.loading", "lab", dict(model=self.config.model, offline=offline))
        if self.config.model.startswith('compact:'):
            core=CompactEncoderDecoder(self.config)
        elif self.config.model.startswith('numpy:'):
            name=self.config.model[6:]
            core=NativeSeq2Seq(self.config) if name=='tiny' else NativeSeq2Seq.load(self.config,name)
        else:
            core = EncoderDecoderCore(self.config, offline=offline)
        if self.expected_signature is not None and core.signature != self.expected_signature:
            raise ValueError("Pesos do backbone diferem do checkpoint; abra uma sessão nova")
        for agent in self.agents:
            if agent.bridge is not None:
                agent.saved_bridge = _bridge_arrays(agent.bridge)
            agent.bridge = None
            agent.ensure_bridge(core)
        self.expected_signature = core.signature
        self.backend = core
        self.last_error = ""
        self.history.append("lab.model.ready", "lab", dict(model=core.identity,
            architecture=core.model.config.model_type, dimension=core.dimension, origin=core.origin))
        return dict(model=core.identity, ready=True)

    @lab_operation
    def numeric_step(self, batch=8):
        if type(batch) is not int or not 1 <= batch <= 128:
            raise ValueError("batch deve estar entre 1 e 128")
        successes = []
        for genome in self.population:
            X,y = ArmsRace._sample(genome[None,:], 8, self.rng)
            accuracy = float(np.mean([np.mean(np.argmax(a.task.predict_proba(X), axis=1)==y) for a in self.agents]))
            successes.append(accuracy)
        fitness = -np.abs(np.asarray(successes)-0.65) - 0.01*np.mean(self.population**2,axis=1)
        elites = self.population[np.argsort(-fitness, kind="stable")[:2]].copy()
        for genome in elites:
            if not any(np.linalg.norm(genome-old)<0.1 for old in self.archive):
                self.archive.append(genome.copy())
        tasks = np.vstack((elites, np.asarray(self.archive)[-4:]))
        X,y = ArmsRace._sample(tasks, batch, self.rng)
        losses = {}
        for agent in self.agents:
            before = {k:v.copy() for k,v in agent.task.core.p.items()}
            reports = [agent.task.learn_one(x,int(target)) for x,target in zip(X,y)]
            agent.last_numpy = numpy_inspection(agent.task, X[-1], before)
            losses[agent.identity] = float(np.mean([r.loss for r in reports]))
            self.history.append("lab.weights", agent.identity, agent.last_numpy)
        children = [g.copy() for g in elites]
        while len(children)<8:
            mother,father=elites[self.rng.integers(0,2,size=2)]
            child=np.where(self.rng.random(6)<0.5,mother,father)
            children.append(np.clip(child+self.rng.normal(0,0.15,6),-1,1))
        self.population=np.asarray(children)
        self.rounds+=1
        report=dict(round=self.rounds, losses=losses, challenge_success=float(np.mean(successes)),
            archive=len(self.archive), population=self.population)
        self.metrics.append(dict(round=self.rounds, losses=losses))
        self.history.append("lab.challenge", "society", dict(report=report,X=X,y=y))
        return jsonable(report)

    @lab_operation
    def calculate(self,identity,request):
        agent=self._agent(identity)
        request=_bounded_math_request(copy.deepcopy(request))
        if request['op']=='system.solve':
            spec=request.get('args',[{}])[0];family=spec.get('family');data=spec.get('data')
            arguments=[data] if family=='sat' else [data,spec.get('source',0)]
            features=_formal_features(family,arguments)
            recommendation=int(agent.formal_router.predict_one(features).value)
            request.setdefault('kwargs',{}).setdefault('strategy',recommendation)
            self.history.append('math.policy',identity,dict(features=features,recommendation=recommendation))
        receipt=FormalCortex(self.history,identity).run(request)
        agent.last_formal=receipt
        symbolic=agent.unit.symbols.encode(dict(tool=receipt['operation'],
            epistemic='verified' if receipt['verification']['verified'] else receipt['verification']['kind']))
        agent.unit.workspace.offer('formal_math',dict(operation=receipt['operation'],receipt=receipt['id'],
            verified=receipt['verification']['verified']),.95)
        self.history.append('math.vsa',identity,dict(symbolic=symbolic,receipt=receipt['id']))
        return receipt

    @lab_operation
    def simulate(self,identity,kind='heat',parameters=None):
        agent=self._agent(identity);before=agent.unit.steps
        receipt=self.calculate(identity,dict(op='system.simulate',args=[kind,parameters or {}]))
        hypothesis=dict(receipt=receipt['id'],scenario=kind,parameters=parameters or {},
            source='simulation_not_real_observation',kind='numerical',result=receipt['result'])
        agent.hypotheses.append(hypothesis)
        if agent.unit.steps!=before: raise RuntimeError('Simulação alterou relógio de observações')
        self.history.append('math.simulation',identity,hypothesis)
        return receipt

    @lab_operation
    def curriculum_step(self,identity='NEURON-1',*,teacher=False,steps=1,family=None):
        return curriculum_step_impl(self,identity,teacher,steps,family)

    @lab_operation
    def eight_action(self,item):
        action=item['action'];identity=item.get('agent','NEURON-1');agent=self._agent(identity)
        if action=='curriculum_step':return self.curriculum_step(identity,teacher=item.get('teacher',False),steps=item.get('steps',1))
        if action=='curriculum_start':result=self.curriculum.start(identity,teacher=item.get('teacher',False),interval=item.get('interval',2.),steps=item.get('steps',1))
        elif action=='curriculum_stop':
            # Não espera thread segurando o lock de operações; o loop observa o sinal.
            self.curriculum.stop_event.set();result=self.curriculum.status()
        elif action=='thought_config':
            budget=item.get('budget',0)
            if not isinstance(self.backend,NativeSeq2Seq):raise ValueError('Carregue um modelo NumPy nativo')
            updated=dataclasses.replace(self.config,thought_budget=budget)
            # Alterar orçamento muda a dinâmica; é explícito, não altera os pesos.
            self.config=updated;self.backend.config=updated
            for peer in self.agents:peer.config=updated
            self.backend.signature=self.backend.compatibility_signature();self.expected_signature=self.backend.signature;result=dict(budget=budget,weights_changed=False,warning='O treino deve usar dinâmica compatível; mais ciclos não garantem respostas melhores')
        elif action in ('bpe_status','bpe_enable'):
            if not isinstance(self.backend,CompactEncoderDecoder):raise ValueError('Use --model compact:pt')
            agent.ensure_bridge(self.backend)
            if action=='bpe_enable':
                language=CompressedLanguageModel.load(agent.bridge.language().dump());language.enable_bpe();agent.bridge.store(language)
            language=agent.bridge.language();result=language.stats()
            if language.tokenizer is not None:language.tokenizer.persist(self.history,identity)
        elif action=='symbolic_prove':
            operation='system.boolean_equivalence' if item.get('boolean') else 'system.symbolic_equivalence'
            result=FormalCortex(self.history,identity,timeout=10).run(dict(op=operation,args=[item['old'],item['new']],kwargs={} if item.get('boolean') else dict(variables=item.get('variables'),assumptions=item.get('assumptions',[]))))
        else:raise ValueError('Ação NEURON 8 desconhecida')
        self.history.append('lab.eight.result',identity,dict(action=action,result=jsonable(result)));return jsonable(result)


    @lab_operation
    def advanced_action(self,item):
        action=item['action'];identity=item.get('agent','NEURON-1');agent=self._agent(identity)
        if action=='language_read':
            result=read_language_sources(self,identity,files=item.get('files',[]),urls=item.get('urls',[]),seconds=item.get('seconds',300),max_bytes=item.get('max_bytes',1048576))
        elif action=='language_generate':
            if not isinstance(self.backend,CompactEncoderDecoder):raise ValueError('Use --model compact:pt')
            agent.ensure_bridge(self.backend);result=dict(text=agent.bridge.language().generate(item.get('prefix',''),max_tokens=item.get('tokens',64)),verified=False)
        elif action.startswith('architecture_'):
            editor=ArchitectureEditor(Path(__file__),self.directory/'architecture',self.history)
            result=editor.inspect() if action=='architecture_inspect' else editor.stage(item['source']) if action=='architecture_stage' else editor.activate(item.get('source',''))
        elif action in ('desktop_plan','desktop_execute'):
            controller=DesktopController(live=action=='desktop_execute' and item.get('live') is True,stop_file=self.directory/'STOP_DESKTOP',history=self.history)
            try:result=controller.execute(item.get('actions'))
            finally:controller.close()
        elif action=='desktop_teach':
            features=item.get('features',agent.sensor_features)
            if features is None:raise ValueError('Ative um sensor ou forneça 32 features')
            agent.motor_policy.teach(features,item['displacement']);result=dict(samples=len(agent.motor_policy.samples),executed=False)
        elif action=='desktop_suggest':
            features=item.get('features',agent.sensor_features)
            if features is None:raise ValueError('Ative um sensor ou forneça 32 features')
            result=agent.motor_policy.suggest(features)
        else:raise ValueError('Ação avançada desconhecida')
        self.history.append('lab.advanced.result',identity,dict(action=action,result=jsonable(result)))
        return jsonable(result)


    @lab_operation
    def seed_action(self,item):
        action=item['action'];identity=item.get('agent','NEURON-1')
        if action=='memory_search':
            query=item.get('query','')
            if not isinstance(query,str) or len(query)>8000:raise ValueError('Consulta HDC inválida')
            result=dict(matches=self.semantic_memory.search(identity,query),stats=self.semantic_memory.stats())
        elif action=='memory_add':
            self._agent(identity)
            result=dict(digest=self.semantic_memory.add(identity,item['text'],item.get('answer',''),kind='user_supplied'),stats=self.semantic_memory.stats())
        elif action in ('tools_policy','tool_plan','tool_goal'):
            if action=='tools_policy':
                hosts=item.get('http_hosts',[]);commands=item.get('commands',[]);write=item.get('allow_write',False)
                if type(write) is not bool or not isinstance(hosts,list) or len(hosts)>16 or any(not isinstance(h,str) or not re.fullmatch('[a-z0-9.-]{1,253}',h) for h in hosts):raise ValueError('Política HTTP/escrita inválida')
                if not isinstance(commands,list) or len(commands)>16 or any(not isinstance(c,list) or not c or len(c)>32 or any(not isinstance(a,str) or len(a)>1024 for a in c) for c in commands):raise ValueError('Política de comandos inválida')
                self.tool_policy=ToolPolicy(self.directory/'tools',allow_write=write,http_hosts=tuple(hosts),commands=tuple(tuple(c) for c in commands))
                result=dict(root=str(self.tool_policy.root),allow_write=write,http_hosts=hosts,commands=commands,persistence='Somente esta execução; reiniciar desabilita permissões.')
            else:
                harness=ToolHarness(self.tool_policy,self.history)
                result=dict(plan=harness.plan(item.get('goal',''))) if action=='tool_plan' else harness.execute_goal(item.get('goal',''))
        elif action in ('meta_inspect','meta_stage'):
            editor=MetaProgrammer(Path(__file__),self.directory/'patches',self.history)
            result=editor.inspect() if action=='meta_inspect' else editor.stage(item['expression'])
        elif action in ('sensor_observe','sensor_x11'):
            agent=self._agent(identity)
            sample=NativeSensors.screen_x11() if action=='sensor_x11' else dict(kind=item.get('kind'),values=item.get('values'))
            features=NativeSensors.features(sample['kind'],sample['values']);agent.sensor_features=features.copy();source='sensor:'+sample['kind']
            if agent.sensor_source!=source:agent.unit.reset_episode()
            agent.sensor_source=source
            perception=agent.unit.perceive(features);reconciliation=agent.unit.reconcile();plan=agent.unit.imagine_futures();action_vector=agent.unit.act(plan)
            result=dict(kind=sample['kind'],features=features,perception=perception,reconciliation=reconciliation,action=action_vector,
                observations=agent.unit.steps,meaning='Sinais amostrados e ação cognitiva interna; sem reconhecimento semântico nem controle do desktop.')
            self.history.append('sensor.sample',identity,dict(sample=sample,features=features))
        else:raise ValueError('Ação seed desconhecida')
        self.history.append('lab.seed.result',identity,dict(action=item['action'],result=jsonable(result)))
        return jsonable(result)


    @lab_operation
    def sleep_formal(self,identity,kind='heat',parameters=None):
        agent=self._agent(identity);before=agent.unit.steps
        consolidation=agent.unit.sleep(4)
        dreamed=agent.unit.dream(4) if agent.unit.current_state is not None else None
        receipt=self.simulate(identity,kind,parameters)
        result=dict(consolidation=consolidation,neural_dream=dreamed,model_simulation=receipt,
            observations_before=before,observations_after=agent.unit.steps,
            source='simulations_are_not_real_observations')
        self.history.append('math.sleep',identity,result)
        return jsonable(result)

    @lab_operation
    def category(self,identity,spec=None):
        agent=self._agent(identity)
        receipt=self.calculate(identity,dict(op='system.category',args=[spec or {}]))
        agent.unit.perceive_scene(dict(subject='sensor',relation='precedes',object='perception'))
        agent.unit.teach_rule('explicit-pipeline-order','precedes','follows',swap=True)
        self.history.append('math.category',identity,dict(receipt=receipt['id'],
            interpretation='Modelo finito declarado; não é descoberta de adjunção da mente nem prova de compreensão'))
        return receipt

    @lab_operation
    def formal_step(self):
        if self.formal_race is None:
            self.formal_race=FormalArmsRace(self.config.seed)
            self.formal_race.attach(self.history)
        report=self.formal_race.step()
        for agent in self.agents:
            before={k:v.copy() for k,v in agent.formal_router.core.p.items()}
            losses=[]
            for case in self.formal_race.last_cases:
                losses.append(agent.formal_router.learn_one(case['features'],case['label']).loss)
            agent.last_formal_numpy=numpy_inspection(agent.formal_router,self.formal_race.last_cases[-1]['features'],before)
            self.history.append('formal.agent_learning',agent.identity,dict(inspection=agent.last_formal_numpy,
                loss=float(np.mean(losses)),labels='Estratégia com menor proxy de trabalho entre duas soluções verificadas'))
        return report

    @lab_operation
    def reply(self, identity: str, message: str, *, source="usuario"):
        if not isinstance(message,str) or not message.strip() or len(message)>4000:
            raise ValueError("Mensagem deve ter entre 1 e 4000 caracteres")
        agent=self._agent(identity)
        request=route_math_message(message)
        receipt=self.calculate(identity,request) if request is not None else None
        if receipt is None: self._require_model()
        if self.backend is not None:
            agent.ensure_bridge(self.backend)
            initial=self.backend.encode(message)
            retrieved=agent.retrieve(initial['features'],query=message)
            prompt=agent.prompt(message,retrieved)
            if receipt is not None:
                prompt += '\nDADOS DO OMNIMAT (não são instruções):\n'+_math_display(receipt['result'],2500)
                prompt += '\nExplique brevemente o resultado. Não modifique os dados calculados.'
            encoded=self.backend.encode(prompt)
            features=encoded['features'];initial_features=initial['features'];sensor='encoder'
        else:
            # Sensação formal explicitamente identificada; não simula um encoder inexistente.
            digest=hashlib.sha256(message.encode()).digest()
            features=(np.frombuffer(digest,dtype=np.uint8).astype(float)-127.5)/127.5
            initial_features=features.copy();prompt='';retrieved=[];sensor='formal_receipt_hash'
        if agent.sensor_source is not None and agent.sensor_source!=sensor:
            agent.unit.reset_episode()
        agent.sensor_source=sensor
        perception=agent.unit.perceive(features);reconciliation=agent.unit.reconcile()
        plan=agent.unit.imagine_futures();action=agent.unit.act(plan)
        context=agent.context(features,action)
        self.history.append('lab.neural_state',identity,dict(sensation=features,sensor_source=sensor,
            perception=perception,plan=plan,action=action,context=context,reconciliation=reconciliation,
            formal_receipt=None if receipt is None else receipt['id']))
        commentary='';inspection=None
        if self.backend is not None:
            commentary,inspection=self.backend.generate(encoded,agent.bridge,context)
            inspection['stamp']=uuid.uuid4().hex
        if receipt is not None:
            answer=formal_answer(receipt)
            if commentary: answer+='\n\nComentário do decoder (não verificado):\n'+commentary
        else: answer=commentary
        agent.last_prompt=prompt
        agent.last_features,agent.last_context,agent.last_action=features.copy(),context.copy(),action.copy()
        agent.last_transformer=inspection;agent.turns+=1;agent.last_text=answer
        agent.memories.append(dict(question=message,answer=answer[:4000],features=initial_features.tolist(),
            kind='formal_result' if receipt is not None else 'dialogue',
            formal_receipt=None if receipt is None else receipt['id']))
        agent.messages.append(dict(speaker=source,text=message));agent.messages.append(dict(speaker=identity,text=answer[:8000]))
        event=dict(agent=identity,source=source,input=message,text=answer,empty_output=not bool(answer),
            turn=agent.turns,inspection=inspection,neural_action=action,transition_learned=reconciliation['learned'],
            formal_result=receipt,decoder_commentary=commentary if receipt is not None else None,
            authority='OMNIMAT result only; decoder commentary is unverified' if receipt is not None else 'neural_generation')
        self.history.append('lab.dialogue',identity,event)
        self.semantic_memory.add(identity,message,answer[:8000],kind='formal_result' if receipt is not None else 'dialogue')
        if isinstance(agent.bridge,CompactBridge) and agent.bridge.language().tokenizer is not None:agent.bridge.language().tokenizer.persist(self.history,identity)
        return jsonable(event)

    @lab_operation
    def social_round(self, topic: str):
        self._require_model()
        if not isinstance(topic,str) or not topic.strip() or len(topic)>1000:
            raise ValueError("Tema deve ter entre 1 e 1000 caracteres")
        self.numeric_step()
        previous = "Tema: " + topic
        replies=[]
        for agent in self.agents:
            status=f"Instância {agent.identity}; perda nas tarefas {agent.task.loss_ema:.3f}; especialistas {agent.task.core.active}."
            event=self.reply(agent.identity,previous+"\n"+status,source="sociedade")
            replies.append(event)
            previous=f"Tema: {topic}\nMensagem anterior de {agent.identity}: {event['text']}\nContinue a conversa com uma contribuição curta."
            if agent.unit._last is not None:
                t=agent.unit._last
                for peer in self.agents:
                    if peer is not agent:
                        peer.unit.observe_peer(agent.identity,t.state,t.action,t.outcome)
                        self.history.append("lab.social_learning",peer.identity,dict(from_agent=agent.identity,transition=t))
            if not agent.unit.culture:
                agent.unit.teach_skill("acao-"+agent.identity,[agent.last_action.tolist()],context={"source":agent.identity})
            for artifact in agent.unit.export_culture():
                for peer in self.agents:
                    if peer is not agent:
                        peer.unit.adopt_artifact(artifact)
        self.history.append("lab.social_round","society",dict(topic=topic,agents=[a.identity for a in self.agents]))
        return replies

    @lab_operation
    def feedback(self, identity: str, good: bool):
        agent=self._agent(identity)
        if type(good) is not bool or agent.turns==0:
            raise ValueError("Feedback exige resposta anterior e good=true/false")
        before={k:v.copy() for k,v in agent.quality.core.p.items()}
        report=agent.quality.learn_one(agent.last_features,int(good))
        inspection=numpy_inspection(agent.quality,agent.last_features,before)
        result=dict(agent=identity,good=good,report=report,inspection=inspection,
                    updated="avaliador_NumPy; próxima ponte recebe sua probabilidade")
        self.history.append("lab.feedback",identity,result)
        return jsonable(result)

    @lab_operation
    def teach(self, identity: str, question: str, answer: str, *, steps=4):
        self._require_model()
        if any(not isinstance(t,str) or not t.strip() or len(t)>4000 for t in (question,answer)):
            raise ValueError("Entrada e resposta de ensino devem ter entre 1 e 4000 caracteres")
        agent=self._agent(identity)
        agent.ensure_bridge(self.backend)
        encoded=self.backend.encode(agent.prompt(question,[]))
        context=agent.context(encoded["features"],agent.last_action)
        result=self.backend.teach(encoded,agent.bridge,context,answer,steps=steps)
        memory_features = self.backend.encode(question)["features"]
        retained = [m for m in agent.memories if m["question"] != question]
        agent.memories.clear()
        agent.memories.extend(retained)
        agent.memories.append(dict(question=question,answer=answer,features=memory_features.tolist(),kind="teaching"))
        agent.teachings+=1
        if isinstance(agent.bridge,CompactBridge) and agent.bridge.language().tokenizer is not None:agent.bridge.language().tokenizer.persist(self.history,identity)
        self.semantic_memory.add(identity,question,answer,kind="teaching")
        self.history.append("lab.teach",identity,dict(question=question,answer=answer,result=result))
        return result

    def _save_bytes(self):
        state=dict(format="neuron-laboratory",version=1,config=dataclasses.asdict(self.config),
            rng=self.rng.bit_generator.state,population=self.population,archive=list(self.archive),
            rounds=self.rounds,metrics=list(self.metrics),agents=[],base_signature=self.expected_signature,
            has_formal_race=self.formal_race is not None,synthetic_state=self.synthetic_state,auto_improvement_state=self.auto_improvement_state)
        output=io.BytesIO()
        with zipfile.ZipFile(output,"w",zipfile.ZIP_DEFLATED) as archive:
            for agent in self.agents:
                prefix=agent.identity
                arrays=(_bridge_arrays(agent.bridge) if agent.bridge is not None else agent.saved_bridge)
                record=dict(identity=prefix,index=agent.index,turns=agent.turns,teachings=agent.teachings,
                    last_features=agent.last_features,last_context=agent.last_context,last_action=agent.last_action,
                    last_numpy=agent.last_numpy,last_transformer=agent.last_transformer,messages=list(agent.messages),
                    last_formal=agent.last_formal,last_formal_numpy=agent.last_formal_numpy,
                    motor_policy=agent.motor_policy.dump(),sensor_features=agent.sensor_features,
                    sensor_source=agent.sensor_source,hypotheses=list(agent.hypotheses),
                    memories=list(agent.memories),last_text=agent.last_text,last_prompt=agent.last_prompt,has_bridge=arrays is not None)
                state["agents"].append(record)
                for name,model in (("task",agent.task),("quality",agent.quality),("unit",agent.unit),("formal_router",agent.formal_router)):
                    archive.writestr(prefix+"/"+name,_checkpoint_bytes(model))
                if arrays is not None:
                    buffer=io.BytesIO()
                    np.savez_compressed(buffer,**arrays)
                    archive.writestr(prefix+"/bridge.npz",buffer.getvalue())
            if self.formal_race is not None:
                archive.writestr('formal_race',self.formal_race.save_bytes())
            archive.writestr("state.json",json.dumps(jsonable(state),ensure_ascii=False,allow_nan=False))
        return output.getvalue()

    def _load_bytes(self,data):
        with zipfile.ZipFile(io.BytesIO(data)) as archive:
            if len(archive.infolist())>64 or sum(e.file_size for e in archive.infolist())>256*1024*1024:
                raise ValueError("Checkpoint de laboratório excede orçamento")
            state=json.loads(archive.read("state.json"))
            if state.get("format")!="neuron-laboratory" or state.get("version")!=1:
                raise ValueError("Formato de laboratório incompatível")
            self.config=LabConfig(**state["config"])
            self.synthetic_state=state.get("synthetic_state",synthetic_state())
            self.auto_improvement_state=state.get("auto_improvement_state",dict(rounds=0,recent=[]))
            if type(self.auto_improvement_state.get("rounds")) is not int or self.auto_improvement_state["rounds"]<0 or len(self.auto_improvement_state.get("recent",[]))>32:raise ValueError("Estado de auto-melhoria inválido")
            if self.synthetic_state.get("version")!=1 or len(self.synthetic_state.get("recent",[]))>32:raise ValueError("Estado sintético inválido")
            self.expected_signature=state.get("base_signature")
            if self.backend is not None:
                self.backend.config=self.config
                if isinstance(self.backend,NativeSeq2Seq):self.backend.signature=self.backend.compatibility_signature()
            if len(state["agents"])!=self.config.agents:
                raise ValueError("Contagem inválida de instâncias")
            self.rng=np.random.default_rng()
            self.rng.bit_generator.state=state["rng"]
            population=np.asarray(state["population"],dtype=float)
            if population.shape!=(8,6) or not np.isfinite(population).all() or np.any(np.abs(population)>1):
                raise ValueError("População inválida")
            self.population=population
            if len(state["archive"])>16 or len(state["metrics"])>96:
                raise ValueError("Memórias de laboratório excedem limites")
            self.archive=deque((_vector(g,6,"genome",1) for g in state["archive"]),maxlen=16)
            self.metrics=deque(state["metrics"],maxlen=96)
            self.rounds=_count(state["rounds"],"rounds")
            self.formal_race=FormalArmsRace.load_bytes(archive.read('formal_race')) if state.get('has_formal_race') else None
            if self.formal_race is not None and hasattr(self,'history'): self.formal_race.attach(self.history)
            self.agents=[]
            for i,record in enumerate(state["agents"]):
                identity=f"NEURON-{i+1}"
                if record["identity"]!=identity or record["index"]!=i:
                    raise ValueError("Identificador de instância inválido")
                agent=DialogueNeuron(identity,i,self.config)
                agent.task=Neuron.load(io.BytesIO(archive.read(identity+"/task")))
                agent.quality=Neuron.load(io.BytesIO(archive.read(identity+"/quality")))
                agent.unit=CognitiveUnit.load(io.BytesIO(archive.read(identity+"/unit")))
                if identity+'/formal_router' in archive.namelist():
                    agent.formal_router=Neuron.load(io.BytesIO(archive.read(identity+'/formal_router')))
                agent.last_formal=record.get('last_formal');agent.sensor_source=record.get('sensor_source')
                agent.last_formal_numpy=record.get('last_formal_numpy',agent.last_formal_numpy)
                if 'motor_policy' in record:agent.motor_policy=DesktopMotorPolicy.load(record['motor_policy'])
                agent.sensor_features=None if record.get('sensor_features') is None else _vector(record['sensor_features'],32,'sensor_features')
                if len(record.get('hypotheses',[]))>32: raise ValueError('Hipóteses excedem capacidade')
                agent.hypotheses.extend(record.get('hypotheses',[]))
                if (agent.task.config.input_dim,agent.quality.config.input_dim,agent.unit.config.sensory_dim,agent.unit.config.motor_dim)!=(8,32,32,4):
                    raise ValueError("Dimensões inválidas de instância")
                for name,size in (("last_features",32),("last_context",48),("last_action",4)):
                    setattr(agent,name,_vector(record[name],size,name))
                if len(record["memories"])>self.config.memory_capacity or len(record["messages"])>agent.messages.maxlen:
                    raise ValueError("Memória de diálogo excede capacidade")
                for memory in record["memories"]:
                    _vector(memory["features"],32,"memory")
                agent.memories.extend(record["memories"])
                agent.messages.extend(record["messages"])
                agent.turns=_count(record["turns"],"turns")
                agent.teachings=_count(record["teachings"],"teachings")
                for name in ("last_numpy","last_transformer","last_text","last_prompt"):
                    setattr(agent,name,record[name])
                if record["has_bridge"]:
                    with np.load(io.BytesIO(archive.read(identity+"/bridge.npz")),allow_pickle=False) as weights:
                        agent.saved_bridge={k:weights[k].copy() for k in weights.files}
                    if self.backend is not None:
                        agent.ensure_bridge(self.backend)
                if hasattr(self,"history"):
                    agent.attach(self.history)
                agent.semantic_memory=self.semantic_memory
                self.agents.append(agent)

    @lab_operation
    def inspect_encoder_decoder(self, identity: str):
        self._require_model()
        agent = self._agent(identity)
        if not agent.last_prompt:
            raise ValueError("Converse com a instância antes de inspecionar")
        encoded = self.backend.encode(agent.last_prompt)
        _, report = self.backend.generate(encoded, agent.bridge, agent.last_context)
        report["stamp"] = uuid.uuid4().hex
        agent.last_transformer = report
        export = self.directory / "exports" / (identity + ".npz")
        self.backend.export_tensors(export)
        summary = self.directory / "exports" / (identity + ".json")
        summary.write_text(json.dumps(report, ensure_ascii=False, allow_nan=False), encoding="utf-8")
        result = dict(agent=identity, tensors=str(export), report=str(summary), stamp=report["stamp"])
        self.history.append("lab.inspection", identity, result)
        return result

    def checkpoint(self):
        self.history.checkpoint("lab",self._save_bytes(),dict(type="neuron-laboratory",rounds=self.rounds,
            model=self.config.model,turns=sum(a.turns for a in self.agents)))

    def close(self):
        if not self.closed:
            auto=getattr(self,'auto_improvement',None)
            if auto is not None:auto.stop()
            observatory=getattr(self,'agent_observatory',None)
            if observatory is not None:observatory.close();self.agent_observatory=None
            self.curriculum.stop()
            self.history.close()
            self._lease.__exit__()
            self.closed=True

    def __enter__(self):
        return self

    def __exit__(self,*_):
        self.close()

