class LaboratoryWorker:
    """Uma fila limitada e um único escritor para todos os trabalhos do painel."""
    def __init__(self, lab: NeuronLaboratory):
        import queue
        self.lab, self.queue_module = lab, queue
        self.queue = queue.Queue(maxsize=8)
        self.lab.foreground_queue=self.queue
        self.stop_event = threading.Event()
        self.continuous = threading.Event()
        self._lock = threading.RLock()
        self.busy, self.current = False, ""
        self.auto_mode, self.topic = "step", "Como reduzir o esquecimento?"
        self.thread = threading.Thread(target=self._loop, name="neuron-local-worker", daemon=True)
        self.thread.start()

    def status(self):
        with self._lock:
            return dict(busy=self.busy, current=self.current, running=self.continuous.is_set(), mode=self.auto_mode, queued=self.queue.qsize())

    def submit(self, item):
        action = item.get("action")
        allowed = {"run","run_social","run_formal","calculate","simulate","sleep_formal","category","formal_step","stop","step","social","load","reply","feedback","teach","inspect","verify"}
        allowed |= SEED_ACTIONS | ADVANCED_ACTIONS | EIGHT_ACTIONS
        if action not in allowed:
            raise ValueError("Ação desconhecida")
        if action == "stop":
            self.lab.history.append("lab.control", "client", item)
            self.continuous.clear()
            return dict(message="Pausa solicitada; a operação atual será concluída.")
        if action in ("run", "run_social", "run_formal"):
            if action == "run_social":
                if self.lab.backend is None:
                    raise ValueError("Carregue o Encoder–Decoder antes do diálogo contínuo")
                topic = item.get("topic", "Como reduzir o esquecimento?")
                if not isinstance(topic,str) or not 1 <= len(topic) <= 1000:
                    raise ValueError("Tema deve ter entre 1 e 1000 caracteres")
            self.lab.history.append("lab.control", "client", item)
            with self._lock:
                self.auto_mode = "social" if action == "run_social" else "formal_step" if action == "run_formal" else "step"
                self.topic = item.get("topic", self.topic)
                self.continuous.set()
            return dict(message="Diálogo contínuo iniciado." if action == "run_social" else "Evolução numérica contínua iniciada.")
        if action in ("social","load","reply","teach","inspect","calculate","simulate","sleep_formal","category","formal_step"):
            self.continuous.clear()
        if action in ("reply","feedback","teach","inspect","calculate","simulate","sleep_formal","category"):
            self.lab._agent(item.get("agent"))
        if action == "reply" and (not isinstance(item.get("text"),str) or not 1<=len(item["text"])<=4000):
            raise ValueError("Mensagem deve ter entre 1 e 4000 caracteres")
        if action == "teach" and any(not isinstance(item.get(k),str) or not 1<=len(item[k])<=4000 for k in ("question","answer")):
            raise ValueError("Preencha a entrada e a resposta de ensino")
        if action == "social" and (not isinstance(item.get("topic"),str) or not 1<=len(item["topic"])<=1000):
            raise ValueError("Tema deve ter entre 1 e 1000 caracteres")
        identifier=uuid.uuid4().hex
        try:
            with self._lock:
                if self.queue.full():
                    raise self.queue_module.Full()
                self.lab.history.append("lab.job.queued", "client", dict(job=identifier, request=item))
                self.queue.put_nowait((identifier,dict(item)))
        except self.queue_module.Full as error:
            raise BufferError("Fila cheia; espere os trabalhos em andamento") from error
        return dict(job=identifier,message="Operação recebida: "+action)

    def _execute(self, item):
        action=item["action"]
        identity=item.get("agent","NEURON-1")
        if action=='calculate': return self.lab.calculate(identity,item['request'])
        if action=='simulate': return self.lab.simulate(identity,item.get('scenario','heat'),item.get('parameters',{}))
        if action=='sleep_formal': return self.lab.sleep_formal(identity,item.get('scenario','heat'),item.get('parameters',{}))
        if action=='category': return self.lab.category(identity,item.get('spec',{}))
        if action=='formal_step': return self.lab.formal_step()
        if action in EIGHT_ACTIONS:return self.lab.eight_action(item)
        if action in ADVANCED_ACTIONS:return self.lab.advanced_action(item)
        if action in SEED_ACTIONS:return self.lab.seed_action(item)
        if action=="step": return self.lab.numeric_step()
        if action=="social": return self.lab.social_round(item["topic"])
        if action=="load": return self.lab.load_model(offline=item.get("offline",False))
        if action=="reply": return self.lab.reply(identity,item["text"])
        if action=="feedback": return self.lab.feedback(identity,item["good"])
        if action=="teach": return self.lab.teach(identity,item["question"],item["answer"],steps=item.get("steps",4))
        if action=="inspect": return self.lab.inspect_encoder_decoder(identity)
        if action=="verify":
            result=self.lab.history.verify()
            self.lab.history.append("lab.verify","lab",result)
            return result
        raise ValueError("Trabalho desconhecido")

    def _loop(self):
        next_step=0.0
        while not self.stop_event.is_set():
            queued=False
            try:
                identifier,item=self.queue.get(timeout=0.15)
                queued=True
            except self.queue_module.Empty:
                if not self.continuous.is_set() or time.monotonic()<next_step:
                    continue
                with self._lock:
                    item=dict(action=self.auto_mode)
                    if self.auto_mode == "social":
                        item["topic"] = self.topic
                identifier="continuous"
                next_step=time.monotonic()+(5.0 if item["action"]=="social" else 1.0)
            with self._lock:
                self.busy,self.current=True,item["action"]
            try:
                result=self._execute(item)
                self.lab.history.append("lab.job.completed","worker",dict(job=identifier,action=item["action"],
                    result=result if item["action"] in ("inspect","verify","teach","load") else "gravado nos eventos da operação"))
            except Exception as error:
                self.continuous.clear()
                self.lab.history.append("lab.error","worker",dict(job=identifier,operation=item["action"],
                    error=type(error).__name__,message=str(error)))
                self.lab._refresh(error=str(error))
            finally:
                with self._lock:
                    self.busy,self.current=False,""
                if queued:
                    self.queue.task_done()

    def close(self):
        self.continuous.clear()
        self.stop_event.set()
        started = time.monotonic()
        announced = False
        while self.thread.is_alive():
            try:
                self.thread.join(timeout=0.5)
            except KeyboardInterrupt:
                print("Aguardando a operação atual para fechar o histórico com segurança.", flush=True)
            if not announced and time.monotonic()-started > 3:
                print("Concluindo a operação em andamento antes de encerrar…", flush=True)
                announced = True


def make_lab_server(lab: NeuronLaboratory, worker: LaboratoryWorker, port: int = 8765):
    from http.server import ThreadingHTTPServer, BaseHTTPRequestHandler
    from urllib.parse import urlsplit, parse_qs
    class Handler(BaseHTTPRequestHandler):
        server_version = "NeuronLocal/6"
        protocol_version = "HTTP/1.1"
        def log_message(self,*_):
            pass

        def _send(self,code,payload,content_type="application/json; charset=utf-8",download=None):
            if isinstance(payload,bytes): data=payload
            elif content_type.startswith("application/json"):
                data=json.dumps(jsonable(payload),ensure_ascii=False,allow_nan=False).encode("utf-8")
            else: data=payload.encode("utf-8")
            self.send_response(code)
            self.send_header("Content-Type",content_type)
            self.send_header("Content-Length",str(len(data)))
            self.send_header("Cache-Control","no-store")
            if self.close_connection:
                self.send_header("Connection","close")
            self.send_header("X-Content-Type-Options","nosniff")
            self.send_header("Referrer-Policy","no-referrer")
            self.send_header("Content-Security-Policy","default-src 'self'; script-src 'self' 'unsafe-inline'; style-src 'self' 'unsafe-inline'; connect-src 'self'; frame-ancestors 'none'")
            if download: self.send_header("Content-Disposition",'attachment; filename="'+download+'"')
            self.end_headers()
            try: self.wfile.write(data)
            except (BrokenPipeError,ConnectionResetError): pass

        def _host_ok(self):
            actual=self.server.server_port
            return self.headers.get("Host","") in (f"127.0.0.1:{actual}",f"localhost:{actual}")

        def do_GET(self):
            if not self._host_ok():
                self._send(403,dict(error="Host não autorizado"));return
            parsed=urlsplit(self.path)
            query=parse_qs(parsed.query)
            try:
                if parsed.path=="/ws":
                    serve_neural_websocket(self,lab);return
                if parsed.path=="/":
                    self._send(200,LAB_HTML,"text/html; charset=utf-8")
                elif parsed.path=="/api/state":
                    result=lab.view();result["worker"]=worker.status();self._send(200,result)
                elif parsed.path=="/api/math/catalog":
                    self._send(200,dict(areas=catalogo(),operations=sum(map(len,catalogo().values()))))
                elif parsed.path=="/api/inspection":
                    self._send(200,lab.inspection(query.get("agent",["NEURON-1"])[0]))
                elif parsed.path=="/api/events":
                    after=int(query.get("after",["0"])[0]);_count(after,"after")
                    reader=sqlite3.connect(lab.history.path.resolve().as_uri()+"?mode=ro",uri=True)
                    try:
                        rows=reader.execute("SELECT id,utc,actor,kind,payload FROM events WHERE id>? AND (kind LIKE 'lab.%' OR kind LIKE 'math.%' OR kind LIKE 'formal.%' OR kind LIKE 'curriculum.%' OR kind LIKE 'language.%' OR kind LIKE 'thought.%' OR kind LIKE 'agent.%' OR kind LIKE 'dataset.%' OR kind LIKE 'auto.%' OR kind LIKE 'meta.live%') ORDER BY id LIMIT 50",(after,))
                        events=[dict(id=r[0],utc=r[1],actor=r[2],kind=r[3],payload=json.loads(r[4])) for r in rows]
                    finally: reader.close()
                    self._send(200,dict(events=events))
                elif parsed.path=="/api/artifact":
                    identity=query.get("agent",["NEURON-1"])[0]
                    lab._agent(identity)
                    path=lab.directory/"exports"/(identity+".npz")
                    if not path.is_file(): raise ValueError("Exporte uma inspeção primeiro")
                    self._send(200,path.read_bytes(),"application/octet-stream",identity+"-tensors.npz")
                else: self._send(404,dict(error="Recurso inexistente"))
            except (ValueError,TypeError,KeyError,OSError) as error:
                self._send(400,dict(error=str(error)))

        def do_POST(self):
            if not self._host_ok(): self.close_connection=True;self._send(403,dict(error="Host não autorizado"));return
            origin=self.headers.get("Origin")
            allowed=(f"http://127.0.0.1:{self.server.server_port}",f"http://localhost:{self.server.server_port}")
            if origin is not None and origin not in allowed:
                self.close_connection=True
                self._send(403,dict(error="Origem não autorizada"));return
            if self.path!="/api/action": self.close_connection=True;self._send(404,dict(error="Recurso inexistente"));return
            if not self.headers.get("Content-Type","").startswith("application/json"):
                self.close_connection=True
                self._send(415,dict(error="Envie application/json"));return
            try:
                length=int(self.headers.get("Content-Length","0"))
                if not 0<length<=32768:
                    self.close_connection=True
                    self._send(413,dict(error="Requisição excede o limite de 32 KiB"));return
                raw=self.rfile.read(length)
                lab.history.append("lab.http.request","client",dict(body=raw.decode("utf-8",errors="replace")))
                item=json.loads(raw)
                if not isinstance(item,dict): raise ValueError("Objeto JSON esperado")
                result=worker.submit(item)
                self._send(202,result)
            except (ValueError,TypeError,KeyError,BufferError) as error:
                self._send(400,dict(error=str(error)))
            except (OSError,sqlite3.Error,RuntimeError) as error:
                self._send(500,dict(error="Não foi possível persistir a solicitação: "+str(error)))
    class RealtimeHTTPServer(ThreadingHTTPServer):
        daemon_threads=True
        def server_close(self):
            self.ws_stop.set()
            super().server_close()
    server=RealtimeHTTPServer(("127.0.0.1",port),Handler)
    server.ws_slots=threading.BoundedSemaphore(4);server.ws_stop=threading.Event()
    server.daemon_threads=True
    return server


def run_lab_dashboard(directory: Path, config: LabConfig, *, port=8765, open_browser=False, load_model=False, offline=False,curriculum=False,teacher=False):
    if type(port) is not int or not 0<=port<=65535:
        raise ValueError("Porta deve estar entre 0 e 65535")
    with NeuronLaboratory(directory,config) as lab:
        worker=LaboratoryWorker(lab)
        try:
            server=make_lab_server(lab,worker,port)
            url=f"http://127.0.0.1:{server.server_port}"
            print("NEURON · painel local: "+url,flush=True)
            print("Histórico e checkpoints: "+str(lab.history.path),flush=True)
            print("Ctrl+C encerra o servidor; fechar a aba não encerra a sessão.",flush=True)
            if curriculum:
                lab.load_model(offline=offline);lab.curriculum.start(teacher=teacher)
            elif load_model: worker.submit(dict(action="load",offline=offline))
            if open_browser:
                import webbrowser
                webbrowser.open(url)
            try: server.serve_forever(poll_interval=0.25)
            except KeyboardInterrupt: pass
            finally: server.server_close()
        finally:
            worker.close()
    return 0


def download_encoder_decoder(model: str, destination: Path, *, revision="main"):
    """Snapshot local, só pesos safetensors; não habilita código remoto."""
    try:
        from huggingface_hub import snapshot_download
        from transformers import AutoConfig
    except ImportError as error:
        raise RuntimeError("Instale as dependências Encoder–Decoder pelo menu") from error
    destination=Path(destination)
    description=AutoConfig.from_pretrained(model,revision=revision,trust_remote_code=False,
        cache_dir=str(destination.parent/"cache"))
    if not description.is_encoder_decoder:
        raise ValueError("Modelo recusado: escolha um Encoder–Decoder")
    path=snapshot_download(repo_id=model,revision=revision,local_dir=str(destination),
        allow_patterns=["*.json","*.safetensors","*.model","*.txt","*.spm"],
        ignore_patterns=["optimizer*","training_args*","*.bin","*.pt","*.pth"])
    if not list(Path(path).glob("*.safetensors")):
        raise ValueError("Repositório não forneceu pesos safetensors compatíveis")
    print("Encoder–Decoder baixado em: "+str(path))
    return path


def install_neuron_dependencies(full=True):
    import subprocess
    print("Instalando no Python em uso: "+sys.executable,flush=True)
    subprocess.run([sys.executable,"-m","pip","install","numpy>=1.24"],check=True)
    if full:
        torch_command=[sys.executable,"-m","pip","install","torch>=2.6,<3"]
        if sys.platform.startswith("linux") or sys.platform=="win32":
            torch_command += ["--index-url","https://download.pytorch.org/whl/cpu"]
        subprocess.run(torch_command,check=True)
        subprocess.run([sys.executable,"-m","pip","install","transformers>=4.46,<5","sentencepiece>=0.2"],check=True)
    print("Dependências instaladas. Se alguma já estava importada, reinicie o programa.")


def run_neuron_chat(directory,config,*,identity="NEURON-1",offline=False):
    with NeuronLaboratory(directory,config) as lab:
        try:
            lab.load_model(offline=offline)
        except (OSError,RuntimeError,ValueError) as error:
            print('Encoder–Decoder indisponível: '+str(error))
            print('Córtex matemático disponível: /calc, /simular e /categoria continuam funcionando.')
        print("\nNEURON · Encoder–Decoder integrado: "+lab.config.model)
        print("Comandos: /sair · /estado · /bom · /ruim · /ensinar entrada => resposta · /inspecionar · /calc nt.factor [12345] · /simular heat · /categoria")
        while True:
            try: message=input("\nVocê > ").strip()
            except (EOFError,KeyboardInterrupt): print();break
            if not message: continue
            try:
                if message=="/sair": break
                if message=="/estado":
                    agent=next(a for a in lab.view()["agents"] if a["id"]==identity)
                    print(json.dumps(agent,ensure_ascii=False,indent=2));continue
                if message in ("/bom","/ruim"):
                    print(json.dumps(lab.feedback(identity,message=="/bom"),ensure_ascii=False));continue
                if message.startswith("/ensinar "):
                    pair=message[len("/ensinar "):].split("=>",1)
                    if len(pair)!=2: raise ValueError("Use /ensinar entrada => resposta")
                    print(json.dumps(lab.teach(identity,pair[0].strip(),pair[1].strip()),ensure_ascii=False,indent=2));continue
                if message=="/inspecionar":
                    print(json.dumps(lab.inspect_encoder_decoder(identity),ensure_ascii=False,indent=2));continue
                result=lab.reply(identity,message)
                print(identity+" > "+(result["text"] or "[decoder produziu somente tokens especiais]"))
                agent=lab._agent(identity)
                print(f"  [transições: {agent.unit.transitions} · memórias: {len(agent.memories)} · ação: {np.round(agent.last_action,3)}]")
            except KeyboardInterrupt:
                print("\nOperação interrompida. Retome a sessão para recuperar o último checkpoint completo.")
                break
            except (ValueError,RuntimeError,OSError,FloatingPointError) as error:
                print("Erro: "+str(error))
    return 0


def run_social_console(directory,config,*,rounds=3,topic="Como reduzir o esquecimento?",offline=False):
    _count(rounds,"rounds",1)
    with NeuronLaboratory(directory,config) as lab:
        lab.load_model(offline=offline)
        for i in range(rounds):
            print(f"\n── Rodada social {i+1} ──")
            for reply in lab.social_round(topic):
                print(reply["agent"]+" > "+(reply["text"] or "[somente tokens especiais]"))
    return 0


def _menu_input(prompt,default=None):
    text=input(prompt+(f" [{default}]" if default is not None else "")+": ").strip()
    return text if text else default


def run_math_cli(args):
    if args.command=='math-catalog':
        module=omnimat();areas=module.catalogo()
        if args.area:
            if args.area not in areas: raise ValueError('Área inexistente')
            areas={args.area:areas[args.area]}
        print(json.dumps(dict(areas=areas,area_count=len(areas),operations=sum(map(len,areas.values()))),ensure_ascii=False,indent=2))
        return 0
    if args.command=='omnimat-selftest':
        result=omnimat().selftest()
        return 0 if all(v[0]!='FALHA' for v in result.values()) else 1
    if args.command=='math-arms-race': return run_formal_race(args.directory,args.rounds)
    if args.command in ('simulate','categories'):
        with NeuronLaboratory(args.directory) as lab:
            result=lab.simulate(args.agent,args.scenario,json.loads(args.parameters)) if args.command=='simulate' else lab.category(args.agent,json.loads(args.spec))
            print(formal_answer(result))
        return 0
    if args.command=='jit':
        request=dict(op='system.jit',args=[args.expression,json.loads(args.points)],native=True)
    else:
        request=dict(op=args.operation,args=json.loads(args.arguments),kwargs=json.loads(args.kwargs),native=args.native)
    with RunLease(args.directory/'writer.lock'),EventHistory(args.directory/'history.sqlite') as history:
        receipt=FormalCortex(history,'terminal',timeout=args.timeout).run(request)
        print(json.dumps(receipt,ensure_ascii=False,indent=2,allow_nan=False) if args.json_output else formal_answer(receipt))
    return 0


