class FormalIntegrationTests(unittest.TestCase):
    def test_full_original_catalog_and_namespace_isolation(self):
        self.assertEqual(len(catalogo()),39)
        self.assertEqual(sum(map(len,catalogo().values())),424)
        self.assertIn('codigo_maquina',catalogo()['nat'])
        self.assertIsNot(omnimat().deque,Neuron)
        model=Neuron(Config(branches=4,fourier_features=2))
        self.assertIsInstance(model.predict_one([0,0]),Prediction)
        self.assertEqual(calcular('nt.egcd',240,46)[0],2)

    def test_all_original_omnimat_test_areas(self):
        results=omnimat().selftest(verbose=False)
        self.assertEqual(len(results),25)
        for area,(status,elapsed,trace) in results.items():
            with self.subTest(area=area): self.assertEqual(status,'ok',trace)

    def test_large_integer_and_fraction_serialization_is_lossless(self):
        from fractions import Fraction
        value={('x',2):Fraction(1,3),'integer':2**61-1,'complex':2+3j}
        restored=_math_decode(_math_pack(value))
        self.assertEqual(restored,value)
        self.assertEqual(_math_pack(2**61-1),{'$integer':str(2**61-1)})

    def test_primality_contract_is_bounded_and_witnesses_composites(self):
        exact=omnimat().primality_report(2**61-1)
        probable=omnimat().primality_report(2**127-1)
        composite=omnimat().primality_report(341550071728321)
        self.assertTrue(exact['prime'] and exact['deterministic'])
        self.assertTrue(probable['prime']);self.assertFalse(probable['deterministic'])
        self.assertFalse(composite['prime']);self.assertTrue(composite['deterministic'])

