    def test_groebner_certificate_checks_both_inclusions_and_s_pairs(self):
        module=omnimat()
        certificate=module.groebner_certificate(['x^2+y^2-1','x-y'],'xy')
        self.assertTrue(module.verify_groebner_certificate(certificate))
        self.assertTrue(calcular('alg.ideal_member','2*y^2-1',certificate['basis'],'xy'))
        corrupted=copy.deepcopy(certificate)
        corrupted['representations'][0]=[{},{}]
        self.assertFalse(module.verify_groebner_certificate(corrupted))
        self.assertTrue(module.verify_groebner_certificate(module.groebner_certificate(['0'],'x')))

