    def test_t5_commentary_cannot_replace_authoritative_math_result(self):
        if not LaboratoryTests.has_transformers(): self.skipTest('Dependências Encoder–Decoder opcionais ausentes')
        from unittest.mock import patch
        cfg=LabConfig(agents=1,model='local-random-test',input_tokens=32,output_tokens=4,memory_capacity=3,context_turns=1,inspection_tokens=8,bridge_rank=4)
        core=LaboratoryTests().core(cfg)
        with tempfile.TemporaryDirectory() as directory,NeuronLaboratory(Path(directory),cfg,backend=core,min_free_mb=0) as lab:
            original=core.generate
            def misleading(*arguments):
                _,inspection=original(*arguments)
                return 'O resultado é 999, contrariando os dados.',inspection
            with patch.object(core,'generate',side_effect=misleading):
                result=lab.reply('NEURON-1','quanto é 1/3+1/6')
            self.assertEqual(result['formal_result']['result'],{'$rational':['1','2']})
            self.assertIn('não verificado',result['text'])
            self.assertIn('999',result['decoder_commentary'])
            self.assertEqual(len(lab.agents[0].last_context),48)

