    def test_encoder_state_conditions_decoder_and_attention_alignment(self):
        core=self.core()
        bridge=core.new_bridge(42)
        encoded=core.encode("Olá mundo")
        context=np.zeros(48)
        with core.torch.no_grad():
            one,_=core._condition(encoded,bridge,context)
            context[0]=1
            two,_=core._condition(encoded,bridge,context)
        self.assertFalse(core.torch.equal(one.last_hidden_state[:,:2],two.last_hidden_state[:,:2]))
        text,inspection=core.generate(encoded,bridge,context)
        cross=inspection["cross_attention"]
        self.assertEqual(cross["key_tokens"][:2],["[NEURON:0]","[NEURON:1]"])
        self.assertEqual(len(cross["matrix"][0]),len(inspection["decoder_input_tokens"]))
        self.assertEqual(len(inspection["encoder_states"]),2)
        self.assertEqual(inspection["origin"],"random-test")
        self.assertTrue(all(not p.requires_grad for p in core.model.parameters()))

    def test_real_gradient_teaches_only_individual_bridge(self):
        core=self.core()
        first,second=core.new_bridge(10),core.new_bridge(11)
        other={k:v.copy() for k,v in _bridge_arrays(second).items()}
        frozen={k:v.detach().clone() for k,v in core.model.named_parameters()}
        result=core.teach(core.encode("Olá mundo"),first,np.ones(48)*.1,"Resposta sim",steps=4)
        self.assertGreater(result["delta_l2"],0)
        self.assertLess(result["loss_after"],result["loss_before"])
        for key,value in core.model.named_parameters(): self.assertTrue(core.torch.equal(value,frozen[key]))
        for key,value in _bridge_arrays(second).items(): np.testing.assert_array_equal(value,other[key])
        self.assertFalse(result["backbone_updated"])

