class CognitiveTests(unittest.TestCase):
    def unit(self, **kwargs):
        settings = dict(sensory_dim=2, motor_dim=2, branches=6, fourier_features=3,
                        initial_experts=1, max_experts=2, ensemble_size=2,
                        replay_capacity=48, replay_batch=2, episodic_capacity=32,
                        vsa_dim=1024, symbolic_capacity=8, planning_candidates=10,
                        planning_iterations=2, planning_horizon=3, meta_every=10000,
                        meta_window=8, seed=7)
        settings.update(kwargs)
        return CognitiveUnit(Config(**settings))

    def feed(self, unit, count=12):
        rng = np.random.default_rng(8)
        if unit.current_state is None:
            unit.perceive([0.5, -0.5])
        for _ in range(count):
            a = unit.act(action=rng.uniform(-1, 1, 2))
            unit.perceive(0.8 * unit.current_state + 0.35 * a)
            unit.reconcile()

    def test_predictive_cycle_has_no_label_and_no_duplicate_training(self):
        unit = self.unit()
        unit.perceive([0.2, -0.2])
        self.assertFalse(unit.reconcile()["learned"])
        action = unit.act(action=[0.3, -0.1])
        expected = unit._awaiting["prediction"].copy()
        sensation = unit.perceive([0.4, -0.1])
        np.testing.assert_allclose(sensation.surprise, np.mean((np.array([0.4, -0.1]) - expected) ** 2))
        # Ordem da API proposta: age no presente antes de reconciliar o passado.
        unit.act(action=[0., 0.])
        report = unit.reconcile()
        np.testing.assert_array_equal(unit.episodes[-1].action, action)
        self.assertEqual(unit.world_model.updates, 1)
        self.assertTrue(report["learned"])
        self.assertFalse(unit.reconcile()["learned"])
        self.assertEqual(unit.world_model.updates, 1)

    def test_invalid_operations_do_not_drop_transitions(self):
        unit = self.unit()
        with self.assertRaises(RuntimeError):
            unit.act()
        unit.perceive([0., 0.])
        with self.assertRaises(RuntimeError):
            unit.perceive([0., 0.])
        with self.assertRaises(ValueError):
            unit.act(action=[2., 0.])
        self.assertIsNone(unit._awaiting)
        unit.act(action=[0., 0.])
        with self.assertRaises(RuntimeError):
            unit.act(action=[0., 0.])
        unit.perceive([0.1, 0.1])
        before = unit._pending
        with self.assertRaises(RuntimeError):
            unit.perceive([0.2, 0.2])
        self.assertIs(unit._pending, before)
        with self.assertRaises(ValueError):
            unit.perceive([float("nan"), 0.])
        self.assertTrue(unit.reconcile()["learned"])

    def test_imagination_does_not_train_and_factual_recovery(self):
        unit = self.unit()
        self.feed(unit)
        snapshots = [copy.deepcopy(m.core.p) for m in unit.world_model.models]
        rng = copy.deepcopy(unit.world_model.rng.bit_generator.state)
        steps = unit.world_model.updates
        actual = unit._last
        np.testing.assert_allclose(unit.imagine(actual.action, previous=True), actual.outcome, atol=1e-15)
        self.assertEqual(unit.world_model.rollout(unit.current_state, [[0, 0], [0.1, 0.1]]).shape, (3, 2))
        unit.imagine([0.2, -0.2])
        plan = unit.imagine_futures(horizon=3)
        self.assertEqual(plan.states.shape, (4, 2))
        self.assertTrue(np.all(np.abs(plan.actions) <= 1))
        self.assertEqual(unit.world_model.updates, steps)
        self.assertEqual(unit.world_model.rng.bit_generator.state, rng)
        for model, before in zip(unit.world_model.models, snapshots):
            for key in before:
                np.testing.assert_array_equal(model.core.p[key], before[key])

    def test_learns_action_conditioned_dynamics_and_plans(self):
        unit = self.unit(learning_rate=0.012, memory_strength=0., replay_batch=1,
                         consolidation_strength=0., slow_mix=0., project_memory=False)
        rng = np.random.default_rng(41)
        probes = [(rng.uniform(-1, 1, 2), rng.uniform(-1, 1, 2)) for _ in range(24)]
        def risk():
            return np.mean([np.mean((unit.world_model.predict(s, a)[0] - (0.8 * s + 0.35 * a)) ** 2) for s, a in probes])
        initial = risk()
        for _ in range(220):
            state, action = rng.uniform(-1, 1, 2), rng.uniform(-1, 1, 2)
            unit.observe_peer("teacher", state, action, 0.8 * state + 0.35 * action)
        self.assertLess(risk(), initial * 0.25)
        unit.perceive([0, 0])
        unit.set_goal([0.5, -0.5])
        plan = unit.imagine_futures(horizon=3, candidates=20)
        actual_next = 0.35 * plan.actions[0]
        self.assertLess(np.linalg.norm(actual_next - [0.5, -0.5]), np.linalg.norm([0.5, -0.5]))
        self.assertGreater(unit.imagine([1, 0])[0], unit.imagine([-1, 0])[0])

    def test_information_seeking_action_uses_epistemic_proxy(self):
        unit = self.unit(risk_weight=0., effort_weight=0.)
        unit.perceive([0, 0])
        unit.world_model.predict = lambda state, action: (np.asarray(state).copy(), float(np.sum(np.asarray(action) ** 2)), 1.)
        action = unit.act_to_perceive()
        self.assertGreater(np.linalg.norm(action), 0.8)
        np.testing.assert_array_equal(action, unit._awaiting["action"])

    def test_vsa_unbind_retrieves_roles_and_zero_shot_rule(self):
        unit = self.unit(vsa_dim=4096)
        symbols = unit.symbols
        a, b = symbols.symbol("role"), symbols.symbol("cat")
        np.testing.assert_array_equal(symbols.unbind(symbols.bind(a, b), a), b)
        scene = symbols.encode(dict(subject="cat", relation="above", object="table"))
        self.assertEqual(symbols.query(scene, "object", ["cat", "table", "above"])[0][0], "table")
        unit.teach_rule("inverse", "above", "below", swap=True)
        result = symbols.infer("astronaut", "above", "moon")
        self.assertEqual(result["bindings"], dict(subject="moon", relation="below", object="astronaut"))
        other = self.unit(vsa_dim=4096)
        np.testing.assert_array_equal(other.symbols.symbol("cat"), symbols.symbol("cat"))

    def test_sleep_updates_slow_memory_without_inventing_observations(self):
        unit = self.unit()
        self.feed(unit)
        before = unit.diagnostics()
        params = copy.deepcopy(unit.world_model.slow.core.p)
        fast = [copy.deepcopy(model.core.p) for model in unit.world_model.models]
        report = unit.sleep(12)
        self.assertEqual(report["cycles"], 12)
        self.assertTrue(any(np.any(params[k] != unit.world_model.slow.core.p[k]) for k in params))
        for name in ("steps", "transitions", "episodic_size", "world_updates", "affect", "timescales"):
            self.assertEqual(unit.diagnostics()[name], before[name])
        for model, snapshot in zip(unit.world_model.models, fast):
            for k in snapshot:
                np.testing.assert_array_equal(model.core.p[k], snapshot[k])
        self.assertEqual(unit.world_model.slow.steps, 0)
        self.assertEqual(len(unit.world_model.slow.calibration.scores), 0)
        size = len(unit.episodes)
        self.assertEqual(unit.dream(4).shape, (5, 2))
        self.assertEqual(len(unit.episodes), size)

    def test_temporal_hierarchy_goals_and_expiration(self):
        unit = self.unit()
        unit.perceive([0, 0])
        unit.set_goal([2, 2], duration=3)
        for _ in range(2):
            unit.act(action=[0, 0])
            unit.perceive([1, 1])
            unit.reconcile()
        traces = unit.temporal.traces[:, 0]
        self.assertTrue(np.all(traces[:-1] > traces[1:]))
        self.assertEqual(len(unit.temporal.goals), 1)
        unit.act(action=[0, 0])
        unit.perceive([1, 1])
        self.assertEqual(unit.temporal.goals, [])

    def test_workspace_competition_and_affect(self):
        unit = self.unit()
        unit.workspace.offer("urgent", {"message": "attend"}, 3.)
        state = unit.perceive([4, 4])
        self.assertEqual(state.focus["source"], "urgent")
        self.assertTrue(all(message == state.focus for message in unit.workspace.inboxes.values()))
        self.assertGreater(unit.affect.values["fear"], 0.)
        unit.workspace.inboxes["policy"]["payload"]["message"] = "changed"
        self.assertEqual(unit.workspace.focus["payload"]["message"], "attend")

    def test_meta_evaluation_is_prospective_and_bounded(self):
        unit = self.unit(meta_window=4)
        self.feed(unit, 4)
        original = unit.world_model.models[0].config.learning_rate
        report = unit.meta_update()
        self.assertEqual(report["status"], "started")
        self.assertEqual(unit.world_model.models[0].config.learning_rate, original)
        self.assertEqual(len(unit._trial["base_losses"]), 0)
        unit.act(action=[0.1, 0.2])
        result = 0.8 * unit.current_state + [0.035, 0.07]
        predictions = [w.predict(unit.current_state, [0.1, 0.2])[0] for w in unit._trial["models"]]
        unit.perceive(result)
        unit.reconcile()
        for prediction, losses in zip(predictions, unit._trial["losses"]):
            self.assertAlmostEqual(losses[0], np.mean((prediction - result) ** 2))
        self.feed(unit, 3)
        self.assertIsNone(unit._trial)
        self.assertEqual(len(unit.meta_history), 1)
        rate = unit.world_model.models[0].config.learning_rate
        self.assertGreaterEqual(rate, unit.config.min_learning_rate)
        self.assertLessEqual(rate, unit.config.max_learning_rate)
        self.assertEqual(unit.world_model.updates, unit.transitions)

    def test_meta_acceptance_does_not_learn_last_transition_twice(self):
        unit = self.unit(meta_window=4, meta_margin=0.)
        unit.perceive([0, 0])
        unit.meta_update()
        unit.world_model.predict = lambda s, a: (np.ones(2), 0., 1.)
        candidate = unit._trial["models"][0]
        candidate.predict = lambda s, a: (np.zeros(2), 0., 1.)
        for _ in range(4):
            unit.act(action=[0, 0])
            unit.perceive([0, 0])
            unit.reconcile()
        self.assertIs(unit.world_model, candidate)
        self.assertEqual(unit.world_model.updates, 4)
        self.assertIsNotNone(unit.meta_history[-1]["accepted_rate"])

    def test_social_learning_and_bounded_cultural_transmission(self):
        teacher, student = self.unit(), self.unit()
        student.perceive([0, 0])
        student.observe_peer("teacher", [0, 0], [1, 0], [0.35, 0], goal=[1, 0])
        self.assertEqual(student.transitions, 0)
        self.assertEqual(student.world_model.updates, 1)
        self.assertEqual(student.episodes[-1].source, "peer:teacher")
        np.testing.assert_array_equal(student.current_state, [0, 0])
        teacher.teach_rule("inverse", "above", "below", swap=True)
        teacher.teach_skill("push", [[0.5, 0.]], {"object": "box"})
        for artifact in teacher.export_culture():
            student.adopt_artifact(artifact)
        self.assertIsNotNone(student.symbols.infer("bird", "above", "tree"))
        self.assertEqual(student.culture["push"]["actions"], [[0.5, 0.]])
        for i in range(12):
            student.teach_rule(str(i), str(i), "related")
        self.assertLessEqual(len(student.culture), student.config.symbolic_capacity)
        self.assertLessEqual(len(student.symbols.rules), student.config.symbolic_capacity)
        with self.assertRaises(ValueError):
            student.adopt_artifact(dict(format="neuron-culture", version=1, name="bad", kind="code", code="print(1)"))

    def test_shared_goal_divides_actuators_in_planning(self):
        left, right = self.unit(), self.unit()
        for unit, name in ((left, "left"), (right, "right")):
            unit.perceive([0, 0])
            unit.coordinate([0.8, 0.8], ["right", "left"], name)
        a, b = left.imagine_futures(), right.imagine_futures()
        np.testing.assert_array_equal(a.actions[:, 1], 0)
        np.testing.assert_array_equal(b.actions[:, 0], 0)
        with self.assertRaises(ValueError):
            left.act(action=[0, 1])
        np.testing.assert_array_equal(np.array(left.coordination["mask"]) + right.coordination["mask"], [1, 1])

    def test_checkpoint_exact_resume_pending_action_trial_and_culture(self):
        unit = self.unit()
        self.feed(unit, 6)
        unit.sleep(3)
        unit.set_goal([0.6, -0.6], duration=100)
        unit.set_homeostasis([0, 0], [0.3, 0.7])
        unit.teach_rule("inverse", "above", "below", swap=True)
        unit.teach_skill("push", [[1, 0]], {"object": "box"})
        unit.perceive_scene({"object": "box"})
        unit.meta_update()
        unit.act(action=[0.2, -0.2])
        unit.perceive([0.3, -0.3])
        unit.act(action=[0.1, -0.1])
        with tempfile.TemporaryDirectory() as directory:
            path = Path(directory) / "cognitive.zip"
            unit.save(path)
            other = CognitiveUnit.load(path)
        self.assertEqual(unit.diagnostics(), other.diagnostics())
        self.assertEqual(unit.reconcile(), other.reconcile())
        for _ in range(10):
            for item in (unit, other):
                item.perceive(0.8 * item.current_state + 0.35 * item._awaiting["action"])
                item.reconcile()
            p, q = unit.imagine_futures(), other.imagine_futures()
            np.testing.assert_array_equal(p.actions, q.actions)
            self.assertEqual(p.score, q.score)
            np.testing.assert_array_equal(unit.act(p), other.act(q))
        self.assertEqual(unit.diagnostics(), other.diagnostics())
        for a, b in zip(unit.world_model.models, other.world_model.models):
            for key in a.core.p:
                np.testing.assert_array_equal(a.core.p[key], b.core.p[key])

    def test_corrupt_cognitive_checkpoint_rejected(self):
        unit = self.unit()
        self.feed(unit, 2)
        with tempfile.TemporaryDirectory() as directory:
            path = Path(directory) / "unit.zip"
            unit.save(path)
            with zipfile.ZipFile(path) as src:
                files = {name: src.read(name) for name in src.namelist()}
            metadata = json.loads(files["state.json"])
            metadata["current_state"] = [0, 0, 0]
            files["state.json"] = json.dumps(metadata).encode()
            with zipfile.ZipFile(path, "w") as out:
                for name, contents in files.items():
                    out.writestr(name, contents)
            with self.assertRaises(ValueError):
                CognitiveUnit.load(path)

    def test_bounded_memory_and_episode_reset(self):
        unit = self.unit(episodic_capacity=4)
        self.feed(unit, 10)
        self.assertEqual(len(unit.episodes), 4)
        unit.act(action=[0, 0])
        unit.reset_episode()
        self.assertIsNone(unit.current_state)
        self.assertIsNone(unit._awaiting)
        self.assertEqual(unit.transitions, 10)
        unit.perceive([7, 7])
        self.assertFalse(unit.reconcile()["learned"])
        self.assertEqual(unit.transitions, 10)

    def test_run_closes_loop_and_resumes_without_fake_transition(self):
        unit, env = self.unit(), ToyEnvironment(7)
        self.assertEqual(len(unit.run(env, steps=3)), 3)
        self.assertIsNone(unit._pending)
        self.assertIsNone(unit._awaiting)
        self.assertEqual(unit.transitions, 3)
        self.assertEqual(len(unit.run(env, steps=2)), 2)
        self.assertEqual(unit.transitions, 5)
        env.apply(unit.act(action=[0.1, 0.1]))
