    def test_stream_roundtrip_errors_and_resume_latest(self):
        with tempfile.TemporaryDirectory() as directory:
            arguments = ["stream", "--directory", directory, "--min-free-mb", "0"]
            code, output, errors = self.invoke(arguments,
                '{"x":[0.1,0.2],"y":1}\ninvalid\n{"op":"observe","x":[1,0]}\n')
            self.assertEqual(code, 0, errors)
            responses = [json.loads(line) for line in output.splitlines()]
            self.assertEqual([r["ok"] for r in responses], [True, False, True])
            code, output, errors = self.invoke(arguments + ["--resume-latest"],
                '{"op":"label","ticket":0,"y":0}\n')
            self.assertEqual(code, 0, errors)
            response = json.loads(output)
            self.assertEqual(response["line"], 4)
            self.assertEqual(response["result"]["step"], 2)
            with EventHistory(Path(directory) / "history.sqlite", min_free_mb=0) as history:
                self.assertTrue(history.verify()["ok"])
                model = _restore_bytes(Neuron, history.restore("model")[0])
                self.assertEqual(model.steps, 2)
                self.assertEqual(len(model.pending), 0)
            code, _, _ = self.invoke(arguments, '')
            self.assertEqual(code, 2)

    def test_stream_oversized_lines_preserved_and_next_request_survives(self):
        with tempfile.TemporaryDirectory() as directory:
            text = 'x' * 150 + '\n{"x":[1,0],"y":1}\n'
            code, output, errors = self.invoke(["stream", "--directory", directory,
                "--min-free-mb", "0", "--max-line-chars", "32"], text)
            self.assertEqual(code, 0, errors)
            responses = [json.loads(line) for line in output.splitlines()]
            self.assertFalse(responses[0]["ok"])
            self.assertTrue(responses[1]["ok"])
            with EventHistory(Path(directory) / "history.sqlite", min_free_mb=0) as history:
                restored = ''.join(e["payload"]["text"] for e in history.iter_events(kind="stream.input.chunk"))
                self.assertEqual(restored, text)

    def test_cognitive_stream_resume_pending_action(self):
        with tempfile.TemporaryDirectory() as directory:
            arguments = ["cognitive-stream", "--directory", directory, "--min-free-mb", "0"]
            code, output, errors = self.invoke(arguments,
                '{"op":"perceive","sensation":[0,0]}\n{"op":"act","action":[0.2,0]}\n')
            self.assertEqual(code, 0, errors)
            code, output, errors = self.invoke(arguments + ["--resume-latest"],
                '{"op":"perceive","sensation":[0.07,0]}\n{"op":"reconcile"}\n{"op":"reconcile"}\n')
            self.assertEqual(code, 0, errors)
            responses = [json.loads(line) for line in output.splitlines()]
            self.assertTrue(responses[1]["result"]["learned"])
            self.assertFalse(responses[2]["result"]["learned"])

    def test_history_cli_export_filters_and_verification(self):
        with tempfile.TemporaryDirectory() as directory:
            path = Path(directory) / "history.sqlite"
            export = Path(directory) / "events.jsonl"
            with EventHistory(path, min_free_mb=0) as history:
                history.append("test", "agent", {"a": "ação"})
                history.append("other", "agent", {})
            code, output, errors = self.invoke(["history", str(path), "--verify", "--export", str(export), "--kind", "test"])
            self.assertEqual(code, 0, errors)
            rows = [json.loads(line) for line in export.read_text().splitlines()]
