    def test_iter_run_is_lazy_and_yields_completed_transitions(self):
        unit = CognitiveTests().unit(planning_horizon=1, planning_candidates=2, planning_iterations=1)
        env = ToyEnvironment()
        iterator = unit.iter_run(env, sleep_every=2)
        self.assertEqual(unit.steps, 0)
        for number in range(1, 4):
            report = next(iterator)
            self.assertEqual(report["transitions"], number)
            self.assertIsNone(unit._awaiting)
            self.assertIsNone(unit._pending)
        iterator.close()
        self.assertEqual(unit.transitions, 3)
        stop = threading.Event()
        stop.set()
        self.assertEqual(list(unit.iter_run(env, stop_event=stop)), [])
        self.assertEqual(unit.transitions, 3)

