    def test_promotion_requires_both_prospective_gain_and_retention(self):
        from unittest.mock import patch
        for candidate_retention, expected in ((1.0, False), (0.05, True)):
            race = self.race(trial_generations=1)
            original_learn = race.candidate.learn_one
            def better_report(x, y):
                report = original_learn(x, y)
                return dataclasses.replace(report, loss=0.0)
            def retention(model, *_):
                return np.full(4, 0.1 if model is race.champion else candidate_retention)
            with patch.object(race.candidate, "learn_one", side_effect=better_report), patch.object(race, "_losses", side_effect=retention):
                report = race.step()
            self.assertEqual(report["comparison"]["promoted"], expected)
            self.assertEqual(race.promotions, int(expected))

