    def test_tool_policy_read_write_hash_and_path_escape(self):
        with tempfile.TemporaryDirectory() as d:
            root=Path(d)/'tools';tool=ToolHarness(ToolPolicy(root))
            with self.assertRaises(PermissionError):tool.run('files.write',dict(path='a.txt',text='hello'))
            with self.assertRaises(ValueError):tool.path('../secret')
            with self.assertRaises(ValueError):tool.path('/etc/passwd')
            outside=Path(d)/'outside';outside.mkdir();(root/'escape').symlink_to(outside,target_is_directory=True)
            with self.assertRaises(ValueError):tool.path('escape/test')
            tool.policy.allow_write=True;r=tool.run('files.write',dict(path='a.txt',text='hello'))['result']
            with self.assertRaises(ValueError):tool.run('files.write',dict(path='a.txt',text='overwrite'))
            tool.run('files.write',dict(path='a.txt',text='new',expected_sha256=r['sha256']))
            self.assertEqual(tool.run('files.read',dict(path='a.txt'))['result']['text'],'new')

