    def test_meta_apply_rollback_hashes_and_scope(self):
        from unittest.mock import patch
        from types import SimpleNamespace
        with tempfile.TemporaryDirectory() as d:
            source=Path(d)/'neuron.py';source.write_bytes(Path(__file__).read_bytes());original=source.read_bytes()
            editor=MetaProgrammer(source,Path(d)/'patches')
            kernel=next(n for n in ast.parse(original).body if isinstance(n,ast.FunctionDef) and n.name=='adaptive_kernel')
            current=ast.unparse(next(n.value for n in kernel.body if isinstance(n,ast.Return)))
            expression='x*(x+2)+1' if current==ast.unparse(ast.parse('(x+1)**2',mode='eval').body) else '(x+1)**2'
            report=editor.stage(expression);digest=report['candidate_sha256']
            with patch('subprocess.run',return_value=SimpleNamespace(returncode=0,stdout='OK',stderr='')):
                self.assertTrue(editor.apply(digest)['applied'])
            self.assertNotEqual(source.read_bytes(),original);editor.rollback(digest);self.assertEqual(source.read_bytes(),original)
            source.write_bytes(original+b'\n# concurrent edit\n')
            with self.assertRaisesRegex(ValueError,'Fonte mudou'):editor.apply(digest)

