    def test_meta_rejects_decorators_and_executable_kernel_body(self):
        with tempfile.TemporaryDirectory() as d:
            editor=MetaProgrammer(Path(__file__),Path(d));report=editor.stage('(x+1)**2')
            source=Path(report['candidate']).read_text();tree=ast.parse(source)
            target=next(n for n in tree.body if isinstance(n,ast.FunctionDef) and n.name=='adaptive_kernel')
            lines=source.splitlines(keepends=True)
            lines.insert(target.lineno-1,'@print("unexpected decorator")\n')
            tampered=''.join(lines);digest=hashlib.sha256(tampered.encode()).hexdigest()
            (Path(d)/(digest+'.py')).write_text(tampered)
            report['candidate_sha256']=digest;report['candidate']=str(Path(d)/(digest+'.py'))
            (Path(d)/(digest+'.json')).write_text(json.dumps(report))
            with self.assertRaisesRegex(ValueError,'decoradores'):editor.apply(digest)

    def test_swarm_expired_authenticated_message_is_rejected(self):
        protocol=SwarmProtocol('K'*32);wire=protocol.sign(dict(hi=1));wire['body']['utc']=time.time()-60
        raw=json.dumps(wire['body'],sort_keys=True,separators=(',',':'),allow_nan=False).encode()
        wire['mac']=hmac.new(protocol.key,raw,hashlib.sha256).hexdigest()
        with self.assertRaisesRegex(ValueError,'expirada'):protocol.verify(wire)

    def test_swarm_rejects_authentic_but_wrong_mathematical_answer(self):
        import socketserver
        key='K'*32;protocol=SwarmProtocol(key)
        class LyingPeer(socketserver.StreamRequestHandler):
            def handle(self):
                payload=protocol.verify(json.loads(self.rfile.readline(65537)));request=payload['request']
                receipt=dict(operation=request['op'],result={'$map':[[7,1],[13,2]]})
                reply=protocol.sign(dict(job=payload['job'],request_sha256=hashlib.sha256(json.dumps(request,sort_keys=True).encode()).hexdigest(),receipt=receipt))
                self.wfile.write(json.dumps(reply).encode()+b'\n')
        server=socketserver.TCPServer(('127.0.0.1',0),LyingPeer);thread=threading.Thread(target=server.serve_forever,daemon=True);thread.start()
        try:
            client=SwarmClient(['127.0.0.1:'+str(server.server_address[1])],key)
            with self.assertRaisesRegex(ArithmeticError,'verificador'):client.map([dict(op='nt.factor',args=[91])])
        finally:server.shutdown();server.server_close();thread.join(timeout=2)


