class EightIntegrationTests(unittest.TestCase):
    def core(self,budget=2,constitution=False):
        return NativeSeq2Seq(LabConfig(agents=1,model='numpy:tiny',input_tokens=16,output_tokens=4,thought_budget=budget,constitutional_projection=constitution),dimension=8)

    def test_latent_bptt_matches_all_parameter_finite_differences(self):
        core=self.core();bridge=core.new_bridge(0);enc=core.encode('ab');context=np.linspace(-.2,.2,48);loss,grad=core.loss_grad(enc,bridge,context,'cd')
        self.assertTrue(math.isfinite(loss));rng=np.random.default_rng(801)
        for key in ('E','A','D','C','O','b','B'):
            direction=rng.normal(size=bridge.arrays[key].shape);direction/=np.linalg.norm(direction);initial=bridge.arrays[key].copy();epsilon=1e-5
            bridge.arrays[key]=initial+epsilon*direction;plus=core.loss_grad(enc,bridge,context,'cd')[0]
            bridge.arrays[key]=initial-epsilon*direction;minus=core.loss_grad(enc,bridge,context,'cd')[0];bridge.arrays[key]=initial
            self.assertAlmostEqual((plus-minus)/(2*epsilon),float(np.sum(grad[key]*direction)),delta=2e-7,msg=key)

    def test_zero_budget_uses_original_decoder_equation(self):
        core=self.core(0);b=core.new_bridge(0);enc=core.encode('a');states=core._encoder(enc['ids'],b.arrays);h=states[-1];w=core._softmax(states@h/math.sqrt(8));expected=np.tanh(b.arrays['E'][0]+b.arrays['D']@h+b.arrays['C']@(w@states))
        records=core._forward(enc,b.arrays,np.zeros(48),[3])[2];np.testing.assert_array_equal(records[0][2],expected);self.assertEqual(core.signature,core.base_signature)

