        proof=symbolic_equivalence_check(old,'x*x+2*x+1');self.assertTrue(verify_symbolic_equivalence(proof));self.assertFalse(proof['ieee754_proved']);self.assertFalse(proof['clock_speed_proved'])
        self.assertTrue(symbolic_equivalence_check('0.1*x+0.2*x','3*x/10')['proved'])

