                report=activate_live_source(path,digest,lab.history);self.assertFalse(report['restart_required']);self.assertEqual(adaptive_kernel(3),16);self.assertIs(lab.agents[0].bridge,bridge)
                path.write_text('def adaptive_kernel(x):\n    return x+9\n')
