def main(argv: Iterable[str] | None = None) -> int:
    effective = list(argv) if argv is not None else sys.argv[1:]
    if effective == ['_kernel-benchmark']:
        ns=[];checksum=0.
        for repeat in range(7):
            started=time.perf_counter_ns()
            for i in range(20000):checksum+=adaptive_kernel((i%200-100)*.01)
            ns.append((time.perf_counter_ns()-started)/20000)
        print(json.dumps(dict(median_ns_per_call=sorted(ns)[len(ns)//2],checksum=checksum)));return 0
    if effective == ['_kernel-worker']:
        values=json.loads(sys.stdin.read(65537))
        if not isinstance(values,list) or len(values)>512:raise ValueError('Pontos inválidos')
        print(json.dumps([adaptive_kernel(float(x)) for x in values],allow_nan=False));return 0
    if effective and effective[0]=='--swarm':effective[0]='swarm'
    argv=effective
    if effective == ["_math-worker"]:
        return math_worker_main()
    parser = argparse.ArgumentParser(description="NEURON 8 · Computação latente, provas restritas, currículo e BPE",
                                     formatter_class=argparse.RawDescriptionHelpFormatter)
    parser.add_argument("--version", action="version", version=__version__)
    parser.add_argument("--menu",action="store_true",help="Abre o laboratório clássico em vez da conversa")
    commands = parser.add_subparsers(dest="command")
    advanced_commands=add_advanced_commands(commands)
    eight_commands=add_eight_commands(commands)
    agent_command=commands.add_parser('agent',help='Conversa natural local com ferramentas autorizadas')
    agent_command.add_argument('--directory',type=Path,default=Path('neuron_data/sessao'))
    agent_command.add_argument('--model',default='compact:pt')
    agent_command.add_argument('--thought-budget',type=int,default=0)
    agent_command.add_argument('--constitution',action='store_true')
    agent_command.add_argument('--effort',choices=('baixo','medio','alto','muito_alto','maximo','personalizado'),default='medio')
    agent_command.add_argument('--effort-steps',type=int,default=32)
    agent_command.add_argument('--effort-seconds',type=float,default=20.)
    agent_command.add_argument('--reasoning',action=argparse.BooleanOptionalAction,default=True)
    dataset_command=commands.add_parser('dataset',help='Treino local JSONL com holdout, retenção e crescimento RNN opcional')
    dataset_command.add_argument('path',type=Path)
    dataset_command.add_argument('--directory',type=Path,default=Path('neuron_data/sessao'))
    dataset_command.add_argument('--model',default='compact:pt')
    dataset_command.add_argument('--epochs',type=int,default=2)
    dataset_command.add_argument('--seconds',type=float,default=30.)
    dataset_command.add_argument('--grow',action='store_true')
    import_command=commands.add_parser('import-data',help='Importa documentos/datasets para memória compacta; PDF sem OCR')
    import_command.add_argument('path',type=Path)
    import_command.add_argument('--directory',type=Path,default=Path('neuron_data/sessao'))
    cognitive = commands.add_parser("cognitive-demo", help="Agente ativo em ambiente NumPy controlável")
    cognitive.add_argument("--steps", type=int, default=160)
    cognitive.add_argument("--seed", type=int, default=42)
    cognitive.add_argument("--json", type=Path)
    demo = commands.add_parser("demo", help="Fluxo A → B → A com avaliação prequencial")
    demo.add_argument("--steps", type=int, default=1600)
    demo.add_argument("--seed", type=int, default=42)
    demo.add_argument("--json", type=Path, help="Salva métricas JSON neste caminho")
    bench = commands.add_parser("benchmark", help="Ablações pareadas em múltiplas seeds")
    bench.add_argument("--steps", type=int, default=1200)
    bench.add_argument("--seeds", type=int, default=3)
    bench.add_argument("--json", type=Path)
    commands.add_parser("selftest", help="Testes matemáticos e de integração")
    stream = commands.add_parser("stream", help="Aprendizado em JSON Lines via stdin")
    stream.add_argument("--inputs", type=int, default=2)
    stream.add_argument("--classes", type=int, default=2, help="Classes ou saídas de regressão")
    stream.add_argument("--task", choices=("classification", "regression"), default="classification")
    stream.add_argument("--seed", type=int, default=42)
    stream.add_argument("--resume", type=Path)
    stream.add_argument("--checkpoint", type=Path)
    cognitive_stream = commands.add_parser("cognitive-stream", help="Ciclo cognitivo JSONL com histórico e retomada")
    cognitive_stream.add_argument("--sensors", type=int, default=2)
    cognitive_stream.add_argument("--motors", type=int, default=2)
    cognitive_stream.add_argument("--seed", type=int, default=42)
    cognitive_stream.add_argument("--resume", type=Path)
    cognitive_stream.add_argument("--checkpoint", type=Path)
    for command in (stream, cognitive_stream):
        command.add_argument("--resume-latest", action="store_true", help="Retoma o último checkpoint do diretório")
        command.add_argument("--max-line-chars", type=int, default=1048576)
    race = commands.add_parser("arms-race", help="Corrida coevolutiva entre desafios e aprendizes")
    race.add_argument("--generations", type=int, default=20, help="Gerações adicionais; 0 executa continuamente")
    race.add_argument("--seed", type=int, default=42)
    race.add_argument("--population", type=int, default=8)
    race.add_argument("--elite", type=int, default=2)
    race.add_argument("--train-size", type=int, default=48)
    race.add_argument("--probe-size", type=int, default=24)
    race.add_argument("--resume-latest", action="store_true")
    race.add_argument("--checkpoint-every", type=int, default=1)
    race.add_argument("--max-seconds", type=float, default=0, help="Limite verificado entre gerações; 0 desliga")
    race.add_argument("--rate", type=float, default=1, help="Máximo de gerações/s; 0 sem pausa")
    for command, default in ((stream, "runs/stream"), (cognitive_stream, "runs/cognitive-stream"),
                             (race, "runs/arms-race"), (cognitive, "runs/cognitive-demo"),
                             (demo, "runs/demo"), (bench, "runs/benchmark")):
        command.add_argument("--directory", type=Path, default=Path(default))
        command.add_argument("--min-free-mb", type=float, default=64)
    history = commands.add_parser("history", help="Consulta, verifica e exporta eventos sem carregar tudo na RAM")
    history.add_argument("database", type=Path)
    history.add_argument("--verify", action="store_true")
    history.add_argument("--export", type=Path)
    history.add_argument("--after", type=int, default=0)
    history.add_argument("--kind")
    history.add_argument("--limit", type=int, default=50, help="0 mostra todos os eventos")
    commands.add_parser("menu", help="Menu interativo de todos os modos")
    laboratory_commands = {}
    for name, description in (("chat", "Conversa com NEURON via Encoder–Decoder integrado"),
            ("society", "Instâncias independentes conversando e aprendendo"),
            ("lab", "Observatório visual local embutido no arquivo"),
            ("inspect-hf", "Inspeciona Encoder–Decoder do próprio NEURON")):
        command = commands.add_parser(name, help=description)
        command.add_argument("--directory", type=Path, default=Path("neuron_data/sessao"))
        command.add_argument("--model", default="google/flan-t5-small" if name=="inspect-hf" else "compact:pt")
        command.add_argument("--instances", type=int, default=1 if name=="chat" else 3)
        command.add_argument("--offline", action="store_true")
        command.add_argument("--thought-budget",type=int,default=0)
        command.add_argument("--inference-seconds",type=float,default=5.)
        command.add_argument("--constitution",action="store_true")
        command.add_argument("--device", choices=("cpu","cuda","mps"), default="cpu")
        command.add_argument("--max-input-tokens", type=int, default=128)
        command.add_argument("--max-new-tokens", type=int, default=48)
        command.add_argument("--revision", default="main")
        laboratory_commands[name] = command
    laboratory_commands["lab"].add_argument("--port", type=int, default=8765)
    laboratory_commands["lab"].add_argument("--open", action="store_true")
    laboratory_commands["lab"].add_argument("--load-model", action="store_true")
    laboratory_commands["lab"].add_argument("--curriculum",action="store_true")
    laboratory_commands["lab"].add_argument("--teacher",action="store_true")
    laboratory_commands["society"].add_argument("--rounds", type=int, default=3)
    laboratory_commands["society"].add_argument("--topic", default="Como reduzir o esquecimento?")
    laboratory_commands["inspect-hf"].add_argument("--text", default="Olá, vamos aprender juntos?")
    downloader = commands.add_parser("download-model", help="Baixa apenas um Encoder–Decoder compatível")
    downloader.add_argument("model", nargs="?", default="google/flan-t5-small")
    downloader.add_argument("--destination", type=Path, default=Path("neuron_data/modelos/flan-t5-small"))
    downloader.add_argument("--revision", default="main")
    installer = commands.add_parser("install", help="Instala dependências pelo Python em uso")
    installer.add_argument("--core-only", action="store_true")
    formal_commands = {'math','math-catalog','omnimat-selftest','simulate','categories','jit','math-arms-race'}
    math_parser = commands.add_parser('math',help='Calculadora OMNIMAT com resultados tipados e verificação')
    math_parser.add_argument('operation')
    math_parser.add_argument('arguments',nargs='?',default='[]',help='Lista JSON de argumentos')
    math_parser.add_argument('--kwargs',default='{}')
    math_parser.add_argument('--native',action='store_true',help='JIT explícito para operações nat/sym')
    math_parser.add_argument('--json-output',action='store_true')
    math_parser.add_argument('--timeout',type=float,default=8.)
    math_parser.add_argument('--directory',type=Path,default=Path('neuron_data/matematica'))
    inventory=commands.add_parser('math-catalog',help='Catálogo completo das 39 áreas OMNIMAT')
    inventory.add_argument('--area')
    commands.add_parser('omnimat-selftest',help='Autotestes originais OMNIMAT incorporados')
    physics=commands.add_parser('simulate',help='Simulações matemáticas com comparação/refinamento')
    physics.add_argument('scenario',choices=('heat','wave','lorenz','geometry'))
    physics.add_argument('--parameters',default='{}')
    physics.add_argument('--agent',default='NEURON-1')
    physics.add_argument('--directory',type=Path,default=Path('neuron_data/sessao'))
    categories=commands.add_parser('categories',help='Categorias finitas, Yoneda e adjunções fornecidas explicitamente')
    categories.add_argument('--spec',default='{}')
    categories.add_argument('--agent',default='NEURON-1')
    categories.add_argument('--directory',type=Path,default=Path('neuron_data/sessao'))
    compiler=commands.add_parser('jit',help='Compila expressão em x86-64 e compara os valores em processo separado')
    compiler.add_argument('expression')
    compiler.add_argument('--points',default='[-1,0,0.25,1,2]')
    compiler.add_argument('--timeout',type=float,default=8.)
    compiler.add_argument('--json-output',action='store_true')
    compiler.add_argument('--directory',type=Path,default=Path('neuron_data/jit'))
    formal_race=commands.add_parser('math-arms-race',help='Coevolução de tarefas SAT/grafos com soluções conferidas')
    formal_race.add_argument('--rounds',type=int,default=10)
    formal_race.add_argument('--directory',type=Path,default=Path('neuron_data/corrida_formal'))
    inspect = commands.add_parser("inspect", help="Inspeciona checkpoint sem treinar")
    inspect.add_argument("checkpoint", type=Path)
    seed_commands=add_seed_commands(commands)
    args = parser.parse_args(list(argv) if argv is not None else None)
    if args.menu:
        if args.command is not None:parser.error('--menu não aceita subcomando')
        return neuron_menu()
    try:
        if args.command is None:return run_autonomous_agent(Path('neuron_data/sessao'),LabConfig(agents=1,model='compact:pt'))
        if args.command=='import-data':
            with NeuronLaboratory(args.directory,LabConfig(agents=1,model='compact:pt')) as lab:
                lab.load_model(offline=True);result=import_agent_data(lab,'NEURON-1',args.path);print('Importação concluída: '+str(result['records'])+' blocos/exemplos. Nenhuma melhora foi presumida.')
            return 0
        if args.command=='dataset':
            with NeuronLaboratory(args.directory,LabConfig(agents=1,model=args.model)) as lab:
                lab.load_model(offline=True);print(dataset_human_report(train_agent_dataset(lab,'NEURON-1',args.path,epochs=args.epochs,grow=args.grow,seconds=args.seconds)))
            return 0
        if args.command=='agent':return run_autonomous_agent(args.directory,LabConfig(agents=1,model=args.model,thought_budget=args.thought_budget,constitutional_projection=args.constitution,reasoning_effort=args.effort,reasoning_visible=args.reasoning,reasoning_custom_budget=args.effort_steps,reasoning_custom_seconds=args.effort_seconds))
        if args.command in eight_commands:return run_eight_cli(args)
        if args.command in advanced_commands:return run_advanced_cli(args)
        if args.command in seed_commands:return run_seed_cli(args)
        if args.command in formal_commands:
            return run_math_cli(args)
        if args.command == "menu":
            return neuron_menu()
        if args.command == "install":
            install_neuron_dependencies(not args.core_only)
            return 0
        if args.command == "download-model":
            download_encoder_decoder(args.model, args.destination, revision=args.revision)
            return 0
        if args.command in laboratory_commands:
            cfg = LabConfig(agents=args.instances, model=args.model, device=args.device,
                input_tokens=args.max_input_tokens, output_tokens=args.max_new_tokens, revision=args.revision,thought_budget=args.thought_budget,inference_seconds=args.inference_seconds,constitutional_projection=args.constitution)
            if args.command == "chat":
                return run_neuron_chat(args.directory, cfg, offline=args.offline)
            if args.command == "society":
                return run_social_console(args.directory, cfg, rounds=args.rounds, topic=args.topic, offline=args.offline)
            if args.command == "lab":
                return run_lab_dashboard(args.directory, cfg, port=args.port, open_browser=args.open,
                    load_model=args.load_model, offline=args.offline,curriculum=args.curriculum,teacher=args.teacher)
            with NeuronLaboratory(args.directory, cfg) as lab_session:
                lab_session.load_model(offline=args.offline)
                lab_session.reply("NEURON-1", args.text)
                print(json.dumps(lab_session.inspect_encoder_decoder("NEURON-1"),ensure_ascii=False,indent=2))
            return 0
        if args.command == "selftest":
            suite = unittest.TestSuite(unittest.defaultTestLoader.loadTestsFromTestCase(case)
                                       for case in (NeuronTests, CognitiveTests, EvolutionTests, LaboratoryTests, FormalIntegrationTests, SeedIntegrationTests, SevenIntegrationTests, EightIntegrationTests, AgentBootTests))
            return 0 if unittest.TextTestRunner(verbosity=2).run(suite).wasSuccessful() else 1
        if args.command == "cognitive-demo":
            result = run_logged_experiment(args)
            print(json.dumps(jsonable(result), indent=2, ensure_ascii=False, allow_nan=False))
        elif args.command == "demo":
            result = run_logged_experiment(args)
        elif args.command == "benchmark":
            result = run_logged_experiment(args)
            print(json.dumps(jsonable(result["summary"]), indent=2, allow_nan=False))
        elif args.command in ("stream", "cognitive-stream"):
            return run_persistent_stream(args)
        elif args.command == "arms-race":
            return run_arms_race(args)
        elif args.command == "history":
            return run_history(args)
        elif args.command == "inspect":
            print(json.dumps(inspect_checkpoint(args.checkpoint), indent=2, allow_nan=False))
            return 0
        else:
            parser.error("Comando desconhecido")
        if args.json:
            args.json.parent.mkdir(parents=True, exist_ok=True)
            args.json.write_text(json.dumps(jsonable(result), indent=2, allow_nan=False), encoding="utf-8")
        return 0
    except (ValueError, OSError, KeyError, RuntimeError, FloatingPointError, sqlite3.Error,
            zipfile.BadZipFile, subprocess.SubprocessError) as error:
        print(f"Erro: {error}", file=sys.stderr)
        return 2


if __name__ == "__main__":
    raise SystemExit(main())
